    /**
     * @return array<string, mixed>
     */
    public function selectedScriptInventory(?string $repoRoot = null): array
    {
        $coverage = $this->runnerCoverageAudit();
        $wildcards = $this->wildcardExpansionPlan($repoRoot);
        $root = $repoRoot ?? dirname(__DIR__, 3);
        $relativeTestDirectory = '.upstream-cache/libsqlite/test';
        $testDirectory = $root . '/' . $relativeTestDirectory;
        $testDirectoryReady = is_dir($testDirectory);

        $resolved = [];
        $missing = [];
        $invalid = [];

        foreach ($coverage['selected_scripts'] as $script) {
            if (!is_string($script) || !preg_match('/^[A-Za-z0-9_.?-]+\.test$/', $script)) {
                $invalid[] = (string) $script;
                continue;
            }

            $path = $testDirectory . '/' . $script;
            if (!$testDirectoryReady || !is_file($path)) {
                $missing[] = $script;
                continue;
            }

            $resolved[$script] = [
                'script' => $script,
                'source' => $relativeTestDirectory . '/' . $script,
                'bytes' => filesize($path) ?: 0,
                'from' => 'selected-runner-history',
            ];
        }

        foreach ($wildcards['expanded'] ?? [] as $pattern => $scripts) {
            if (!is_string($pattern) || !is_array($scripts)) {
                continue;
            }

            foreach ($scripts as $script) {
                if (!is_string($script) || !preg_match('/^[A-Za-z0-9_.?-]+\.test$/', $script)) {
                    $invalid[] = (string) $script;
                    continue;
                }

                $path = $testDirectory . '/' . $script;
                if (!is_file($path)) {
                    $missing[] = $script;
                    continue;
                }

                $resolved[$script] = [
                    'script' => $script,
                    'source' => $relativeTestDirectory . '/' . $script,
                    'bytes' => filesize($path) ?: 0,
                    'from' => 'wildcard-pattern:' . $pattern,
                ];
            }
        }

        ksort($resolved);
        $missing = array_values(array_unique($missing));
        sort($missing);
        $invalid = array_values(array_unique($invalid));
        sort($invalid);

        $requestedCount = (int) $coverage['selected_script_count'] + (int) $wildcards['expanded_script_count'];
        $blocked = !$testDirectoryReady || $missing !== [] || $invalid !== [] || ($wildcards['status'] ?? null) === 'blocked-needs-hydrated-test-dir';

        return [
            'status' => $blocked ? 'blocked' : 'ready',
            'test_directory' => $relativeTestDirectory,
            'test_directory_ready' => $testDirectoryReady,
            'requested_selected_script_count' => (int) $coverage['selected_script_count'],
            'requested_wildcard_pattern_count' => (int) $coverage['pattern_script_count'],
            'requested_expanded_wildcard_script_count' => (int) $wildcards['expanded_script_count'],
            'requested_total_script_count' => $requestedCount,
            'resolved_script_count' => count($resolved),
            'missing_script_count' => count($missing),
            'invalid_script_count' => count($invalid),
            'resolved_scripts' => array_values($resolved),
            'missing_scripts' => $missing,
            'invalid_scripts' => $invalid,
            'wildcard_status' => $wildcards['status'] ?? 'unknown',
            'next_gate' => $blocked
                ? 'hydrate .upstream-cache/libsqlite/test and resolve every selected or wildcard-expanded .test file before launching broad all/release runners'
                : 'use the resolved script inventory as the concrete focused-suite denominator for reruns and all/release handoff review',
            'dependency_closure' => 'no new support component needed; selected-script inventory reads hydrated SQLite test sources only',
        ];
    }

    /**
     * @param list<string> $acceptedHeads
     * @return array<string, mixed>
     */
    public function releaseRunnerAcceptedHeadBurnup(
        array $acceptedHeads,
        ?string $repoRoot = null,
        ?string $artifactDirectory = null,
        string $processSnapshot = '',
        int $jobs = 1
    ): array {
        if ($jobs < 1) {
            throw new \InvalidArgumentException('SQLite release runner burnup jobs must be at least 1');
        }

        $heads = [];
        foreach ($acceptedHeads as $head) {
            if (!is_string($head) || trim($head) === '') {
                throw new \InvalidArgumentException('SQLite release runner burnup requires non-empty accepted repository HEAD values');
            }
            $heads[] = trim($head);
        }
        if ($heads === []) {
            throw new \InvalidArgumentException('SQLite release runner burnup requires at least one accepted repository HEAD');
        }

        $root = $repoRoot ?? dirname(__DIR__, 3);
        $artifactRoot = $artifactDirectory ?? $root . '/.tmux-team/tmp/sqlite-runner-artifacts';
        $hydration = $this->upstreamRunnerHydrationGate($jobs, $root);
        $commandManifest = $this->fullSuiteCommandManifest($jobs, $root);
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $records = [];
        $countableHeads = [];
        $missingHeads = [];
        foreach ($heads as $index => $head) {
            $provenance = $this->acceptedHeadArtifactProvenanceDirectoryRecord(
                $artifactRoot,
                $head,
                $processSnapshot
            );
            $count = (int) ($provenance['current_accepted_count'] ?? 0);
            $records[] = [
                'head' => $head,
                'index' => $index,
                'status' => $count > 0 ? 'countable-artifact-present' : 'missing-countable-artifact',
                'current_accepted_count' => $count,
                'blocked_count' => (int) ($provenance['blocked_count'] ?? 0),
                'artifact_count' => (int) ($provenance['artifact_count'] ?? 0),
                'next_gate' => $provenance['next_gate'] ?? null,
            ];

            if ($count > 0) {
                $countableHeads[] = $head;
            } else {
                $missingHeads[] = $head;
            }
        }

        $prefixCountable = 0;
        foreach ($records as $record) {
            if (($record['status'] ?? null) !== 'countable-artifact-present') {
                break;
            }
            $prefixCountable++;
        }

        $firstMissingHead = $missingHeads[0] ?? null;
        $blockers = [];
        if ($firstMissingHead !== null) {
            $blockers[] = [
                'id' => 'next-accepted-artifact-missing',
                'evidence' => 'no zero-error bounded runner artifact matches the next uncounted accepted source',
                'head' => $firstMissingHead,
            ];
        }
        if (($hydration['status'] ?? null) !== 'hydrated') {
            $blockers[] = [
                'id' => 'runner-hydration-incomplete',
                'evidence' => (string) ($hydration['missing_count'] ?? 0) . ' runner inputs are missing',
                'missing' => is_array($hydration['missing'] ?? null) ? $hydration['missing'] : [],
            ];
        }
        if (($commandManifest['status'] ?? null) !== 'ready') {
            $blockers[] = [
                'id' => 'command-manifest-blocked',
                'evidence' => (string) ($commandManifest['blocked_command_count'] ?? 0) . ' release/upstream commands are blocked',
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
                'active_tiers' => is_array($active['active_tiers'] ?? null) ? $active['active_tiers'] : [],
            ];
        }

        $allCountable = count($countableHeads) === count($heads);
        $readyForNext = !$allCountable
            && $prefixCountable === count($countableHeads)
            && ($hydration['status'] ?? null) === 'hydrated'
            && ($commandManifest['status'] ?? null) === 'ready'
            && ($active['status'] ?? null) === 'clear';

        $status = 'blocked';
        if ($allCountable) {
            $status = 'all-accepted-heads-countable';
        } elseif ($readyForNext) {
            $status = 'ready-for-next-accepted-head-runner';
        }

        return [
            'status' => $status,
            'artifact_directory' => $artifactRoot,
            'jobs' => $jobs,
            'head_count' => count($heads),
            'countable_head_count' => count($countableHeads),
            'missing_head_count' => count($missingHeads),
            'prefix_countable_head_count' => $prefixCountable,
            'burnup_percent' => round((count($countableHeads) / count($heads)) * 100, 2),
            'countable_heads' => $countableHeads,
            'missing_heads' => $missingHeads,
            'next_missing_head' => $firstMissingHead,
            'ready_to_launch_next_guarded_runner' => $readyForNext,
            'hydration_status' => $hydration['status'] ?? 'unknown',
            'command_manifest_status' => $commandManifest['status'] ?? 'unknown',
            'command_count' => (int) ($commandManifest['command_count'] ?? 0),
            'runnable_command_count' => (int) ($commandManifest['runnable_command_count'] ?? 0),
            'blocked_command_count' => (int) ($commandManifest['blocked_command_count'] ?? 0),
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'records' => $records,
            'counts_as_release_parity' => $allCountable,
            'next_gate' => match ($status) {
                'all-accepted-heads-countable' => 'record the burnup as complete only after manifest/status also names the countable accepted-HEAD artifacts',
                'ready-for-next-accepted-head-runner' => 'launch at most one guarded runner for the next missing accepted source, then count only a zero-error artifact with matching provenance',
                default => 'preserve counted accepted-head artifacts and resolve hydration, command-manifest, or duplicate-runner blockers before launching another broad runner',
            },
            'dependency_closure' => 'no new support component needed; current-accepted-head burnup composes accepted-head artifact provenance, runner hydration, command manifest, and duplicate-runner gates only',
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public function releaseRunnerSuiteMap(
        string $currentAcceptedHead,
        string $nextAcceptedHead,
        ?string $repoRoot = null,
        ?string $artifactDirectory = null,
        string $processSnapshot = '',
        int $jobs = 2
    ): array {
        if ($currentAcceptedHead === '' || $nextAcceptedHead === '') {
            throw new \InvalidArgumentException('Current and next accepted repository HEAD values are required');
        }
        if ($jobs < 1) {
            throw new \InvalidArgumentException('SQLite release-runner suite map jobs must be at least 1');
        }

        $root = $repoRoot ?? dirname(__DIR__, 3);
        $base = $this->releaseRunnerAcceptedHeadMap(
            $currentAcceptedHead,
            $nextAcceptedHead,
            $root,
            $artifactDirectory,
            $processSnapshot,
            $jobs
        );
        $readiness = $this->fullSuiteReadinessRecord($jobs, $root);
        $commandManifest = $this->fullSuiteCommandManifest($jobs, $root);
        $selected = $this->selectedScriptInventory($root);
        $wildcards = $this->wildcardExpansionPlan($root);
        $permutations = $this->permutationSuiteMap($root);

        $readyIds = [];
        foreach ($readiness['ready'] ?? [] as $ready) {
            if (is_array($ready) && is_string($ready['id'] ?? null)) {
                $readyIds[] = $ready['id'];
            }
        }

        $blockedIds = [];
        foreach ($readiness['blocked'] ?? [] as $blocked) {
            if (is_array($blocked) && is_string($blocked['id'] ?? null)) {
                $blockedIds[] = $blocked['id'];
            }
        }

        $suiteMapBlocked = [];
        if (($selected['status'] ?? null) !== 'ready') {
            $suiteMapBlocked[] = 'selected-script-inventory';
        }
        if (!in_array(($wildcards['status'] ?? null), ['ready', 'complete-no-wildcards'], true)) {
            $suiteMapBlocked[] = 'wildcard-expansion';
        }
        if (($permutations['status'] ?? null) !== 'ready') {
            $suiteMapBlocked[] = 'permutation-suite-map';
        }
        if (($commandManifest['status'] ?? null) !== 'ready') {
            $suiteMapBlocked[] = 'command-manifest';
        }
        if (($base['active_runner_status'] ?? null) !== 'clear') {
            $suiteMapBlocked[] = 'duplicate-broad-runner-active';
        }

        $status = 'blocked';
        if (($base['status'] ?? null) === 'next-artifact-already-countable') {
            $status = 'next-artifact-already-countable';
        } elseif (($base['current_artifact_count'] ?? 0) > 0 && ($base['next_artifact_count'] ?? 0) === 0 && $suiteMapBlocked === []) {
            $status = 'ready-current-to-next-suite-map';
        } elseif (($base['current_artifact_count'] ?? 0) > 0) {
            $status = 'current-artifact-preserved-suite-map-blocked';
        }

        return [
            'status' => $status,
            'current_accepted_head' => $currentAcceptedHead,
            'next_accepted_head' => $nextAcceptedHead,
            'jobs' => $jobs,
            'upstream_map_status' => $base['status'] ?? 'unknown',
            'current_artifact_count' => (int) ($base['current_artifact_count'] ?? 0),
            'next_artifact_count' => (int) ($base['next_artifact_count'] ?? 0),
            'active_runner_status' => $base['active_runner_status'] ?? 'unknown',
            'active_runner_count' => (int) ($base['active_runner_count'] ?? 0),
            'command_manifest_status' => $commandManifest['status'] ?? 'unknown',
            'command_count' => (int) ($commandManifest['command_count'] ?? 0),
            'runnable_command_count' => (int) ($commandManifest['runnable_command_count'] ?? 0),
            'blocked_command_count' => (int) ($commandManifest['blocked_command_count'] ?? 0),
            'ready_gate_ids' => $readyIds,
            'blocked_gate_ids' => $blockedIds,
            'suite_map_blockers' => $suiteMapBlocked,
            'suite_map_blocker_count' => count($suiteMapBlocked),
            'selected_script_status' => $selected['status'] ?? 'unknown',
            'selected_requested_count' => (int) ($selected['requested_selected_script_count'] ?? 0),
            'selected_resolved_count' => (int) ($selected['resolved_script_count'] ?? 0),
            'selected_missing_count' => (int) ($selected['missing_script_count'] ?? 0),
            'wildcard_status' => $wildcards['status'] ?? 'unknown',
            'wildcard_pattern_count' => (int) ($wildcards['pattern_count'] ?? 0),
            'wildcard_expanded_script_count' => (int) ($wildcards['expanded_script_count'] ?? 0),
            'permutation_status' => $permutations['status'] ?? 'unknown',
            'permutation_mapped_count' => (int) ($permutations['mapped_suite_count'] ?? 0),
            'permutation_unmapped_count' => (int) ($permutations['unmapped_suite_count'] ?? 0),
            'counts_current_artifact_only' => (bool) ($base['counts_current_artifact_only'] ?? false),
            'ready_to_launch_next_guarded_runner' => $status === 'ready-current-to-next-suite-map',
            'next_gate' => match ($status) {
                'ready-current-to-next-suite-map' => 'launch at most one guarded next-source runner using the concrete selected, wildcard-expanded, permutation, and release-tier command map',
                'next-artifact-already-countable' => 'record the next-source artifact and suppress duplicate release/all runner launch',
                'current-artifact-preserved-suite-map-blocked' => 'preserve current accepted artifact evidence and resolve suite-map blockers before launching a next-source runner',
                default => 'do not count release/all movement until current artifact provenance and current-to-next suite map gates are explicit',
            },
            'dependency_closure' => 'no new support component needed; current-to-next suite map composes existing artifact provenance, command-manifest, selected-script, wildcard, and permutation-suite gates only',
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public function releaseRunnerGapLedger(
        string $currentAcceptedHead,
        string $nextAcceptedHead,
        ?string $repoRoot = null,
        ?string $artifactDirectory = null,
        string $processSnapshot = '',
        int $jobs = 2
    ): array {
        if ($currentAcceptedHead === '' || $nextAcceptedHead === '') {
            throw new \InvalidArgumentException('Current and next accepted repository HEAD values are required for release-runner gap ledger evidence');
        }
        if ($jobs < 1) {
            throw new \InvalidArgumentException('SQLite release-runner gap ledger jobs must be at least 1');
        }

        $root = $repoRoot ?? dirname(__DIR__, 3);
        $artifactRoot = $artifactDirectory ?? $root . '/.tmux-team/tmp/sqlite-runner-artifacts';
        $current = $this->acceptedHeadArtifactProvenanceDirectoryRecord(
            $artifactRoot,
            $currentAcceptedHead,
            $processSnapshot
        );
        $next = $this->acceptedHeadArtifactProvenanceDirectoryRecord(
            $artifactRoot,
            $nextAcceptedHead,
            $processSnapshot
        );
        $hydration = $this->upstreamRunnerHydrationGate($jobs, $root);
        $commandManifest = $this->fullSuiteCommandManifest($jobs, $root);
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);
        $wildcards = $this->wildcardExpansionPlan($root);
        $permutations = $this->permutationSuiteMap($root);

        $currentCount = (int) ($current['current_accepted_count'] ?? 0);
        $nextCount = (int) ($next['current_accepted_count'] ?? 0);

        $ledger = [];
        $ledger[] = [
            'id' => 'current-accepted-artifact',
            'status' => $currentCount > 0 ? 'satisfied' : 'open',
            'severity' => $currentCount > 0 ? 'evidence' : 'blocking',
            'evidence' => [
                'artifact_count' => (int) ($current['artifact_count'] ?? 0),
                'countable_current_artifacts' => $currentCount,
                'blocked_artifacts' => (int) ($current['blocked_count'] ?? 0),
                'missing_log_count' => (int) ($current['missing_log_count'] ?? 0),
            ],
            'next_gate' => $currentCount > 0
                ? 'preserve current accepted artifact provenance while evaluating whether next-source evidence is already present'
                : 'produce or locate a zero-error bounded runner artifact for the current accepted source before counting release/all movement',
        ];
        $ledger[] = [
            'id' => 'next-accepted-artifact',
            'status' => $nextCount > 0 ? 'satisfied' : 'open',
            'severity' => $nextCount > 0 ? 'evidence' : 'blocking',
            'evidence' => [
                'artifact_count' => (int) ($next['artifact_count'] ?? 0),
                'countable_next_artifacts' => $nextCount,
                'blocked_artifacts' => (int) ($next['blocked_count'] ?? 0),
                'missing_log_count' => (int) ($next['missing_log_count'] ?? 0),
            ],
            'next_gate' => $nextCount > 0
                ? 'record next accepted artifact and suppress duplicate broad runner launch'
                : 'launch only after hydration, command, and duplicate-runner gates are clear, then count a matching next-source artifact',
        ];
        $ledger[] = [
            'id' => 'runner-hydration',
            'status' => ($hydration['status'] ?? null) === 'hydrated' ? 'satisfied' : 'open',
            'severity' => 'blocking',
            'evidence' => [
                'status' => $hydration['status'] ?? 'unknown',
                'missing_count' => (int) ($hydration['missing_count'] ?? 0),
                'runnable_command_count' => (int) ($hydration['runnable_command_count'] ?? 0),
                'missing' => is_array($hydration['missing'] ?? null) ? $hydration['missing'] : [],
            ],
            'next_gate' => 'hydrate the SQLite source/build/testfixture inputs before any next-source release/all runner launch',
        ];
        $ledger[] = [
            'id' => 'command-manifest',
            'status' => ($commandManifest['status'] ?? null) === 'ready' ? 'satisfied' : 'open',
            'severity' => 'blocking',
            'evidence' => [
                'status' => $commandManifest['status'] ?? 'unknown',
                'command_count' => (int) ($commandManifest['command_count'] ?? 0),
                'runnable_command_count' => (int) ($commandManifest['runnable_command_count'] ?? 0),
                'blocked_command_count' => (int) ($commandManifest['blocked_command_count'] ?? 0),
            ],
            'next_gate' => 'keep release, permutation, make, wildcard, and suite-command manifest rows explicit before running',
        ];
        $ledger[] = [
            'id' => 'duplicate-runner',
            'status' => ($active['status'] ?? null) === 'clear' ? 'satisfied' : 'open',
            'severity' => 'blocking',
            'evidence' => [
                'status' => $active['status'] ?? 'unknown',
                'active_count' => (int) ($active['active_count'] ?? 0),
                'active_tiers' => is_array($active['active_tiers'] ?? null) ? $active['active_tiers'] : [],
            ],
            'next_gate' => 'do not launch a duplicate broad SQLite runner while all/release/mptest evidence is active',
        ];
        $ledger[] = [
            'id' => 'wildcard-expansion',
            'status' => in_array($wildcards['status'] ?? null, ['ready', 'complete-no-wildcards'], true) ? 'satisfied' : 'open',
            'severity' => 'audit-gap',
            'evidence' => [
                'status' => $wildcards['status'] ?? 'unknown',
                'pattern_count' => (int) ($wildcards['pattern_count'] ?? 0),
                'expanded_script_count' => (int) ($wildcards['expanded_script_count'] ?? 0),
                'missing_patterns' => is_array($wildcards['missing_patterns'] ?? null) ? $wildcards['missing_patterns'] : [],
            ],
            'next_gate' => 'expand wildcard .test selections against the hydrated upstream test directory before claiming exact focused coverage',
        ];
        $ledger[] = [
            'id' => 'permutation-suite-map',
            'status' => ($permutations['status'] ?? null) === 'ready' ? 'satisfied' : 'open',
            'severity' => 'audit-gap',
            'evidence' => [
                'status' => $permutations['status'] ?? 'unknown',
                'declared_suite_count' => (int) ($permutations['declared_suite_count'] ?? 0),
                'mapped_suite_count' => (int) ($permutations['mapped_suite_count'] ?? 0),
                'unmapped_suite_count' => (int) ($permutations['unmapped_suite_count'] ?? 0),
            ],
            'next_gate' => 'map every declared permutation suite into concrete testfixture commands before counting all-suite closure',
        ];

        $open = [];
        $satisfied = [];
        foreach ($ledger as $entry) {
            if (($entry['status'] ?? null) === 'satisfied') {
                $satisfied[] = $entry['id'];
            } else {
                $open[] = $entry['id'];
            }
        }

        $readyToLaunch = $currentCount > 0
            && $nextCount === 0
            && ($hydration['status'] ?? null) === 'hydrated'
            && ($commandManifest['status'] ?? null) === 'ready'
            && ($active['status'] ?? null) === 'clear';

        $status = 'blocked';
        if ($nextCount > 0) {
            $status = 'next-artifact-countable';
        } elseif ($readyToLaunch) {
            $status = 'ready-for-next-guarded-runner';
        } elseif ($currentCount > 0) {
            $status = 'current-artifact-preserved-with-open-gaps';
        }

        return [
            'status' => $status,
            'current_accepted_head' => $currentAcceptedHead,
            'next_accepted_head' => $nextAcceptedHead,
            'artifact_directory' => $artifactRoot,
            'jobs' => $jobs,
            'ledger_count' => count($ledger),
            'open_gap_count' => count($open),
            'satisfied_gap_count' => count($satisfied),
            'open_gap_ids' => $open,
            'satisfied_gap_ids' => $satisfied,
            'current_artifact_count' => $currentCount,
            'next_artifact_count' => $nextCount,
            'ready_to_launch_next_guarded_runner' => $readyToLaunch,
            'counts_as_release_parity' => $nextCount > 0,
            'counts_current_artifact_only' => $currentCount > 0 && $nextCount === 0,
            'ledger' => $ledger,
            'next_gate' => match ($status) {
                'next-artifact-countable' => 'route the next-source artifact through release admission; do not launch another broad runner',
                'ready-for-next-guarded-runner' => 'launch at most one supervisor-approved guarded runner for the next accepted source, then parse the audit/log artifact',
                'current-artifact-preserved-with-open-gaps' => 'preserve current artifact evidence and close the listed open gaps before next-source launch or parity counting',
                default => 'do not count release/all movement until current artifact provenance, hydration, command, and duplicate-runner gaps are closed',
            },
            'dependency_closure' => 'no new support component needed; current-next gap ledger composes existing runner artifact provenance, hydration, command-manifest, wildcard, permutation, and active-runner gates only',
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public function releaseRunnerHydrationClusterRecord(
        string $acceptedRepositoryHead,
        ?string $repoRoot = null,
        ?string $artifactDirectory = null,
        string $processSnapshot = '',
        int $jobs = 2
    ): array {
        if ($acceptedRepositoryHead === '') {
            throw new \InvalidArgumentException('Accepted repository HEAD is required for release-runner hydration evidence');
        }
        if ($jobs < 1) {
            throw new \InvalidArgumentException('SQLite release-runner hydration jobs must be at least 1');
        }

        $root = $repoRoot ?? dirname(__DIR__, 3);
        $artifactRoot = $artifactDirectory ?? $root . '/.tmux-team/tmp/sqlite-runner-artifacts';
        $hydration = $this->upstreamRunnerHydrationGate($jobs, $root);
        $tiers = $this->releaseTierMatrix($jobs, $root);
        $scripts = $this->selectedScriptInventory($root);
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);
        $artifacts = $this->acceptedHeadArtifactProvenanceDirectoryRecord(
            $artifactRoot,
            $acceptedRepositoryHead,
            $processSnapshot
        );

        $runnableCommandIds = [];
        foreach ($hydration['commands'] ?? [] as $command) {
            if (is_array($command) && ($command['runnable'] ?? false) === true && is_string($command['id'] ?? null)) {
                $runnableCommandIds[] = $command['id'];
            }
        }

        $blockedReasons = [];
        if (($hydration['status'] ?? null) !== 'hydrated') {
            $blockedReasons[] = 'runner-hydration-incomplete';
        }
        if (($tiers['status'] ?? null) !== 'ready') {
            $blockedReasons[] = 'release-tier-matrix-blocked';
        }
        if (($scripts['status'] ?? null) !== 'ready') {
            $blockedReasons[] = 'selected-script-inventory-blocked';
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blockedReasons[] = 'duplicate-broad-runner-active';
        }
        if (($artifacts['current_accepted_count'] ?? 0) < 1) {
            $blockedReasons[] = 'no-current-accepted-artifact';
        }
        if (($artifacts['blocked_count'] ?? 0) > 0) {
            $blockedReasons[] = 'artifact-provenance-blocked';
        }

        $readyToLaunch = $blockedReasons === ['no-current-accepted-artifact']
            && ($hydration['status'] ?? null) === 'hydrated'
            && ($tiers['status'] ?? null) === 'ready'
            && ($scripts['status'] ?? null) === 'ready'
            && ($active['status'] ?? null) === 'clear';
        $currentArtifactReady = ($artifacts['current_accepted_count'] ?? 0) > 0
            && ($artifacts['blocked_count'] ?? 0) === 0;

        $status = 'blocked';
        if ($currentArtifactReady) {
            $status = 'current-accepted-artifact-ready';
        } elseif ($readyToLaunch) {
            $status = 'ready-for-guarded-runner';
        }

        return [
            'status' => $status,
            'accepted_repository_head' => $acceptedRepositoryHead,
            'root' => $root,
            'artifact_directory' => $artifactRoot,
            'jobs' => $jobs,
            'hydration_status' => $hydration['status'] ?? 'unknown',
            'hydration_missing_count' => (int) ($hydration['missing_count'] ?? 0),
            'hydration_runnable_command_count' => (int) ($hydration['runnable_command_count'] ?? 0),
            'hydration_runnable_command_ids' => $runnableCommandIds,
            'release_tier_status' => $tiers['status'] ?? 'unknown',
            'release_ready_tiers' => (int) ($tiers['ready_tiers'] ?? 0),
            'release_blocked_tiers' => (int) ($tiers['blocked_tiers'] ?? 0),
            'selected_script_status' => $scripts['status'] ?? 'unknown',
            'selected_script_resolved_count' => (int) ($scripts['resolved_script_count'] ?? 0),
            'selected_script_missing_count' => (int) ($scripts['missing_script_count'] ?? 0),
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'artifact_status' => $artifacts['status'] ?? 'unknown',
            'artifact_count' => (int) ($artifacts['artifact_count'] ?? 0),
            'current_accepted_artifact_count' => (int) ($artifacts['current_accepted_count'] ?? 0),
            'artifact_blocked_count' => (int) ($artifacts['blocked_count'] ?? 0),
            'missing_log_count' => (int) ($artifacts['missing_log_count'] ?? 0),
            'blocked_reasons' => $blockedReasons,
            'ready_to_launch_guarded_runner' => $readyToLaunch,
            'counts_current_accepted_artifact' => $currentArtifactReady,
            'next_gate' => match ($status) {
                'current-accepted-artifact-ready' => 'record current accepted-HEAD runner artifact evidence and do not launch a duplicate broad runner',
                'ready-for-guarded-runner' => 'launch at most one guarded bounded runner, then write audit/log artifacts back to this artifact directory',
                default => 'hydrate missing runner inputs, resolve selected scripts, clear duplicate runners, and repair artifact provenance before counting release/all evidence',
            },
            'dependency_closure' => 'no new support component needed; release-runner hydration cluster composes lane-local manifest, hydrated upstream cache probes, supplied process snapshots, and guarded audit/log artifact provenance only',
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public function releaseRunnerAcceptedHeadMap(
        string $currentAcceptedHead,
        string $nextAcceptedHead,
        ?string $repoRoot = null,
        ?string $artifactDirectory = null,
        string $processSnapshot = '',
        int $jobs = 2
    ): array {
        if ($currentAcceptedHead === '' || $nextAcceptedHead === '') {
            throw new \InvalidArgumentException('Current and next accepted repository HEAD values are required');
        }
        if ($jobs < 1) {
            throw new \InvalidArgumentException('SQLite release-runner upstream map jobs must be at least 1');
        }

        $root = $repoRoot ?? dirname(__DIR__, 3);
        $artifactRoot = $artifactDirectory ?? $root . '/.tmux-team/tmp/sqlite-runner-artifacts';
        $current = $this->acceptedHeadArtifactProvenanceDirectoryRecord(
            $artifactRoot,
            $currentAcceptedHead,
            $processSnapshot
        );
        $next = $this->acceptedHeadArtifactProvenanceDirectoryRecord(
            $artifactRoot,
            $nextAcceptedHead,
            $processSnapshot
        );
        $hydration = $this->upstreamRunnerHydrationGate($jobs, $root);
        $commandManifest = $this->fullSuiteCommandManifest($jobs, $root);
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $currentCount = (int) ($current['current_accepted_count'] ?? 0);
        $nextCount = (int) ($next['current_accepted_count'] ?? 0);
        $blocked = [];
        if ($currentCount < 1) {
            $blocked[] = [
                'id' => 'current-accepted-artifact-missing',
                'evidence' => 'no zero-error bounded runner artifact matches the current accepted source',
            ];
        }
        if ($nextCount > 0) {
            $blocked[] = [
                'id' => 'next-source-artifact-already-present',
                'evidence' => 'a bounded runner artifact already matches the next accepted source; do not launch a duplicate',
            ];
        }
        if (($hydration['status'] ?? null) !== 'hydrated') {
            $blocked[] = [
                'id' => 'runner-hydration-incomplete',
                'evidence' => (string) ($hydration['missing_count'] ?? 0) . ' runner inputs are missing',
            ];
        }
        if (($commandManifest['status'] ?? null) !== 'ready') {
            $blocked[] = [
                'id' => 'command-manifest-blocked',
                'evidence' => (string) ($commandManifest['blocked_command_count'] ?? 0) . ' release/upstream commands are blocked',
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blocked[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
            ];
        }

        $status = 'blocked';
        if ($currentCount > 0 && $nextCount === 0 && ($hydration['status'] ?? null) === 'hydrated' && ($commandManifest['status'] ?? null) === 'ready' && ($active['status'] ?? null) === 'clear') {
            $status = 'ready-map-current-to-next-runner';
        } elseif ($currentCount > 0 && $nextCount > 0) {
            $status = 'next-artifact-already-countable';
        } elseif ($currentCount > 0) {
            $status = 'current-artifact-preserved-next-blocked';
        }

        $runnableIds = [];
        $blockedIds = [];
        foreach ($commandManifest['commands'] ?? [] as $command) {
            if (!is_array($command) || !is_string($command['id'] ?? null)) {
                continue;
            }

            if (($command['runnable'] ?? false) === true) {
                $runnableIds[] = $command['id'];
            } else {
                $blockedIds[] = $command['id'];
            }
        }

        return [
            'status' => $status,
            'current_accepted_head' => $currentAcceptedHead,
            'next_accepted_head' => $nextAcceptedHead,
            'artifact_directory' => $artifactRoot,
            'jobs' => $jobs,
            'current_artifact_count' => $currentCount,
            'next_artifact_count' => $nextCount,
            'current_artifact_status' => $current['status'] ?? 'unknown',
            'next_artifact_status' => $next['status'] ?? 'unknown',
            'hydration_status' => $hydration['status'] ?? 'unknown',
            'hydration_missing_count' => (int) ($hydration['missing_count'] ?? 0),
            'command_manifest_status' => $commandManifest['status'] ?? 'unknown',
            'command_count' => (int) ($commandManifest['command_count'] ?? 0),
            'runnable_command_count' => (int) ($commandManifest['runnable_command_count'] ?? 0),
            'blocked_command_count' => (int) ($commandManifest['blocked_command_count'] ?? 0),
            'runnable_command_ids' => $runnableIds,
            'blocked_command_ids' => $blockedIds,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'blocker_count' => count($blocked),
            'blockers' => $blocked,
            'counts_current_artifact_only' => $currentCount > 0 && $nextCount === 0,
            'ready_to_launch_next_guarded_runner' => $status === 'ready-map-current-to-next-runner',
            'next_gate' => match ($status) {
                'ready-map-current-to-next-runner' => 'launch at most one guarded runner for the next accepted source, then count only a zero-error artifact with matching provenance',
                'next-artifact-already-countable' => 'record the next accepted artifact and suppress duplicate broad runner launch',
                'current-artifact-preserved-next-blocked' => 'preserve current accepted artifact evidence and resolve hydration, command, or duplicate-runner blockers before the next launch',
                default => 'do not count release/all movement until current accepted artifact provenance and next-source launch gates are explicit',
            },
            'dependency_closure' => 'no new support component needed; current-accepted-head upstream map composes existing artifact provenance, runner hydration, command manifest, and duplicate-runner gates only',
        ];
    }

    /**
     * @param array<string, list<string>> $focusedGroups
     * @return array<string, mixed>
     */
    public function releaseRunnerUpstreamGapProof(
        string $currentAcceptedHead,
        string $nextAcceptedHead,
        string $artifactDirectory,
        array $focusedGroups,
        int $currentPhpPass,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?string $repoRoot = null,
        string $processSnapshot = '',
        int $jobs = 2
    ): array {
        if ($currentAcceptedHead === '' || $nextAcceptedHead === '') {
            throw new \InvalidArgumentException('SQLite release-runner upstream gap proof requires current and next accepted HEAD values');
        }
        if ($artifactDirectory === '') {
            throw new \InvalidArgumentException('SQLite release-runner upstream gap proof requires an artifact directory');
        }
        if ($focusedGroups === []) {
            throw new \InvalidArgumentException('SQLite release-runner upstream gap proof requires at least one focused subset group');
        }
        if ($jobs < 1) {
            throw new \InvalidArgumentException('SQLite release-runner upstream gap proof jobs must be at least 1');
        }

        $root = $repoRoot ?? dirname(__DIR__, 3);
        $current = $this->acceptedHeadArtifactProvenanceDirectoryRecord(
            $artifactDirectory,
            $currentAcceptedHead,
            $processSnapshot
        );
        $next = $this->acceptedHeadArtifactProvenanceDirectoryRecord(
            $artifactDirectory,
            $nextAcceptedHead,
            $processSnapshot
        );
        $subsets = $this->focusedSubsetMatrix($focusedGroups, $jobs, $root);
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);
        $phpAdmission = $this->focusedPhpPassAdmission(
            $currentPhpPass,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote
        );

        $runnableGroups = [];
        $blockedGroups = [];
        $scriptNames = [];
        foreach ($subsets as $name => $subset) {
            $missingScripts = [];
            foreach (is_array($subset['scripts'] ?? null) ? $subset['scripts'] : [] as $script) {
                if (is_string($script)) {
                    $scriptNames[$script] = true;
                    if (!is_file($root . '/.upstream-cache/libsqlite/test/' . $script)) {
                        $missingScripts[] = $script;
                    }
                }
            }

            if (($subset['runnable'] ?? false) === true && $missingScripts === []) {
                $runnableGroups[] = $name;
            } else {
                $blockedGroups[] = $name;
            }
            if ($missingScripts !== []) {
                $subsets[$name]['runnable'] = false;
                $subsets[$name]['status'] = 'skipped';
                $subsets[$name]['skip_reason'] = 'focused subset scripts missing from hydrated test directory: ' . implode(', ', $missingScripts);
                $subsets[$name]['missing_scripts'] = $missingScripts;
            }
        }
        sort($runnableGroups);
        sort($blockedGroups);
        $scriptNames = array_keys($scriptNames);
        sort($scriptNames);

        $currentCount = (int) ($current['current_accepted_count'] ?? 0);
        $nextCount = (int) ($next['current_accepted_count'] ?? 0);
        $blockers = [];
        if ($currentCount < 1) {
            $blockers[] = [
                'id' => 'current-accepted-artifact-missing',
                'evidence' => 'no countable zero-error bounded runner artifact matches the current accepted source',
            ];
        }
        if ($nextCount > 0) {
            $blockers[] = [
                'id' => 'next-source-artifact-already-countable',
                'evidence' => 'a countable bounded runner artifact already matches the next accepted source; do not launch a duplicate',
            ];
        }
        if ($blockedGroups !== []) {
            $blockers[] = [
                'id' => 'focused-subset-hydration-blocked',
                'evidence' => 'one or more explicit focused upstream subsets cannot be launched from the hydrated runner tree',
                'blocked_groups' => $blockedGroups,
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
                'active_tiers' => $active['active_tiers'] ?? [],
            ];
        }
        if (($phpAdmission['status'] ?? null) !== 'admitted') {
            $blockers[] = [
                'id' => 'php-pass-admission-blocked',
                'evidence' => $phpAdmission['blocker'] ?? 'focused PHP output did not satisfy admission gates',
            ];
        }

        $status = $blockers === []
            ? 'current-artifact-gap-proof-next-ready'
            : ($currentCount > 0 && $nextCount === 0 ? 'current-artifact-preserved-next-blocked' : 'blocked');

        return [
            'status' => $status,
            'current_accepted_head' => $currentAcceptedHead,
            'next_accepted_head' => $nextAcceptedHead,
            'artifact_directory' => $artifactDirectory,
            'root' => $root,
            'jobs' => $jobs,
            'current_artifact_count' => (int) ($current['artifact_count'] ?? 0),
            'current_accepted_artifact_count' => $currentCount,
            'current_blocked_count' => (int) ($current['blocked_count'] ?? 0),
            'next_artifact_count' => (int) ($next['artifact_count'] ?? 0),
            'next_accepted_artifact_count' => $nextCount,
            'next_blocked_count' => (int) ($next['blocked_count'] ?? 0),
            'focused_group_count' => count($subsets),
            'focused_runnable_group_count' => count($runnableGroups),
            'focused_blocked_group_count' => count($blockedGroups),
            'focused_runnable_groups' => $runnableGroups,
            'focused_blocked_groups' => $blockedGroups,
            'focused_script_count' => count($scriptNames),
            'focused_scripts' => $scriptNames,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'php_pass_admission' => $phpAdmission,
            'php_pass_delta' => (int) ($phpAdmission['assertion_delta'] ?? 0),
            'next_php_pass' => (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass),
            'counts_current_artifact_only' => $currentCount > 0 && $nextCount === 0,
            'ready_to_launch_next_guarded_runner' => $status === 'current-artifact-gap-proof-next-ready',
            'counts_next_artifact' => false,
            'current' => $current,
            'next' => $next,
            'focused_subsets' => $subsets,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'next_gate' => match ($status) {
                'current-artifact-gap-proof-next-ready' => 'launch at most one guarded next-source runner for these explicit focused subsets, then count only zero-error artifacts with matching next-source provenance',
                'current-artifact-preserved-next-blocked' => 'preserve current accepted artifact evidence while repairing focused subset hydration, duplicate-runner, next-artifact, or PHP admission blockers',
                default => 'repair current artifact provenance before proving the next-source upstream runner gap',
            },
            'dependency_closure' => 'no new support component needed; current-next37 gap proof composes accepted-HEAD artifact provenance, explicit focused subset hydration, duplicate-runner gates, and focused PHP PASS admission only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $suiteRows
     * @return array<string, mixed>
     */
    public function releaseRunnerSuiteProgressMap(
        array $suiteRows,
        string $currentAcceptedHead,
        string $nextAcceptedHead,
        int $currentPhpPass,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote
    ): array {
        if ($currentAcceptedHead === '' || $nextAcceptedHead === '') {
            throw new \InvalidArgumentException('SQLite suite progress map requires current and next accepted HEAD values');
        }
        if ($suiteRows === []) {
            throw new \InvalidArgumentException('SQLite suite progress map requires at least one suite row');
        }

        $phpAdmission = $this->focusedPhpPassAdmission(
            $currentPhpPass,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote
        );

        $entries = [];
        $blocked = [];
        $currentCountable = 0;
        $nextCountable = 0;
        $currentTests = 0;
        $nextTests = 0;
        $advanced = [];
        $preserved = [];
        $regressed = [];
        $open = [];
        $tiers = [];

        foreach ($suiteRows as $label => $row) {
            if (!is_array($row)) {
                $blocked[] = [
                    'id' => 'suite-row-invalid',
                    'evidence' => 'suite progress row is not an array',
                    'label' => is_string($label) ? $label : 'row-' . (string) count($entries),
                ];
                continue;
            }

            $id = is_string($row['id'] ?? null) && $row['id'] !== ''
                ? $row['id']
                : (is_string($label) ? $label : 'row-' . (string) count($entries));
            $tier = is_string($row['tier'] ?? null) && $row['tier'] !== '' ? $row['tier'] : 'unclassified';
            $currentStatus = is_string($row['current_status'] ?? null) ? $row['current_status'] : 'missing';
            $nextStatus = is_string($row['next_status'] ?? null) ? $row['next_status'] : 'missing';
            $currentRowCountable = (bool) ($row['current_countable'] ?? ($currentStatus === 'passed'));
            $nextRowCountable = (bool) ($row['next_countable'] ?? ($nextStatus === 'passed'));
            $currentRowTests = max(0, (int) ($row['current_tests'] ?? 0));
            $nextRowTests = max(0, (int) ($row['next_tests'] ?? 0));
            $rowBlockers = [];
            if (is_array($row['blockers'] ?? null)) {
                foreach ($row['blockers'] as $blocker) {
                    if (is_string($blocker) && $blocker !== '') {
                        $rowBlockers[] = $blocker;
                    }
                }
            }
            if (is_string($row['blocker'] ?? null) && $row['blocker'] !== '') {
                $rowBlockers[] = $row['blocker'];
            }

            if ($currentRowCountable) {
                $currentCountable++;
                $currentTests += $currentRowTests;
            }
            if ($nextRowCountable) {
                $nextCountable++;
                $nextTests += $nextRowTests;
            }

            $movement = 'open';
            if ($nextRowCountable && !$currentRowCountable) {
                $movement = 'advanced';
                $advanced[] = $id;
            } elseif ($nextRowCountable && $currentRowCountable) {
                $movement = $nextRowTests >= $currentRowTests ? 'preserved' : 'regressed';
                if ($movement === 'preserved') {
                    $preserved[] = $id;
                } else {
                    $regressed[] = $id;
                    $rowBlockers[] = 'next-test-count-regressed';
                }
            } elseif (!$nextRowCountable && $currentRowCountable) {
                $movement = 'regressed';
                $regressed[] = $id;
                $rowBlockers[] = 'next-countability-regressed';
            } else {
                $open[] = $id;
            }

            if ($rowBlockers !== []) {
                $blocked[] = [
                    'id' => 'suite-row-blocked',
                    'suite_id' => $id,
                    'evidence' => implode('; ', array_values(array_unique($rowBlockers))),
                ];
            }

            if (!isset($tiers[$tier])) {
                $tiers[$tier] = [
                    'tier' => $tier,
                    'rows' => 0,
                    'current_countable' => 0,
                    'next_countable' => 0,
                    'advanced' => 0,
                    'preserved' => 0,
                    'regressed' => 0,
                    'open' => 0,
                    'current_tests' => 0,
                    'next_tests' => 0,
                ];
            }
            $tiers[$tier]['rows']++;
            $tiers[$tier]['current_countable'] += $currentRowCountable ? 1 : 0;
            $tiers[$tier]['next_countable'] += $nextRowCountable ? 1 : 0;
            $tiers[$tier][$movement]++;
            $tiers[$tier]['current_tests'] += $currentRowCountable ? $currentRowTests : 0;
            $tiers[$tier]['next_tests'] += $nextRowCountable ? $nextRowTests : 0;

            $entries[] = [
                'id' => $id,
                'tier' => $tier,
                'current_status' => $currentStatus,
                'next_status' => $nextStatus,
                'current_countable' => $currentRowCountable,
                'next_countable' => $nextRowCountable,
                'current_tests' => $currentRowTests,
                'next_tests' => $nextRowTests,
                'movement' => $movement,
                'blockers' => array_values(array_unique($rowBlockers)),
            ];
        }

        ksort($tiers);
        $tierRows = array_values($tiers);
        sort($advanced);
        sort($preserved);
        sort($regressed);
        sort($open);

        if (($phpAdmission['status'] ?? null) !== 'admitted') {
            $blocked[] = [
                'id' => 'focused-php-pass-admission-blocked',
                'evidence' => $phpAdmission['blocker'] ?? 'focused PHP output did not satisfy admission gates',
            ];
        }

        $countableDelta = $nextCountable - $currentCountable;
        $testsDelta = $nextTests - $currentTests;
        $status = 'blocked';
        if ($blocked === [] && $countableDelta > 0) {
            $status = 'next48-suite-progress-advanced';
        } elseif ($blocked === [] && $countableDelta === 0 && $regressed === []) {
            $status = 'next48-suite-progress-preserved';
        } elseif ($currentCountable > 0 && $regressed === []) {
            $status = 'current-suite-progress-preserved-with-open-gaps';
        }

        return [
            'status' => $status,
            'current_accepted_head' => $currentAcceptedHead,
            'next_accepted_head' => $nextAcceptedHead,
            'row_count' => count($entries),
            'tier_count' => count($tierRows),
            'current_countable_count' => $currentCountable,
            'next_countable_count' => $nextCountable,
            'countable_delta' => $countableDelta,
            'current_tests_total' => $currentTests,
            'next_tests_total' => $nextTests,
            'tests_total_delta' => $testsDelta,
            'advanced_count' => count($advanced),
            'preserved_count' => count($preserved),
            'regressed_count' => count($regressed),
            'open_count' => count($open),
            'advanced_ids' => $advanced,
            'preserved_ids' => $preserved,
            'regressed_ids' => $regressed,
            'open_ids' => $open,
            'tiers' => $tierRows,
            'entries' => $entries,
            'php_pass_admission' => $phpAdmission,
            'php_pass_delta' => (int) ($phpAdmission['assertion_delta'] ?? 0),
            'next_php_pass' => (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass),
            'blocker_count' => count($blocked),
            'blockers' => $blocked,
            'counts_next_suite_progress' => $status === 'next48-suite-progress-advanced',
            'preserves_current_suite_progress' => in_array($status, ['next48-suite-progress-preserved', 'current-suite-progress-preserved-with-open-gaps'], true),
            'next_gate' => match ($status) {
                'next48-suite-progress-advanced' => 'publish only the advanced current/next48 suite progress rows and keep remaining release/all gaps explicit',
                'next48-suite-progress-preserved' => 'record that current/next48 preserves suite progress without claiming release/all parity movement',
                'current-suite-progress-preserved-with-open-gaps' => 'preserve current countable suite rows and resolve open next-source blockers before counting more progress',
                default => 'repair regressed, blocked, or unfocused suite progress evidence before counting current/next48 movement',
            },
            'dependency_closure' => 'no new support component needed; current-next48 suite progress map composes lane-local suite row metadata and focused PHP TestRunner admission only',
        ];
    }

