    /**
     * @return array<string, mixed>
     */
    public function releaseRunnerUpstreamSuiteGapBurnup(
        string $currentArtifactDirectory,
        string $nextArtifactDirectory,
        string $currentAcceptedHead,
        string $nextAcceptedHead,
        int $currentPhpPass,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        int $minimumFocusedAssertions = 40
    ): array {
        if ($currentAcceptedHead === '' || $nextAcceptedHead === '') {
            throw new \InvalidArgumentException('SQLite current-next55 suite gap burnup requires current and next accepted HEAD values');
        }
        if ($currentArtifactDirectory === '' || $nextArtifactDirectory === '') {
            throw new \InvalidArgumentException('SQLite current-next55 suite gap burnup requires current and next artifact directories');
        }
        if ($minimumFocusedAssertions < 1) {
            throw new \InvalidArgumentException('SQLite current-next55 suite gap burnup minimum focused assertions must be at least 1');
        }

        $current = $this->boundedRunnerArtifactDirectoryRecord($currentArtifactDirectory, $currentAcceptedHead);
        $next = $this->boundedRunnerArtifactDirectoryRecord($nextArtifactDirectory, $nextAcceptedHead);
        $phpAdmission = $this->focusedPhpPassAdmission(
            $currentPhpPass,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote
        );

        $currentEntries = $this->artifactDirectoryEntriesBySuiteKey($current['entries'] ?? []);
        $nextEntries = $this->artifactDirectoryEntriesBySuiteKey($next['entries'] ?? []);
        $keys = array_values(array_unique(array_merge(array_keys($currentEntries), array_keys($nextEntries))));
        sort($keys);

        $entries = [];
        $blockers = [];
        $advanced = [];
        $preserved = [];
        $regressed = [];
        $open = [];
        $tiers = [];
        $currentCountable = 0;
        $nextCountable = 0;
        $currentTests = 0;
        $nextTests = 0;

        foreach ($keys as $key) {
            $currentEntry = $currentEntries[$key] ?? null;
            $nextEntry = $nextEntries[$key] ?? null;
            $currentCounted = is_array($currentEntry) && (bool) ($currentEntry['countable'] ?? false);
            $nextCounted = is_array($nextEntry) && (bool) ($nextEntry['countable'] ?? false);
            $currentEntryTests = $currentCounted ? max(0, (int) ($currentEntry['tests'] ?? 0)) : 0;
            $nextEntryTests = $nextCounted ? max(0, (int) ($nextEntry['tests'] ?? 0)) : 0;
            $tier = $this->artifactEntryTier($nextEntry ?? $currentEntry ?? []);
            $id = $this->artifactEntrySuiteId($nextEntry ?? $currentEntry ?? [], $key);

            if ($currentCounted) {
                $currentCountable++;
                $currentTests += $currentEntryTests;
            }
            if ($nextCounted) {
                $nextCountable++;
                $nextTests += $nextEntryTests;
            }

            $entryBlockers = [];
            foreach ([$currentEntry, $nextEntry] as $artifactEntry) {
                if (!is_array($artifactEntry) || !is_array($artifactEntry['blocker_ids'] ?? null)) {
                    continue;
                }
                foreach ($artifactEntry['blocker_ids'] as $blocker) {
                    if (is_string($blocker) && $blocker !== '') {
                        $entryBlockers[] = $blocker;
                    }
                }
            }

            $movement = 'open';
            if ($nextCounted && !$currentCounted) {
                $movement = 'advanced';
                $advanced[] = $id;
            } elseif ($nextCounted && $currentCounted) {
                $movement = $nextEntryTests >= $currentEntryTests ? 'preserved' : 'regressed';
                if ($movement === 'preserved') {
                    $preserved[] = $id;
                } else {
                    $regressed[] = $id;
                    $entryBlockers[] = 'next-test-count-regressed';
                }
            } elseif (!$nextCounted && $currentCounted) {
                $movement = 'regressed';
                $regressed[] = $id;
                $entryBlockers[] = 'next-countability-regressed';
            } else {
                $open[] = $id;
            }

            $entryBlockers = array_values(array_unique($entryBlockers));
            if ($entryBlockers !== []) {
                $blockers[] = [
                    'id' => 'suite-artifact-blocked',
                    'suite_id' => $id,
                    'evidence' => implode('; ', $entryBlockers),
                ];
            }

            if (!isset($tiers[$tier])) {
                $tiers[$tier] = [
                    'tier' => $tier,
                    'rows' => 0,
                    'current_countable' => 0,
                    'next_countable' => 0,
                    'advanced' => 0,
                    'preserved' => 0,
                    'regressed' => 0,
                    'open' => 0,
                    'current_tests' => 0,
                    'next_tests' => 0,
                ];
            }
            $tiers[$tier]['rows']++;
            $tiers[$tier]['current_countable'] += $currentCounted ? 1 : 0;
            $tiers[$tier]['next_countable'] += $nextCounted ? 1 : 0;
            $tiers[$tier][$movement]++;
            $tiers[$tier]['current_tests'] += $currentEntryTests;
            $tiers[$tier]['next_tests'] += $nextEntryTests;

            $entries[] = [
                'id' => $id,
                'suite_key' => $key,
                'tier' => $tier,
                'current_label' => is_array($currentEntry) ? (string) ($currentEntry['label'] ?? '') : null,
                'next_label' => is_array($nextEntry) ? (string) ($nextEntry['label'] ?? '') : null,
                'current_status' => is_array($currentEntry) ? (string) ($currentEntry['status'] ?? 'missing') : 'missing',
                'next_status' => is_array($nextEntry) ? (string) ($nextEntry['status'] ?? 'missing') : 'missing',
                'current_countable' => $currentCounted,
                'next_countable' => $nextCounted,
                'current_tests' => $currentEntryTests,
                'next_tests' => $nextEntryTests,
                'movement' => $movement,
                'blockers' => $entryBlockers,
            ];
        }

        ksort($tiers);
        sort($advanced);
        sort($preserved);
        sort($regressed);
        sort($open);

        if (($phpAdmission['status'] ?? null) !== 'admitted') {
            $blockers[] = [
                'id' => 'focused-php-pass-admission-blocked',
                'evidence' => $phpAdmission['blocker'] ?? 'focused PHP output did not satisfy admission gates',
            ];
        } elseif ((int) ($phpAdmission['assertion_delta'] ?? 0) < $minimumFocusedAssertions) {
            $blockers[] = [
                'id' => 'focused-php-pass-delta-below-minimum',
                'evidence' => 'focused TestRunner assertion delta is below current-next55 suite gap burnup minimum',
                'minimum' => $minimumFocusedAssertions,
                'actual' => (int) ($phpAdmission['assertion_delta'] ?? 0),
            ];
        }

        if (($current['status'] ?? null) === 'blocked-missing-artifact-directory' || ($next['status'] ?? null) === 'blocked-missing-artifact-directory') {
            $blockers[] = [
                'id' => 'artifact-directory-missing',
                'evidence' => 'current or next guarded bounded-runner artifact directory is missing',
            ];
        }

        $countableDelta = $nextCountable - $currentCountable;
        $testsDelta = $nextTests - $currentTests;
        $status = 'blocked';
        $criticalBlockerIds = ['focused-php-pass-admission-blocked', 'focused-php-pass-delta-below-minimum', 'artifact-directory-missing'];
        $hasCriticalBlocker = count(array_intersect($criticalBlockerIds, array_column($blockers, 'id'))) > 0;
        if ($blockers === [] && $countableDelta > 0) {
            $status = 'next55-suite-gap-burnup-advanced';
        } elseif ($blockers === [] && $countableDelta === 0 && $regressed === []) {
            $status = 'next55-suite-gap-burnup-preserved';
        } elseif (!$hasCriticalBlocker && $currentCountable > 0 && $regressed === []) {
            $status = 'current-suite-gap-burnup-preserved-with-open-gaps';
        }

        return [
            'status' => $status,
            'current_accepted_head' => $currentAcceptedHead,
            'next_accepted_head' => $nextAcceptedHead,
            'current_artifact_directory' => $currentArtifactDirectory,
            'next_artifact_directory' => $nextArtifactDirectory,
            'row_count' => count($entries),
            'tier_count' => count($tiers),
            'current_artifact_count' => (int) ($current['artifact_count'] ?? 0),
            'next_artifact_count' => (int) ($next['artifact_count'] ?? 0),
            'current_countable_count' => $currentCountable,
            'next_countable_count' => $nextCountable,
            'countable_delta' => $countableDelta,
            'current_tests_total' => $currentTests,
            'next_tests_total' => $nextTests,
            'tests_total_delta' => $testsDelta,
            'advanced_count' => count($advanced),
            'preserved_count' => count($preserved),
            'regressed_count' => count($regressed),
            'open_count' => count($open),
            'advanced_ids' => $advanced,
            'preserved_ids' => $preserved,
            'regressed_ids' => $regressed,
            'open_ids' => $open,
            'tiers' => array_values($tiers),
            'entries' => $entries,
            'current_directory_record' => $current,
            'next_directory_record' => $next,
            'php_pass_admission' => $phpAdmission,
            'minimum_focused_assertions' => $minimumFocusedAssertions,
            'php_pass_delta' => (int) ($phpAdmission['assertion_delta'] ?? 0),
            'next_php_pass' => (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass),
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_next_suite_gap_burnup' => $status === 'next55-suite-gap-burnup-advanced',
            'preserves_current_suite_gap_burnup' => in_array($status, ['next55-suite-gap-burnup-preserved', 'current-suite-gap-burnup-preserved-with-open-gaps'], true),
            'counts_as_release_parity' => false,
            'next_gate' => match ($status) {
                'next55-suite-gap-burnup-advanced' => 'publish only accepted-HEAD zero-error next55 artifact burnup rows and keep release/all parity gaps explicit',
                'next55-suite-gap-burnup-preserved' => 'record that current-next55 preserves countable artifact burnup without claiming release/all parity movement',
                'current-suite-gap-burnup-preserved-with-open-gaps' => 'preserve current countable artifact rows while resolving open next-source guarded-runner blockers',
                default => 'repair blocked, regressed, stale, failed, active, or under-threshold current-next55 suite gap burnup evidence before counting movement',
            },
            'dependency_closure' => 'no new support component needed; current-next55 suite gap burnup composes guarded artifact-directory countability and focused PHP TestRunner admission only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRecords
     * @return array<string, mixed>
     */
    public function releaseRunnerUpstreamCanonicalMap(
        array $artifactRecords,
        string $currentAcceptedHead,
        string $nextAcceptedHead
    ): array {
        if ($currentAcceptedHead === '' || $nextAcceptedHead === '') {
            throw new \InvalidArgumentException('Current and next accepted repository HEAD values are required for the canonical upstream map');
        }

        $entries = [];
        $canonical = [];
        $currentCount = 0;
        $nextCount = 0;
        $staleCount = 0;
        $blockedCount = 0;
        $releaseLikeCount = 0;
        $focusedCount = 0;
        $testsTotal = 0;
        $errorsTotal = 0;
        $duplicateLabels = [];
        $canonicalKeys = [];

        foreach ($artifactRecords as $label => $artifact) {
            $entryLabel = is_string($label) ? $label : 'artifact-' . (string) count($entries);
            if (!is_array($artifact)) {
                $blockedCount++;
                $entries[] = [
                    'label' => $entryLabel,
                    'status' => 'blocked-invalid-artifact',
                    'head_class' => 'invalid',
                    'canonical_key' => 'invalid:' . $entryLabel,
                    'kind' => 'invalid',
                    'tests' => 0,
                    'errors' => 0,
                    'blocker_ids' => ['artifact-record-invalid'],
                ];
                continue;
            }

            $acceptance = $this->boundedRunnerAcceptanceGate($artifact, $currentAcceptedHead);
            $requested = is_array($artifact['requested'] ?? null) ? $artifact['requested'] : [];
            $results = is_array($artifact['results'] ?? null) ? $artifact['results'] : [];
            $head = is_string($artifact['repository_head'] ?? null) ? $artifact['repository_head'] : '';
            $testset = is_string($requested['testset'] ?? null) ? $requested['testset'] : 'unknown';
            $patterns = $this->normalizeRunnerPatterns($requested['patterns'] ?? []);
            $tests = is_int($results['tests'] ?? null) ? $results['tests'] : 0;
            $errors = is_int($results['errors'] ?? null) ? $results['errors'] : 0;

            $headClass = 'stale';
            if ($head === $currentAcceptedHead) {
                $headClass = 'current';
            } elseif ($head === $nextAcceptedHead) {
                $headClass = 'next';
            }

            $kind = $patterns === [] && in_array($testset, ['all', 'release'], true)
                ? 'release-like'
                : ($patterns !== [] ? 'focused' : 'unselected');

            if ($kind === 'release-like') {
                $releaseLikeCount++;
            } elseif ($kind === 'focused') {
                $focusedCount++;
            }

            $blockerIds = [];
            foreach (is_array($acceptance['blockers'] ?? null) ? $acceptance['blockers'] : [] as $blocker) {
                if (is_array($blocker) && is_string($blocker['id'] ?? null)) {
                    $blockerIds[] = $blocker['id'];
                }
            }

            if ($headClass === 'next') {
                $nextAcceptance = $this->boundedRunnerAcceptanceGate($artifact, $nextAcceptedHead);
                $blockerIds = [];
                foreach (is_array($nextAcceptance['blockers'] ?? null) ? $nextAcceptance['blockers'] : [] as $blocker) {
                    if (is_array($blocker) && is_string($blocker['id'] ?? null)) {
                        $blockerIds[] = $blocker['id'];
                    }
                }
            } elseif ($headClass === 'stale') {
                $blockerIds[] = 'artifact-head-not-current-or-next';
            }

            $blockerIds = array_values(array_unique($blockerIds));
            $countable = $blockerIds === [] && in_array($headClass, ['current', 'next'], true);
            if ($countable) {
                if ($headClass === 'current') {
                    $currentCount++;
                } else {
                    $nextCount++;
                }
                $testsTotal += $tests;
                $errorsTotal += $errors;
            } else {
                $blockedCount++;
                if ($headClass === 'stale') {
                    $staleCount++;
                }
            }

            $canonicalKey = implode('|', [
                $headClass,
                $head,
                $testset,
                $patterns === [] ? 'none' : implode(',', $patterns),
            ]);

            $entry = [
                'label' => $entryLabel,
                'status' => $countable ? 'countable' : 'blocked',
                'head_class' => $headClass,
                'repository_head' => $head,
                'canonical_key' => $canonicalKey,
                'kind' => $kind,
                'testset' => $testset,
                'patterns' => $patterns,
                'tests' => $tests,
                'errors' => $errors,
                'blocker_ids' => $blockerIds,
            ];

            $entries[] = $entry;
            if (!isset($canonical[$canonicalKey]) || $tests > (int) ($canonical[$canonicalKey]['tests'] ?? 0)) {
                $canonical[$canonicalKey] = $entry;
            } else {
                $duplicateLabels[] = $entryLabel;
            }
            if (isset($canonicalKeys[$canonicalKey])) {
                $duplicateLabels[] = $entryLabel;
            }
            $canonicalKeys[$canonicalKey] = true;
        }

        ksort($canonical);
        $duplicateLabels = array_values(array_unique($duplicateLabels));
        sort($duplicateLabels);

        $status = 'blocked';
        if ($nextCount > 0) {
            $status = 'next-canonical-artifact-present';
        } elseif ($currentCount > 0 && $blockedCount === 0) {
            $status = 'current-canonical-baseline-only';
        } elseif ($currentCount > 0) {
            $status = 'current-canonical-baseline-with-blockers';
        }

        return [
            'status' => $status,
            'current_accepted_head' => $currentAcceptedHead,
            'next_accepted_head' => $nextAcceptedHead,
            'artifact_count' => count($entries),
            'canonical_entry_count' => count($canonical),
            'current_countable_count' => $currentCount,
            'next_countable_count' => $nextCount,
            'stale_count' => $staleCount,
            'blocked_count' => $blockedCount,
            'release_like_count' => $releaseLikeCount,
            'focused_count' => $focusedCount,
            'duplicate_count' => count($duplicateLabels),
            'duplicate_labels' => $duplicateLabels,
            'tests_total' => $testsTotal,
            'errors_total' => $errorsTotal,
            'entries' => $entries,
            'canonical_entries' => array_values($canonical),
            'counts_current_baseline' => $currentCount > 0,
            'counts_next_artifacts' => $nextCount > 0,
            'ready_to_launch_next_guarded_runner' => $currentCount > 0 && $nextCount === 0 && $blockedCount === 0,
            'next_gate' => match ($status) {
                'next-canonical-artifact-present' => 'count the next accepted canonical artifact set and suppress duplicate broad runner launch',
                'current-canonical-baseline-only' => 'preserve the current accepted canonical baseline, then launch at most one guarded next-source runner if supervisor-approved',
                'current-canonical-baseline-with-blockers' => 'preserve current accepted artifacts but repair stale, failed, or manifest-mismatched records before the next launch',
                default => 'collect at least one current accepted zero-error artifact before mapping current-to-next release-runner evidence',
            },
            'dependency_closure' => 'no new support component needed; canonical current-next36 mapping composes in-memory bounded runner artifact records and existing provenance gates only',
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public function wildcardExpansionPlan(?string $repoRoot = null): array
    {
        $coverage = $this->runnerCoverageAudit();
        $root = $repoRoot ?? dirname(__DIR__, 3);
        $testDirectory = $root . '/.upstream-cache/libsqlite/test';
        $patterns = $coverage['pattern_scripts'];

        $expanded = [];
        $missingPatterns = [];
        $invalidPatterns = [];
        $testDirectoryReady = is_dir($testDirectory);

        foreach ($patterns as $pattern) {
            if (!is_string($pattern) || !preg_match('/^[A-Za-z0-9_.*?-]+\.test$/', $pattern)) {
                $invalidPatterns[] = (string) $pattern;
                continue;
            }

            if (!$testDirectoryReady) {
                $missingPatterns[] = $pattern;
                continue;
            }

            $matches = glob($testDirectory . '/' . $pattern);
            if ($matches === false || $matches === []) {
                $missingPatterns[] = $pattern;
                continue;
            }

            $scripts = [];
            foreach ($matches as $match) {
                $scripts[] = basename($match);
            }

            sort($scripts);
            $expanded[$pattern] = $scripts;
        }

        ksort($expanded);

        $expandedCount = 0;
        foreach ($expanded as $scripts) {
            $expandedCount += count($scripts);
        }

        $blocked = !$testDirectoryReady || $missingPatterns !== [] || $invalidPatterns !== [];

        return [
            'status' => $patterns === []
                ? 'complete-no-wildcards'
                : ($blocked ? 'blocked-needs-hydrated-test-dir' : 'ready'),
            'test_directory' => '.upstream-cache/libsqlite/test',
            'test_directory_ready' => $testDirectoryReady,
            'pattern_count' => count($patterns),
            'patterns' => $patterns,
            'expanded_pattern_count' => count($expanded),
            'expanded_script_count' => $expandedCount,
            'expanded' => $expanded,
            'missing_patterns' => $missingPatterns,
            'invalid_patterns' => $invalidPatterns,
            'next_gate' => $blocked
                ? 'hydrate .upstream-cache/libsqlite/test, then expand wildcard selections to concrete .test filenames before counting exact focused coverage'
                : 'replace wildcard runner notes with concrete selected .test script lists in the manifest evidence',
            'dependency_closure' => 'no new support component needed; wildcard expansion uses the lane-local manifest and hydrated upstream test directory only',
        ];
    }

