    /**
     * @return array{scripts: int, tests: int, errors: int}
     */
    private function parseVeryquickResult(mixed $result): array
    {
        if (!is_string($result)) {
            return ['scripts' => 0, 'tests' => 0, 'errors' => 0];
        }

        if (preg_match('/Passed\s+(\d+)\s+(?:Tcl\s+)?scripts?\s+with\s+(\d+)\s+errors?\s+out\s+of\s+(\d+)\s+tests?/i', $result, $matches) !== 1) {
            return ['scripts' => 0, 'tests' => 0, 'errors' => 0];
        }

        return [
            'scripts' => (int) $matches[1],
            'errors' => (int) $matches[2],
            'tests' => (int) $matches[3],
        ];
    }

    /**
     * @return array{tests: int, errors: int}
     */
    private function parseFocusedResultDescription(string $description): array
    {
        if (preg_match('/with\s+(\d+)\s+errors?\s+out\s+of\s+(\d+)\s+tests?/i', $description, $matches) === 1) {
            return [
                'tests' => (int) $matches[2],
                'errors' => (int) $matches[1],
            ];
        }

        if (preg_match('/(\d+)\s+errors?\s+out\s+of\s+(\d+)\s+tests?/i', $description, $matches) === 1) {
            return [
                'tests' => (int) $matches[2],
                'errors' => (int) $matches[1],
            ];
        }

        return ['tests' => 0, 'errors' => 0];
    }

    /**
     * @return list<string>
     */
    private function extractPermutationSuiteNames(string $text): array
    {
        $names = [];
        $patterns = [
            '/^\s*test_suite\s+"([^"\r\n]+)"/m',
            '/^\s*test_suite\s+([A-Za-z0-9_.${}-]+)/m',
            '/^\s*permutation\s+([A-Za-z0-9_.-]+)/m',
            '/^\s*run_tests\s+([A-Za-z0-9_.-]+)/m',
            '/^\s*([A-Za-z0-9_.-]+)\s+\{[^}\n]*(?:-files|-description|-initialize|-shutdown)/m',
        ];

        foreach ($patterns as $pattern) {
            if (preg_match_all($pattern, $text, $matches) !== false) {
                foreach ($matches[1] as $name) {
                    if ($name === 'NAME') {
                        continue;
                    }

                    $names[$name] = true;
                }
            }
        }

        $suiteNames = array_keys($names);
        sort($suiteNames);

        return $suiteNames;
    }

    private function descriptionUsesCachedEvidence(string $description): bool
    {
        $lower = strtolower($description);

        return str_contains($lower, 'reused')
            || str_contains($lower, 'did not start upstream testfixture')
            || str_contains($lower, 'no new upstream runner')
            || str_contains($lower, 'no fresh upstream runner')
            || str_contains($lower, 'did not contain the hydrated upstream cache')
            || str_contains($lower, 'has no hydrated .upstream-cache');
    }

    /**
     * @return list<string>
     */
    private function extractTestScriptTokens(string $command): array
    {
        if (preg_match_all('/(?<![A-Za-z0-9_.\/-])([A-Za-z0-9_.*?\/-]+\.test)(?![A-Za-z0-9_.\/-])/', $command, $matches) < 1) {
            return [];
        }

        return array_values(array_unique($matches[1]));
    }

    /**
     * @return list<string>
     */
    private function normalizeRunnerPatterns(mixed $patterns): array
    {
        if (is_string($patterns)) {
            $patterns = $patterns === 'none' || $patterns === ''
                ? []
                : preg_split('/[\s,]+/', $patterns);
        }

        if (!is_array($patterns)) {
            return [];
        }

        $normalized = [];
        foreach ($patterns as $pattern) {
            if (!is_string($pattern)) {
                continue;
            }

            $pattern = trim($pattern);
            if ($pattern === '' || $pattern === 'none') {
                continue;
            }

            $normalized[$pattern] = true;
        }

        $scripts = array_keys($normalized);
        sort($scripts, SORT_STRING);

        return $scripts;
    }

    /**
     * @param array<string, mixed> $fullReleaseStatus
     * @return list<string>
     */
    private function remainingSuiteTiers(array $fullReleaseStatus): array
    {
        if (($fullReleaseStatus['executed'] ?? false) === true) {
            return [];
        }

        return [
            'full release/all permutations',
            'multi-configuration make test suites',
            'long-running stress/permutation tiers beyond veryquick',
        ];
    }

    /**
     * @return list<string>
     */
    private function missingRunnerInputs(
        string $absoluteBuildDirectory,
        string $testfixture,
        string $testrunner,
        string $buildDirectory
    ): array {
        $missing = [];
        if (!is_dir($absoluteBuildDirectory)) {
            $missing[] = $buildDirectory;
        }
        if (!is_file($testfixture)) {
            $missing[] = $buildDirectory . '/testfixture';
        }
        if (!is_file($testrunner)) {
            $missing[] = '.upstream-cache/libsqlite/test/testrunner.tcl';
        }

        return $missing;
    }

    /**
     * @param array<string, array<string, mixed>> $inputs
     * @param list<string> $ids
     * @return list<string>
     */
    private function missingHydrationGatePaths(array $inputs, array $ids): array
    {
        $missing = [];
        foreach ($ids as $id) {
            $input = $inputs[$id] ?? null;
            if (!is_array($input)) {
                continue;
            }
            if (($input['ready'] ?? false) !== true && is_string($input['path'] ?? null)) {
                $missing[] = $input['path'];
            }
            if ($id === 'testfixture' && ($input['ready'] ?? false) === true && ($input['executable'] ?? false) !== true) {
                $missing[] = (is_string($input['path'] ?? null) ? $input['path'] : 'testfixture') . ' executable bit';
            }
        }

        return array_values(array_unique($missing));
    }

    private function extractMarkdownHeadingLabel(string $text): ?string
    {
        if (preg_match('/^#\s+SQLite Tcl Bounded Runner Evidence\s+-\s+([^\r\n]+)/m', $text, $matches) !== 1) {
            return null;
        }

        return trim($matches[1]);
    }

    private function extractBacktickField(string $text, string $field): ?string
    {
        $quotedField = preg_quote($field, '/');
        if (preg_match('/-\s+' . $quotedField . ':\s+`([^`]*)`/i', $text, $matches) !== 1) {
            return null;
        }

        return $matches[1];
    }

    /**
     * @return array<string, mixed>
     */
    private function extractBoundedRunnerSummaryJson(string $text): array
    {
        $candidates = [];
        if (preg_match('/-\s+(?:Runner\s+)?Summary JSON:\s+`([^`]*)`/i', $text, $matches) === 1) {
            $candidates[] = $matches[1];
        }
        if (preg_match('/```json\s*(\{.*?\})\s*```/is', $text, $matches) === 1) {
            $candidates[] = $matches[1];
        }
        if (preg_match('/^\s*RUNNER_SUMMARY_JSON=(\{.*\})\s*$/mi', $text, $matches) === 1) {
            $candidates[] = $matches[1];
        }

        foreach ($candidates as $candidate) {
            $decoded = json_decode(html_entity_decode($candidate, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'), true);
            if (is_array($decoded)) {
                return $decoded;
            }
        }

        return [];
    }

    /**
     * @param array<string, mixed> $summary
     * @param list<string> $keys
     */
    private function summaryJsonInt(array $summary, array $keys): ?int
    {
        foreach ($keys as $key) {
            $value = $summary[$key] ?? null;
            if (is_int($value)) {
                return $value;
            }
            if (is_string($value) && preg_match('/^-?\d+$/', $value) === 1) {
                return (int) $value;
            }
        }

        return null;
    }

    /**
     * @param array<string, mixed> $summary
     * @param list<string> $keys
     */
    private function summaryJsonString(array $summary, array $keys): ?string
    {
        foreach ($keys as $key) {
            $value = $summary[$key] ?? null;
            if (is_string($value) && $value !== '') {
                return $value;
            }
        }

        return null;
    }

    /**
     * @param array<string, mixed> $summary
     * @param list<string> $keys
     * @return list<string>
     */
    private function summaryJsonStringList(array $summary, array $keys): array
    {
        foreach ($keys as $key) {
            $value = $summary[$key] ?? null;
            if (!is_array($value)) {
                continue;
            }

            $strings = array_values(array_filter($value, 'is_string'));
            if ($strings !== []) {
                return $strings;
            }
        }

        return [];
    }

    private function pairedRunnerLogPath(string $auditText, string $auditPath, string $artifactDirectory): ?string
    {
        $candidates = [];
        $logField = $this->extractBacktickField($auditText, 'Log');
        if (is_string($logField) && $logField !== '') {
            $candidates[] = $logField;
            $candidates[] = $artifactDirectory . DIRECTORY_SEPARATOR . basename($logField);
        }

        $candidates[] = preg_replace('/\.(?:md|audit)$/i', '.log', $auditPath) ?? ($auditPath . '.log');
        $candidates[] = dirname($auditPath) . DIRECTORY_SEPARATOR . pathinfo($auditPath, PATHINFO_FILENAME) . '.log';

        foreach ($candidates as $candidate) {
            if (is_string($candidate) && is_file($candidate)) {
                return $candidate;
            }
        }

        return null;
    }

    /**
     * @param array<string, mixed> $hydration
     * @return list<string>
     */
    private function countableArtifactLabels(array $hydration): array
    {
        $set = is_array($hydration['set'] ?? null) ? $hydration['set'] : [];
        $labels = is_array($set['countable_labels'] ?? null) ? $set['countable_labels'] : [];
        $labels = array_values(array_filter($labels, 'is_string'));
        sort($labels);

        return $labels;
    }

    /**
     * @param array<string, mixed> $hydration
     */
    private function artifactDirectoryTestsTotal(array $hydration): int
    {
        $set = is_array($hydration['set'] ?? null) ? $hydration['set'] : [];

        return is_int($set['tests_total'] ?? null) ? $set['tests_total'] : 0;
    }

    /**
     * @param mixed $entries
     * @return array<string, array<string, mixed>>
     */
    private function artifactDirectoryEntriesBySuiteKey(mixed $entries): array
    {
        if (!is_array($entries)) {
            return [];
        }

        $keyed = [];
        foreach ($entries as $entry) {
            if (!is_array($entry)) {
                continue;
            }

            $key = $this->artifactEntrySuiteKey($entry);
            if ($key === '') {
                continue;
            }

            if (!isset($keyed[$key]) || $this->artifactEntryRank($entry) > $this->artifactEntryRank($keyed[$key])) {
                $keyed[$key] = $entry;
            }
        }

        ksort($keyed);

        return $keyed;
    }

    /**
     * @param array<string, mixed> $entry
     */
    private function artifactEntrySuiteKey(array $entry): string
    {
        $artifact = is_array($entry['gate']['artifact'] ?? null) ? $entry['gate']['artifact'] : [];
        $requested = is_array($artifact['requested'] ?? null) ? $artifact['requested'] : [];
        $testset = is_string($requested['testset'] ?? null) && $requested['testset'] !== ''
            ? strtolower($requested['testset'])
            : 'unknown';
        $patterns = [];
        if (is_array($requested['patterns'] ?? null)) {
            foreach ($requested['patterns'] as $pattern) {
                if (is_string($pattern) && $pattern !== '') {
                    $patterns[] = $pattern;
                }
            }
        }

        sort($patterns);

        return $testset . ':' . ($patterns === [] ? 'none' : implode(',', $patterns));
    }

    /**
     * @param array<string, mixed> $entry
     */
    private function artifactEntrySuiteId(array $entry, string $fallback): string
    {
        $artifact = is_array($entry['gate']['artifact'] ?? null) ? $entry['gate']['artifact'] : [];
        $requested = is_array($artifact['requested'] ?? null) ? $artifact['requested'] : [];
        $testset = is_string($requested['testset'] ?? null) && $requested['testset'] !== ''
            ? strtolower($requested['testset'])
            : 'unknown';
        $patterns = [];
        if (is_array($requested['patterns'] ?? null)) {
            foreach ($requested['patterns'] as $pattern) {
                if (is_string($pattern) && $pattern !== '') {
                    $patterns[] = preg_replace('/[^A-Za-z0-9_.-]+/', '-', $pattern) ?? $pattern;
                }
            }
        }

        sort($patterns);
        if ($patterns === []) {
            return $testset;
        }

        return $testset . '-' . implode('-', $patterns);
    }

    /**
     * @param array<string, mixed> $entry
     */
    private function artifactEntryTier(array $entry): string
    {
        $artifact = is_array($entry['gate']['artifact'] ?? null) ? $entry['gate']['artifact'] : [];
        $requested = is_array($artifact['requested'] ?? null) ? $artifact['requested'] : [];
        $testset = is_string($requested['testset'] ?? null) && $requested['testset'] !== ''
            ? strtolower($requested['testset'])
            : 'unknown';
        if (in_array($testset, ['all', 'release', 'mptest'], true)) {
            return $testset;
        }

        return is_array($requested['patterns'] ?? null) && $requested['patterns'] !== [] ? 'focused' : $testset;
    }

    /**
     * @param array<string, mixed> $entry
     */
    private function artifactEntryRank(array $entry): int
    {
        if ((bool) ($entry['countable'] ?? false)) {
            return 4;
        }

        $status = is_string($entry['status'] ?? null) ? $entry['status'] : '';

        return match ($status) {
            'active' => 3,
            'blocked' => 2,
            default => 1,
        };
    }

    /**
     * @return list<string>
     */
    private function boundedRunnerAuditArtifactPaths(string $artifactDirectory): array
    {
        $paths = [];
        foreach (['*.md', '*.audit'] as $pattern) {
            $matches = glob(rtrim($artifactDirectory, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR . $pattern);
            if ($matches === false) {
                continue;
            }

            foreach ($matches as $path) {
                if (is_file($path)) {
                    $paths[] = $path;
                }
            }
        }

        $paths = array_values(array_unique($paths));
        sort($paths, SORT_STRING);

        return $paths;
    }

    /**
     * @return list<string>
     */
    private function extractBacktickListField(string $text, string $field): array
    {
        $quotedField = preg_quote($field, '/');
        if (preg_match('/-\s+' . $quotedField . ':\s+([^\r\n]+)/i', $text, $matches) !== 1) {
            return [];
        }

        if (preg_match_all('/`([^`]*)`/', $matches[1], $values) < 1) {
            $raw = trim($matches[1]);
            return $raw === '' ? [] : [$raw];
        }

        return array_values(array_filter($values[1], 'strlen'));
    }

    private function extractIntegerBacktickField(string $text, string $field): ?int
    {
        $value = $this->extractBacktickField($text, $field);
        if ($value === null || !preg_match('/^-?\d+$/', $value)) {
            return null;
        }

        return (int) $value;
    }

    /**
     * @return array{completed: int|null, total: int|null, last_line: string|null}
     */
    private function parseRunnerProgress(string $stdoutText): array
    {
        $completed = null;
        $total = null;
        $lastLine = null;

        foreach (preg_split('/\R/', $stdoutText) ?: [] as $line) {
            $trimmed = trim($line);
            if ($trimmed === '') {
                continue;
            }

            if (preg_match('/tcl\((\d+)\/(\d+)\)/', $trimmed, $matches) === 1) {
                $completed = (int) $matches[1];
                $total = (int) $matches[2];
                $lastLine = $trimmed;
            }
        }

        return [
            'completed' => $completed,
            'total' => $total,
            'last_line' => $lastLine,
        ];
    }

    /**
     * @return list<array<string, mixed>>
     */
    private function extractRunnerFailures(string $text): array
    {
        $failures = [];
        if ($text === '') {
            return $failures;
        }

        if (preg_match_all('/FAILED:\s+([^\r\n]+)(.*?)(?=\nFAILED:|\n## |\z)/s', $text, $matches, PREG_SET_ORDER) !== false) {
            foreach ($matches as $match) {
                $label = trim($match[1]);
                $body = $match[2] ?? '';
                $failure = [
                    'label' => $label,
                    'script' => null,
                    'kind' => null,
                    'case' => null,
                    'diagnostic' => null,
                ];

                if (preg_match('/\b((?:ext\/)?[A-Za-z0-9_\/.-]+\.test)\b/', $label, $scriptMatch) === 1) {
                    $failure['script'] = $scriptMatch[1];
                }
                if (preg_match('/^([A-Za-z0-9_ -]+?)\s+(?:ext\/)?[A-Za-z0-9_\/.-]+\.test\b/', $label, $kindMatch) === 1) {
                    $failure['kind'] = trim($kindMatch[1]);
                }
                if (preg_match_all('/([A-Za-z0-9_\/.-]+-\d+(?:\.\d+)*)\.\.\./', $body, $caseMatches) !== false && $caseMatches[1] !== []) {
                    $failure['case'] = end($caseMatches[1]);
                }
                if (preg_match('/SUMMARY:\s+([^\r\n]+)/', $body, $summaryMatch) === 1) {
                    $failure['diagnostic'] = trim($summaryMatch[1]);
                } elseif (preg_match('/runtime error:\s+([^\r\n]+)/', $body, $runtimeMatch) === 1) {
                    $failure['diagnostic'] = 'runtime error: ' . trim($runtimeMatch[1]);
                }

                $failures[] = $failure;
            }
        }

        return $failures;
    }

    /**
     * @param list<array<string, mixed>> $failures
     * @return list<array<string, mixed>>
     */
    private function classifyRunnerFailureBlockers(array $failures): array
    {
        $blockers = [];
        foreach ($failures as $failure) {
            $diagnostic = is_string($failure['diagnostic'] ?? null) ? $failure['diagnostic'] : '';
            $script = is_string($failure['script'] ?? null) ? $failure['script'] : null;
            $case = is_string($failure['case'] ?? null) ? $failure['case'] : null;
            $kind = is_string($failure['kind'] ?? null) ? $failure['kind'] : null;

            $id = 'upstream-runner-failure';
            $category = 'upstream-suite-failure';
            $nextGate = 'keep the release/all artifact uncounted, then rerun only after a focused repro explains whether the failed script is an upstream/runtime issue or a native parity issue';
            if (str_contains($diagnostic, 'UndefinedBehaviorSanitizer') || str_contains($diagnostic, 'runtime error: applying non-zero offset')) {
                $id = 'upstream-runtime-sanitizer';
                $category = 'upstream-runtime-environment';
                $nextGate = 'record as failed release-runner evidence; rerun release only with a supervisor-approved sanitizer decision or a focused repro for the exact script and case';
            }

            $blockers[] = [
                'id' => $id,
                'category' => $category,
                'script' => $script,
                'case' => $case,
                'kind' => $kind,
                'diagnostic' => $diagnostic === '' ? null : $diagnostic,
                'next_gate' => $nextGate,
            ];
        }

        return $blockers;
    }

    /**
     * @param array<int, array<string, mixed>> $artifacts
     * @return array{entries:list<array<string, mixed>>,countable_count:int,blockers:list<array<string, mixed>>}
     */
    private function releaseFailureLedgerEntries(array $artifacts, string $acceptedHead): array
    {
        $expectedManifestUuid = is_string($this->manifest['upstream']['officialManifestUuid'] ?? null)
            ? $this->manifest['upstream']['officialManifestUuid']
            : null;

        $entries = [];
        $blockers = [];
        $countable = 0;
        foreach ($artifacts as $index => $artifact) {
            if (!is_array($artifact)) {
                $blockers[] = [
                    'id' => 'release-artifact-invalid',
                    'index' => $index,
                    'evidence' => 'failed release artifact entry is not an object',
                ];
                continue;
            }

            $results = is_array($artifact['results'] ?? null) ? $artifact['results'] : [];
            $requested = is_array($artifact['requested'] ?? null) ? $artifact['requested'] : [];
            $failureBlockers = is_array($results['failure_blockers'] ?? null) ? $results['failure_blockers'] : [];
            $testset = is_string($requested['testset'] ?? null) ? $requested['testset'] : null;
            $manifestUuid = is_string($artifact['sqlite_manifest_uuid'] ?? null) ? $artifact['sqlite_manifest_uuid'] : null;
            $repositoryHead = is_string($artifact['repository_head'] ?? null) ? $artifact['repository_head'] : null;

            $entryBlockers = [];
            if (($artifact['status'] ?? null) !== 'failed') {
                $entryBlockers[] = 'release-artifact-not-failed';
            }
            if (!in_array($testset, ['all', 'release'], true)) {
                $entryBlockers[] = 'release-artifact-not-release-tier';
            }
            if ($repositoryHead !== $acceptedHead) {
                $entryBlockers[] = 'repository-head-mismatch';
            }
            if ($expectedManifestUuid === null || $manifestUuid !== $expectedManifestUuid) {
                $entryBlockers[] = 'sqlite-manifest-uuid-mismatch';
            }

            $primary = null;
            foreach ($failureBlockers as $failureBlocker) {
                if (!is_array($failureBlocker)) {
                    continue;
                }
                if (($failureBlocker['category'] ?? null) === 'upstream-runtime-environment') {
                    $primary = $failureBlocker;
                    break;
                }
                if ($primary === null) {
                    $primary = $failureBlocker;
                }
            }
            if ($primary === null) {
                $entryBlockers[] = 'release-artifact-missing-failure-blocker';
            }

            $script = is_array($primary) && is_string($primary['script'] ?? null) ? $primary['script'] : null;
            $case = is_array($primary) && is_string($primary['case'] ?? null) ? $primary['case'] : null;
            $category = is_array($primary) && is_string($primary['category'] ?? null) ? $primary['category'] : null;
            $failureKey = implode('#', array_filter([$script, $case, $category], static fn (?string $part): bool => $part !== null && $part !== ''));
            if ($failureKey === '') {
                $failureKey = 'artifact-' . $index;
            }

            $isCountable = $entryBlockers === [];
            if ($isCountable) {
                $countable++;
            } else {
                $blockers[] = [
                    'id' => 'release-failure-entry-blocked',
                    'index' => $index,
                    'label' => $artifact['label'] ?? null,
                    'blocker_ids' => $entryBlockers,
                ];
            }

            $entries[] = [
                'index' => $index,
                'label' => $artifact['label'] ?? null,
                'countable' => $isCountable,
                'blocker_ids' => $entryBlockers,
                'failure_key' => $failureKey,
                'script' => $script,
                'case' => $case,
                'category' => $category,
                'repository_head' => $repositoryHead,
                'testset' => $testset,
                'tests' => $results['tests'] ?? null,
                'errors' => $results['errors'] ?? null,
                'exit' => $results['exit'] ?? null,
            ];
        }

        return [
            'entries' => $entries,
            'countable_count' => $countable,
            'blockers' => $blockers,
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public function focusedPhpPassAdmission(
        int $currentPhpPass,
        string $focusedPath,
        string $testOutput,
        string $nonOverlapNote
    ): array {
        if ($currentPhpPass < 0) {
            throw new \InvalidArgumentException('SQLite focused phpPass admission needs a non-negative current pass count');
        }
        if (!preg_match('#^lanes/libsqlite/tests/[A-Za-z0-9_./-]+Test\.php$#', $focusedPath)) {
            throw new \InvalidArgumentException('SQLite focused phpPass admission requires a lane-local focused test path');
        }
        if (trim($nonOverlapNote) === '') {
            throw new \InvalidArgumentException('SQLite focused phpPass admission requires a non-overlap note');
        }

        $parsed = $this->parseFocusedPhpTestOutput($testOutput);
        $admitted = $parsed['focused']
            && $parsed['selected_test_files'] === 1
            && $parsed['summary_test_files'] === 1
            && $parsed['assertions'] > 0
            && $parsed['failures'] === 0;
        $delta = $admitted ? $parsed['assertions'] : 0;

        return [
            'status' => $admitted ? 'admitted' : 'blocked',
            'focused_path' => $focusedPath,
            'current_php_pass' => $currentPhpPass,
            'assertion_delta' => $delta,
            'next_php_pass' => $currentPhpPass + $delta,
            'selected_test_files' => $parsed['selected_test_files'],
            'summary_test_files' => $parsed['summary_test_files'],
            'failures' => $parsed['failures'],
            'focused_output_seen' => $parsed['focused'],
            'non_overlap_note' => trim($nonOverlapNote),
            'dependency_closure' => 'no new support component needed; phpPass admission reuses local TestRunner output only',
            'blocker' => $admitted ? null : $this->focusedPhpPassAdmissionBlocker($parsed),
        ];
    }

    /**
     * @return array<string, mixed>
     */
    public function focusedPhpPassCurrentHeadAdmission(
        int $currentPhpPass,
        string $acceptedRepositoryHead,
        string $evidenceRepositoryHead,
        string $focusedPath,
        string $testOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null
    ): array {
        if (trim($acceptedRepositoryHead) === '') {
            throw new \InvalidArgumentException('SQLite focused phpPass current-head admission requires an accepted repository HEAD');
        }
        if (trim($evidenceRepositoryHead) === '') {
            throw new \InvalidArgumentException('SQLite focused phpPass current-head admission requires an evidence repository HEAD');
        }
        if ($expectedPassDelta !== null && $expectedPassDelta < 0) {
            throw new \InvalidArgumentException('SQLite focused phpPass current-head admission requires a non-negative expected PASS delta');
        }
        if ($currentPhpPass < 0) {
            throw new \InvalidArgumentException('SQLite focused phpPass admission needs a non-negative current pass count');
        }
        if (!preg_match('#^lanes/libsqlite/tests/[A-Za-z0-9_./-]+Test\.php$#', $focusedPath)) {
            throw new \InvalidArgumentException('SQLite focused phpPass admission requires a lane-local focused test path');
        }
        if (trim($nonOverlapNote) === '') {
            throw new \InvalidArgumentException('SQLite focused phpPass admission requires a non-overlap note');
        }

        $parsed = $this->parseFocusedPhpTestOutput($testOutput);
        $blockers = [];
        if (!$parsed['focused']) {
            $blockers[] = [
                'id' => 'missing-focused-testrunner-output',
                'evidence' => 'Focused TestRunner marker is required before phpPass can move',
            ];
        }
        if ($parsed['selected_test_files'] !== 1 || $parsed['summary_test_files'] !== 1) {
            $blockers[] = [
                'id' => 'focused-test-file-count-not-one',
                'evidence' => 'phpPass admission requires exactly one focused lane test file for this slice',
                'selected_test_files' => $parsed['selected_test_files'],
                'summary_test_files' => $parsed['summary_test_files'],
            ];
        }
        if ($parsed['failures'] !== 0) {
            $blockers[] = [
                'id' => 'focused-output-has-failures',
                'evidence' => 'focused TestRunner output contains failures',
                'failures' => $parsed['failures'],
            ];
        }
        if ($parsed['pass_lines'] <= 0) {
            $blockers[] = [
                'id' => 'focused-pass-lines-missing',
                'evidence' => 'focused TestRunner output has no PASS lines to count',
            ];
        }
        if ($acceptedRepositoryHead !== $evidenceRepositoryHead) {
            $blockers[] = [
                'id' => 'repository-head-mismatch',
                'expected' => $acceptedRepositoryHead,
                'actual' => $evidenceRepositoryHead,
                'evidence' => 'focused phpPass evidence must be produced from the current accepted repository HEAD',
            ];
        }
        if ($expectedPassDelta !== null && $expectedPassDelta !== $parsed['pass_lines']) {
            $blockers[] = [
                'id' => 'focused-pass-delta-mismatch',
                'expected' => $expectedPassDelta,
                'actual' => $parsed['pass_lines'],
                'evidence' => 'expected phpPass delta must match exact focused PASS-line count',
            ];
        }

        $admitted = $blockers === [];
        $delta = $admitted ? $parsed['pass_lines'] : 0;

        return [
            'status' => $admitted ? 'current-head-focused-pass-countable' : 'blocked',
            'focused_path' => $focusedPath,
            'accepted_repository_head' => $acceptedRepositoryHead,
            'evidence_repository_head' => $evidenceRepositoryHead,
            'current_php_pass' => $currentPhpPass,
            'pass_delta' => $delta,
            'assertion_count_observed' => $parsed['assertions'],
            'pass_lines_observed' => $parsed['pass_lines'],
            'expected_pass_delta' => $expectedPassDelta,
            'next_php_pass' => $currentPhpPass + $delta,
            'selected_test_files' => $parsed['selected_test_files'],
            'summary_test_files' => $parsed['summary_test_files'],
            'failures' => $parsed['failures'],
            'focused_output_seen' => $parsed['focused'],
            'non_overlap_note' => trim($nonOverlapNote),
            'countable' => $admitted,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'next_gate' => $admitted
                ? 'publish the exact focused PASS-line delta for this current accepted HEAD only'
                : 'rerun the focused lane test from the accepted HEAD and preserve exact PASS-line evidence before moving phpPass',
            'dependency_closure' => 'no new support component needed; current-head phpPass admission reuses local focused TestRunner output only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $candidateRows
     * @param list<string> $queuedSurfaces
     * @return array<string, mixed>
     */
    public function releaseRunnerCurrentDenominatorDecision(
        array $candidateRows,
        array $queuedSurfaces,
        string $acceptedBaseHead,
        int $currentMapped,
        int $currentPhpPass,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote
    ): array {
        if ($acceptedBaseHead === '') {
            throw new \InvalidArgumentException('SQLite current-next62 denominator decision requires an accepted base HEAD');
        }
        if ($currentMapped < 0) {
            throw new \InvalidArgumentException('SQLite current-next62 denominator decision requires a non-negative current mapped count');
        }
        if ($candidateRows === []) {
            throw new \InvalidArgumentException('SQLite current-next62 denominator decision requires at least one candidate row');
        }

        $queued = [];
        foreach ($queuedSurfaces as $surface) {
            if (is_string($surface) && $surface !== '') {
                $queued[$surface] = true;
            }
        }

        $phpAdmission = $this->focusedPhpPassAdmission(
            $currentPhpPass,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote
        );

        $entries = [];
        $accepted = [];
        $preserved = [];
        $blocked = [];
        $families = [];
        $blockers = [];
        $seen = [];
        $testsDelta = 0;

        foreach ($candidateRows as $label => $row) {
            if (!is_array($row)) {
                $blockers[] = [
                    'id' => 'candidate-row-invalid',
                    'candidate' => is_string($label) ? $label : 'row-' . (string) count($entries),
                    'evidence' => 'candidate row is not an array',
                ];
                continue;
            }

            $id = is_string($row['id'] ?? null) && $row['id'] !== ''
                ? $row['id']
                : (is_string($label) ? $label : 'candidate-' . (string) count($entries));
            $family = is_string($row['family'] ?? null) && $row['family'] !== '' ? $row['family'] : 'suite-denominator';
            $surface = is_string($row['surface'] ?? null) && $row['surface'] !== '' ? $row['surface'] : $id;
            $baseHead = is_string($row['base_head'] ?? null) ? $row['base_head'] : '';
            $evidence = is_string($row['evidence'] ?? null) ? trim($row['evidence']) : '';
            $currentStatus = is_string($row['current_status'] ?? null) ? $row['current_status'] : 'missing';
            $nextStatus = is_string($row['next_status'] ?? null) ? $row['next_status'] : 'missing';
            $tests = max(0, (int) ($row['tests_delta'] ?? 0));
            $releaseParityClaim = (bool) ($row['release_parity'] ?? false);
            $rowBlockers = [];

            if (isset($seen[$id])) {
                $rowBlockers[] = 'duplicate-current-next62-denominator-id';
            }
            $seen[$id] = true;

            if ($baseHead !== $acceptedBaseHead) {
                $rowBlockers[] = 'candidate-base-head-mismatch';
            }
            if (isset($queued[$surface])) {
                $rowBlockers[] = 'candidate-surface-already-queued-or-accepted';
            }
            if ($evidence === '') {
                $rowBlockers[] = 'candidate-missing-focused-evidence';
            }
            if ($releaseParityClaim) {
                $rowBlockers[] = 'release-all-parity-claim-not-admitted';
            }
            foreach (is_array($row['blockers'] ?? null) ? $row['blockers'] : [] as $blocker) {
                if (is_string($blocker) && $blocker !== '') {
                    $rowBlockers[] = $blocker;
                }
            }
            if (is_string($row['blocker'] ?? null) && $row['blocker'] !== '') {
                $rowBlockers[] = $row['blocker'];
            }

            $currentRowMapped = $currentStatus === 'mapped';
            $nextRowMapped = $nextStatus === 'mapped';
            $movement = 'open';
            if ($rowBlockers !== []) {
                $movement = 'blocked';
                $blocked[] = $id;
            } elseif ($nextRowMapped && !$currentRowMapped) {
                $movement = 'accepted-next-denominator';
                $accepted[] = $id;
                $testsDelta += $tests;
            } elseif ($nextRowMapped && $currentRowMapped) {
                $movement = 'preserved';
                $preserved[] = $id;
            }

            foreach (array_values(array_unique($rowBlockers)) as $blocker) {
                $blockers[] = [
                    'id' => 'current-next62-candidate-blocked',
                    'candidate' => $id,
                    'surface' => $surface,
                    'evidence' => $blocker,
                ];
            }

            if (!isset($families[$family])) {
                $families[$family] = [
                    'family' => $family,
                    'rows' => 0,
                    'accepted' => 0,
                    'preserved' => 0,
                    'blocked' => 0,
                    'open' => 0,
                    'tests_delta' => 0,
                ];
            }
            $families[$family]['rows']++;
            $families[$family][$movement === 'accepted-next-denominator' ? 'accepted' : $movement]++;
            $families[$family]['tests_delta'] += $movement === 'accepted-next-denominator' ? $tests : 0;

            $entries[] = [
                'id' => $id,
                'family' => $family,
                'surface' => $surface,
                'base_head' => $baseHead,
                'current_status' => $currentStatus,
                'next_status' => $nextStatus,
                'movement' => $movement,
                'tests_delta' => $tests,
                'evidence' => $evidence,
                'blockers' => array_values(array_unique($rowBlockers)),
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'admitted') {
            $blockers[] = [
                'id' => 'focused-php-pass-admission-blocked',
                'candidate' => 'focused-output',
                'surface' => 'suite-denominator-current-next62',
                'evidence' => $phpAdmission['blocker'] ?? 'focused PHP output did not satisfy admission gates',
            ];
        }

        ksort($families);
        sort($accepted);
        sort($preserved);
        sort($blocked);

        $mappedDelta = $blockers === [] ? count($accepted) : 0;
        $status = 'blocked';
        if ($blockers === [] && $accepted !== []) {
            $status = 'current-next62-denominator-admitted';
        } elseif ($blockers === [] && $preserved !== []) {
            $status = 'current-next62-denominator-preserved';
        }

        return [
            'status' => $status,
            'accepted_base_head' => $acceptedBaseHead,
            'row_count' => count($entries),
            'family_count' => count($families),
            'current_mapped' => $currentMapped,
            'next_mapped' => $currentMapped + $mappedDelta,
            'mapped_delta' => $mappedDelta,
            'accepted_count' => count($accepted),
            'accepted_ids' => $accepted,
            'preserved_count' => count($preserved),
            'preserved_ids' => $preserved,
            'blocked_count' => count($blocked),
            'blocked_ids' => $blocked,
            'queued_surface_count' => count($queued),
            'families' => array_values($families),
            'entries' => $entries,
            'tests_total_delta' => $blockers === [] ? $testsDelta : 0,
            'php_pass_admission' => $phpAdmission,
            'php_pass_delta' => $blockers === [] ? (int) ($phpAdmission['assertion_delta'] ?? 0) : 0,
            'next_php_pass' => $blockers === [] ? (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass) : $currentPhpPass,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_denominator_current_next62' => $status === 'current-next62-denominator-admitted',
            'counts_release_parity' => false,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => $status === 'current-next62-denominator-admitted'
                ? 'publish only the current-next62 admitted denominator row and keep release/all parity gated on accepted-head zero-error broad artifacts'
                : 'repair stale-base, duplicate-surface, missing-evidence, or unfocused current-next62 candidates before moving denominator counts',
            'dependency_closure' => 'no new support component needed; current-next62 denominator decision composes lane-local candidate rows, queued-surface guards, accepted-base provenance, and focused PHP TestRunner admission only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $denominatorRows
     * @return array<string, mixed>
     */
    public function suiteDenominatorCountability(
        array $denominatorRows,
        int $currentMapped,
        int $currentPhpPass,
        string $acceptedRepositoryHead,
        string $evidenceRepositoryHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        if ($denominatorRows === []) {
            throw new \InvalidArgumentException('SQLite suite denominator admission requires at least one row');
        }
        if ($currentMapped < 0) {
            throw new \InvalidArgumentException('SQLite suite denominator admission needs a non-negative current mapped count');
        }

        $phpAdmission = $this->focusedPhpPassCurrentHeadAdmission(
            $currentPhpPass,
            $acceptedRepositoryHead,
            $evidenceRepositoryHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta
        );
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $entries = [];
        $blockers = [];
        $newUnits = [];
        $preservedUnits = [];
        $blockedUnits = [];
        $regressedUnits = [];
        $scripts = [];
        $currentMappedRows = 0;
        $nextMappedRows = 0;
        $currentScriptRows = 0;
        $nextScriptRows = 0;
        $denominatorTotal = 0;
        $categories = [];

        foreach ($denominatorRows as $label => $row) {
            $unit = is_string($label) ? $label : 'suite-denominator-' . count($entries);
            if (!is_array($row)) {
                $blockedUnits[] = $unit;
                $blockers[] = [
                    'id' => 'denominator-row-invalid',
                    'unit' => $unit,
                    'evidence' => 'denominator row must be an array',
                ];
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== '' ? $row['unit'] : $unit;
            $category = is_string($row['category'] ?? null) && $row['category'] !== '' ? $row['category'] : 'suite-denominator';
            $currentRowMapped = max(0, $this->denominatorAuditInt($row, 'current_mapped'));
            $nextRowMapped = max(0, $this->denominatorAuditInt($row, 'next_mapped'));
            $currentScripts = max(0, $this->denominatorAuditInt($row, 'current_countable_scripts'));
            $nextScripts = max(0, $this->denominatorAuditInt($row, 'next_countable_scripts'));
            $total = max(0, $this->denominatorAuditInt($row, 'denominator_total'));
            $rowScripts = array_values(array_filter(
                is_array($row['scripts'] ?? null) ? $row['scripts'] : [],
                static fn (mixed $script): bool => is_string($script) && str_ends_with($script, '.test')
            ));
            sort($rowScripts, SORT_STRING);
            foreach ($rowScripts as $script) {
                $scripts[$script] = true;
            }

            $rowBlockers = [];
            if (($row['evidence'] ?? '') === '') {
                $rowBlockers[] = 'missing-row-evidence';
            }
            if (($row['hydrated'] ?? true) !== true) {
                $rowBlockers[] = 'denominator-row-not-hydrated';
            }
            if ($nextRowMapped < $currentRowMapped) {
                $rowBlockers[] = 'mapped-count-regressed';
            }
            if ($nextScripts < $currentScripts) {
                $rowBlockers[] = 'countable-script-count-regressed';
            }
            if (is_array($row['blockers'] ?? null)) {
                foreach ($row['blockers'] as $blocker) {
                    if (is_string($blocker) && $blocker !== '') {
                        $rowBlockers[] = $blocker;
                    }
                }
            }
            $rowBlockers = array_values(array_unique($rowBlockers));

            $movement = 'preserved';
            if ($rowBlockers !== []) {
                $movement = 'blocked';
                $blockedUnits[] = $unit;
                if (in_array('mapped-count-regressed', $rowBlockers, true) || in_array('countable-script-count-regressed', $rowBlockers, true)) {
                    $regressedUnits[] = $unit;
                }
                $blockers[] = [
                    'id' => 'denominator-row-blocked',
                    'unit' => $unit,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($nextRowMapped > $currentRowMapped || $nextScripts > $currentScripts) {
                $movement = 'advanced';
                $newUnits[] = $unit;
            } else {
                $preservedUnits[] = $unit;
            }

            $categories[$category] = ($categories[$category] ?? 0) + 1;
            $currentMappedRows += $currentRowMapped;
            $nextMappedRows += $nextRowMapped;
            $currentScriptRows += $currentScripts;
            $nextScriptRows += $nextScripts;
            $denominatorTotal += $total;

            $entries[] = [
                'unit' => $unit,
                'category' => $category,
                'movement' => $movement,
                'current_mapped' => $currentRowMapped,
                'next_mapped' => $nextRowMapped,
                'mapped_delta' => $nextRowMapped - $currentRowMapped,
                'current_countable_scripts' => $currentScripts,
                'next_countable_scripts' => $nextScripts,
                'script_delta' => $nextScripts - $currentScripts,
                'denominator_total' => $total,
                'scripts' => $rowScripts,
                'blocker_ids' => $rowBlockers,
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'current-head-focused-pass-countable') {
            $blockers[] = [
                'id' => 'focused-current-head-php-pass-blocked',
                'evidence' => 'focused PHP PASS-line admission did not satisfy current-head gates',
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
            ];
        }

        ksort($categories, SORT_STRING);
        sort($newUnits, SORT_STRING);
        sort($preservedUnits, SORT_STRING);
        sort($blockedUnits, SORT_STRING);
        sort($regressedUnits, SORT_STRING);
        $scriptList = array_keys($scripts);
        sort($scriptList, SORT_STRING);

        $mappedDelta = max(0, $nextMappedRows - $currentMappedRows);
        $scriptDelta = max(0, $nextScriptRows - $currentScriptRows);
        $status = 'blocked';
        if ($blockers === [] && ($mappedDelta > 0 || $scriptDelta > 0)) {
            $status = 'suite-denominator-countable';
        } elseif ($blockers === []) {
            $status = 'suite-denominator-preserved';
        }

        return [
            'status' => $status,
            'countable' => $status === 'suite-denominator-countable',
            'accepted_repository_head' => $acceptedRepositoryHead,
            'evidence_repository_head' => $evidenceRepositoryHead,
            'current_mapped' => $currentMapped,
            'next_mapped' => $blockers === [] ? $currentMapped + $mappedDelta : $currentMapped,
            'mapped_delta' => $blockers === [] ? $mappedDelta : 0,
            'row_current_mapped_total' => $currentMappedRows,
            'row_next_mapped_total' => $nextMappedRows,
            'countable_script_delta' => $blockers === [] ? $scriptDelta : 0,
            'current_countable_scripts' => $currentScriptRows,
            'next_countable_scripts' => $nextScriptRows,
            'denominator_total' => $denominatorTotal,
            'row_count' => count($entries),
            'category_count' => count($categories),
            'categories' => $categories,
            'target_script_count' => count($scriptList),
            'target_scripts' => $scriptList,
            'advanced_units' => $newUnits,
            'preserved_units' => $preservedUnits,
            'blocked_units' => $blockedUnits,
            'regressed_units' => $regressedUnits,
            'entries' => $entries,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'php_pass_admission' => $phpAdmission,
            'php_pass_delta' => $blockers === [] ? (int) ($phpAdmission['pass_delta'] ?? 0) : 0,
            'next_php_pass' => $blockers === [] ? (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass) : $currentPhpPass,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_release_parity' => false,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => $status === 'suite-denominator-countable'
                ? 'publish only the suite denominator/script movement with exact current-head focused PASS-line evidence; release/all parity remains gated'
                : 'keep suite denominator movement uncounted until row evidence, duplicate-runner, and focused PASS-line blockers are clear',
            'dependency_closure' => 'no new support component needed; suite denominator admission composes lane-local rows, active-runner gating, and current-head focused TestRunner PASS-line output only',
        ];
    }

