    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function suiteDenominatorArtifactAdmission(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $acceptedRepositoryHead,
        string $evidenceRepositoryHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        if ($artifactRows === []) {
            throw new \InvalidArgumentException('SQLite suite denominator artifact admission requires at least one artifact row');
        }
        if ($currentMapped < 0) {
            throw new \InvalidArgumentException('SQLite suite denominator artifact admission needs a non-negative current mapped count');
        }

        $phpAdmission = $this->focusedPhpPassCurrentHeadAdmission(
            $currentPhpPass,
            $acceptedRepositoryHead,
            $evidenceRepositoryHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta
        );
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $entries = [];
        $blockers = [];
        $seen = [];
        $advanced = [];
        $preserved = [];
        $blocked = [];
        $regressed = [];
        $scripts = [];
        $categories = [];
        $testsBefore = 0;
        $testsAfter = 0;
        $mappedDelta = 0;
        $countableArtifacts = 0;

        foreach ($artifactRows as $label => $row) {
            $fallbackUnit = is_string($label) ? $label : 'suite-denominator-artifact-' . count($entries);
            if (!is_array($row)) {
                $blocked[] = $fallbackUnit;
                $blockers[] = [
                    'id' => 'artifact-row-invalid',
                    'unit' => $fallbackUnit,
                    'evidence' => 'artifact row must be an array',
                ];
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== '' ? $row['unit'] : $fallbackUnit;
            $category = is_string($row['category'] ?? null) && $row['category'] !== '' ? $row['category'] : 'suite-denominator-artifact';
            $artifactHead = is_string($row['repository_head'] ?? null) ? trim($row['repository_head']) : '';
            $currentStatus = is_string($row['current_status'] ?? null) ? $row['current_status'] : 'missing';
            $nextStatus = is_string($row['next_status'] ?? null) ? $row['next_status'] : 'missing';
            $currentCountable = (bool) ($row['current_countable'] ?? in_array($currentStatus, ['countable', 'mapped'], true));
            $nextCountable = (bool) ($row['next_countable'] ?? in_array($nextStatus, ['countable', 'mapped'], true));
            $testsCurrent = max(0, $this->denominatorAuditInt($row, 'current_tests'));
            $testsNext = max(0, $this->denominatorAuditInt($row, 'next_tests'));
            $rowScripts = array_values(array_unique(array_filter(
                is_array($row['scripts'] ?? null) ? $row['scripts'] : [],
                static fn (mixed $script): bool => is_string($script) && str_ends_with($script, '.test')
            )));
            sort($rowScripts, SORT_STRING);
            foreach ($rowScripts as $script) {
                $scripts[$script] = true;
            }

            $rowBlockers = [];
            if (isset($seen[$unit])) {
                $rowBlockers[] = 'duplicate-artifact-unit';
            }
            $seen[$unit] = true;
            if ($artifactHead !== $acceptedRepositoryHead) {
                $rowBlockers[] = 'artifact-head-mismatch';
            }
            if (($row['artifact_path'] ?? '') === '') {
                $rowBlockers[] = 'missing-artifact-path';
            }
            if (($row['evidence'] ?? '') === '') {
                $rowBlockers[] = 'missing-artifact-evidence';
            }
            if ($nextCountable && $rowScripts === []) {
                $rowBlockers[] = 'countable-artifact-missing-test-scripts';
            }
            if ($currentCountable && !$nextCountable) {
                $rowBlockers[] = 'countable-artifact-regressed';
            }
            if ($testsNext < $testsCurrent) {
                $rowBlockers[] = 'artifact-test-count-regressed';
            }
            foreach (is_array($row['blockers'] ?? null) ? $row['blockers'] : [] as $rowBlocker) {
                if (is_string($rowBlocker) && $rowBlocker !== '') {
                    $rowBlockers[] = $rowBlocker;
                }
            }
            $rowBlockers = array_values(array_unique($rowBlockers));

            $movement = 'open';
            if ($rowBlockers !== []) {
                $movement = 'blocked';
                $blocked[] = $unit;
                if (in_array('countable-artifact-regressed', $rowBlockers, true) || in_array('artifact-test-count-regressed', $rowBlockers, true)) {
                    $regressed[] = $unit;
                }
                $blockers[] = [
                    'id' => 'artifact-row-blocked',
                    'unit' => $unit,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($nextCountable && !$currentCountable) {
                $movement = 'advanced';
                $advanced[] = $unit;
                $mappedDelta++;
                $countableArtifacts++;
            } elseif ($nextCountable) {
                $movement = 'preserved';
                $preserved[] = $unit;
                $countableArtifacts++;
            }

            if ($currentCountable) {
                $testsBefore += $testsCurrent;
            }
            if ($nextCountable) {
                $testsAfter += $testsNext;
            }
            $categories[$category] = ($categories[$category] ?? 0) + 1;

            $entries[] = [
                'unit' => $unit,
                'category' => $category,
                'movement' => $movement,
                'repository_head' => $artifactHead,
                'current_countable' => $currentCountable,
                'next_countable' => $nextCountable,
                'current_tests' => $testsCurrent,
                'next_tests' => $testsNext,
                'scripts' => $rowScripts,
                'blocker_ids' => $rowBlockers,
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'current-head-focused-pass-countable') {
            $blockers[] = [
                'id' => 'focused-current-head-php-pass-blocked',
                'evidence' => 'focused PHP PASS-line admission did not satisfy current-head gates',
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
            ];
        }

        ksort($categories, SORT_STRING);
        sort($advanced, SORT_STRING);
        sort($preserved, SORT_STRING);
        sort($blocked, SORT_STRING);
        sort($regressed, SORT_STRING);
        $scriptList = array_keys($scripts);
        sort($scriptList, SORT_STRING);

        $status = 'blocked';
        if ($blockers === [] && $mappedDelta > 0) {
            $status = 'suite-denominator-artifact-countable';
        } elseif ($blockers === []) {
            $status = 'suite-denominator-artifact-preserved';
        }

        return [
            'status' => $status,
            'countable' => $status === 'suite-denominator-artifact-countable',
            'accepted_repository_head' => $acceptedRepositoryHead,
            'evidence_repository_head' => $evidenceRepositoryHead,
            'current_mapped' => $currentMapped,
            'next_mapped' => $blockers === [] ? $currentMapped + $mappedDelta : $currentMapped,
            'mapped_delta' => $blockers === [] ? $mappedDelta : 0,
            'current_php_pass' => $currentPhpPass,
            'php_pass_delta' => $blockers === [] ? (int) ($phpAdmission['pass_delta'] ?? 0) : 0,
            'next_php_pass' => $blockers === [] ? (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass) : $currentPhpPass,
            'row_count' => count($entries),
            'category_count' => count($categories),
            'categories' => $categories,
            'countable_artifact_count' => $blockers === [] ? $countableArtifacts : 0,
            'current_tests_total' => $testsBefore,
            'next_tests_total' => $testsAfter,
            'tests_total_delta' => $blockers === [] ? max(0, $testsAfter - $testsBefore) : 0,
            'target_script_count' => count($scriptList),
            'target_scripts' => $scriptList,
            'advanced_units' => $advanced,
            'preserved_units' => $preserved,
            'blocked_units' => $blocked,
            'regressed_units' => $regressed,
            'entries' => $entries,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'php_pass_admission' => $phpAdmission,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_release_parity' => false,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => $status === 'suite-denominator-artifact-countable'
                ? 'publish accepted-HEAD artifact denominator movement with exact focused PASS-line evidence; keep release/all parity gated on a zero-error broad artifact'
                : 'keep suite denominator artifact movement uncounted until artifact provenance, row evidence, duplicate-runner, and focused PASS-line blockers are clear',
            'dependency_closure' => 'no new support component needed; suite denominator artifact admission composes lane-local artifact rows, accepted-HEAD provenance, duplicate-runner gating, and exact focused TestRunner PASS-line output only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $denominatorRows
     * @return array<string, mixed>
     */
    public function suiteDenominatorShardAudit(
        array $denominatorRows,
        int $currentMapped,
        int $currentPhpPass,
        string $acceptedRepositoryHead,
        string $evidenceRepositoryHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        $record = $this->suiteDenominatorCountability(
            $denominatorRows,
            $currentMapped,
            $currentPhpPass,
            $acceptedRepositoryHead,
            $evidenceRepositoryHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta,
            $processSnapshot
        );

        $units = [];
        $freshRows = 0;
        $commandRows = 0;
        $artifactRows = 0;
        $blockedRows = [];
        $freshnessBlockers = [];

        foreach ($denominatorRows as $label => $row) {
            $fallbackUnit = is_string($label) ? $label : 'current-next69-' . count($units);
            if (!is_array($row)) {
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== '' ? $row['unit'] : $fallbackUnit;
            if (isset($units[$unit])) {
                $blockedRows[] = $unit;
                $freshnessBlockers[] = [
                    'id' => 'duplicate-current-next69-unit',
                    'unit' => $unit,
                    'evidence' => 'current-next69 denominator rows must have unique unit IDs before countability movement is published',
                ];
            }
            $units[$unit] = true;

            $rowBlockers = [];
            $sourceHead = is_string($row['source_head'] ?? null) ? $row['source_head'] : '';
            if ($sourceHead !== $acceptedRepositoryHead) {
                $rowBlockers[] = 'source-head-mismatch';
            } else {
                $freshRows++;
            }

            $command = is_string($row['runner_command'] ?? null) ? trim($row['runner_command']) : '';
            if ($command === '' || !str_contains($command, 'testfixture') || !str_contains($command, 'testrunner.tcl')) {
                $rowBlockers[] = 'runner-command-missing';
            } else {
                $commandRows++;
            }

            $artifactStatus = is_string($row['artifact_status'] ?? null) ? $row['artifact_status'] : '';
            if (!in_array($artifactStatus, ['focused-pass', 'current-head-admitted', 'preserved-current-head'], true)) {
                $rowBlockers[] = 'artifact-status-not-countable';
            } else {
                $artifactRows++;
            }

            if (($row['counts_release_parity'] ?? false) === true) {
                $rowBlockers[] = 'release-parity-claim-not-allowed';
            }

            if ($rowBlockers !== []) {
                $blockedRows[] = $unit;
                $freshnessBlockers[] = [
                    'id' => 'current-next69-row-freshness-blocked',
                    'unit' => $unit,
                    'evidence' => implode('; ', array_values(array_unique($rowBlockers))),
                ];
            }
        }

        $blockedRows = array_values(array_unique($blockedRows));
        sort($blockedRows, SORT_STRING);

        $baseBlockers = is_array($record['blockers'] ?? null) ? $record['blockers'] : [];
        $blockers = array_merge($baseBlockers, $freshnessBlockers);
        $blocked = $blockers !== [];
        $baseStatus = is_string($record['status'] ?? null) ? $record['status'] : 'blocked';
        $status = 'blocked';
        if (!$blocked && $baseStatus === 'suite-denominator-countable') {
            $status = 'current-next69-denominator-current-source-countable';
        } elseif (!$blocked && $baseStatus === 'suite-denominator-preserved') {
            $status = 'current-next69-denominator-current-source-preserved';
        }

        $record['status'] = $status;
        $record['countable'] = $status === 'current-next69-denominator-current-source-countable';
        $record['current_next69_fresh_row_count'] = $freshRows;
        $record['current_next69_command_row_count'] = $commandRows;
        $record['current_next69_artifact_row_count'] = $artifactRows;
        $record['current_next69_blocked_units'] = $blockedRows;
        $record['current_next69_blocker_count'] = count($freshnessBlockers);
        $record['blocker_count'] = count($blockers);
        $record['blockers'] = $blockers;
        $record['mapped_delta'] = $blocked ? 0 : (int) ($record['mapped_delta'] ?? 0);
        $record['next_mapped'] = $blocked ? $currentMapped : (int) ($record['next_mapped'] ?? $currentMapped);
        $record['countable_script_delta'] = $blocked ? 0 : (int) ($record['countable_script_delta'] ?? 0);
        $record['php_pass_delta'] = $blocked ? 0 : (int) ($record['php_pass_delta'] ?? 0);
        $record['next_php_pass'] = $blocked ? $currentPhpPass : (int) ($record['next_php_pass'] ?? $currentPhpPass);
        $record['counts_release_parity'] = false;
        $record['next_gate'] = $status === 'current-next69-denominator-current-source-countable'
            ? 'publish current-next69 focused PASS-line movement only after source-head, runner-command, artifact-status, and duplicate-unit gates stay clean; release/all parity remains unclaimed'
            : 'keep current-next69 denominator movement uncounted until current-source freshness, runner-command, artifact-status, duplicate-unit, active-runner, and focused PASS-line blockers are clear';
        $record['dependency_closure'] = 'no new support component needed; current-next69 denominator freshness reuses lane-local rows, accepted-source heads, guarded runner command strings, artifact status tags, duplicate-runner gates, and focused TestRunner PASS-line output only';

        return $record;
    }

    /**
     * @param array<int|string, array<string, mixed>> $runnerRows
     * @return array<string, mixed>
     */
    public function suiteDenominatorRunnerAdmission(
        array $runnerRows,
        int $currentMapped,
        int $currentPhpPass,
        string $acceptedRepositoryHead,
        string $evidenceRepositoryHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        if ($runnerRows === []) {
            throw new \InvalidArgumentException('SQLite current-next73 runner denominator admission requires at least one runner row');
        }
        if ($currentMapped < 0) {
            throw new \InvalidArgumentException('SQLite current-next73 runner denominator admission needs a non-negative current mapped count');
        }

        $phpAdmission = $this->focusedPhpPassCurrentHeadAdmission(
            $currentPhpPass,
            $acceptedRepositoryHead,
            $evidenceRepositoryHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta
        );
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $entries = [];
        $blockers = [];
        $seenRunIds = [];
        $advanced = [];
        $preserved = [];
        $blocked = [];
        $regressed = [];
        $scripts = [];
        $categories = [];
        $currentRunnerCount = 0;
        $nextRunnerCount = 0;
        $currentTests = 0;
        $nextTests = 0;
        $parsedAuditRows = 0;
        $parsedLogRows = 0;

        foreach ($runnerRows as $label => $row) {
            $fallbackUnit = is_string($label) ? $label : 'current-next73-runner-' . count($entries);
            if (!is_array($row)) {
                $blocked[] = $fallbackUnit;
                $blockers[] = [
                    'id' => 'runner-row-invalid',
                    'unit' => $fallbackUnit,
                    'evidence' => 'runner row must be an array',
                ];
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== '' ? $row['unit'] : $fallbackUnit;
            $category = is_string($row['category'] ?? null) && $row['category'] !== '' ? $row['category'] : 'focused-runner-artifact-pair';
            $runId = is_string($row['run_id'] ?? null) ? trim($row['run_id']) : '';
            $sourceHead = is_string($row['source_head'] ?? null) ? trim($row['source_head']) : '';
            $auditPath = is_string($row['audit_path'] ?? null) ? trim($row['audit_path']) : '';
            $logPath = is_string($row['log_path'] ?? null) ? trim($row['log_path']) : '';
            $command = is_string($row['runner_command'] ?? null) ? trim($row['runner_command']) : '';
            $artifactStatus = is_string($row['artifact_status'] ?? null) ? trim($row['artifact_status']) : '';
            $currentCountable = (bool) ($row['current_countable'] ?? false);
            $nextCountable = (bool) ($row['next_countable'] ?? false);
            $currentRowTests = max(0, $this->denominatorAuditInt($row, 'current_tests'));
            $nextRowTests = max(0, $this->denominatorAuditInt($row, 'next_tests'));
            $auditTests = max(0, $this->denominatorAuditInt($row, 'audit_tests'));
            $logTests = max(0, $this->denominatorAuditInt($row, 'log_tests'));
            $auditErrors = max(0, $this->denominatorAuditInt($row, 'audit_errors'));
            $logErrors = max(0, $this->denominatorAuditInt($row, 'log_errors'));
            $rowScripts = array_values(array_unique(array_filter(
                is_array($row['scripts'] ?? null) ? $row['scripts'] : [],
                static fn (mixed $script): bool => is_string($script) && str_ends_with($script, '.test')
            )));
            sort($rowScripts, SORT_STRING);
            foreach ($rowScripts as $script) {
                $scripts[$script] = true;
            }

            $rowBlockers = [];
            if ($runId === '') {
                $rowBlockers[] = 'missing-run-id';
            } elseif (isset($seenRunIds[$runId])) {
                $rowBlockers[] = 'duplicate-run-id';
            }
            if ($runId !== '') {
                $seenRunIds[$runId] = true;
            }
            if ($sourceHead !== $acceptedRepositoryHead) {
                $rowBlockers[] = 'source-head-mismatch';
            }
            if (!preg_match('#^lanes/libsqlite/(notes|fixtures)/[A-Za-z0-9_.-]+\.md$#', $auditPath)) {
                $rowBlockers[] = 'audit-path-not-lane-local';
            } else {
                $parsedAuditRows++;
            }
            if (!preg_match('#^lanes/libsqlite/(notes|fixtures)/[A-Za-z0-9_.-]+\.log$#', $logPath)) {
                $rowBlockers[] = 'log-path-not-lane-local';
            } else {
                $parsedLogRows++;
            }
            if ($command === '' || !str_contains($command, 'testfixture') || !str_contains($command, 'testrunner.tcl')) {
                $rowBlockers[] = 'runner-command-missing';
            }
            if (!in_array($artifactStatus, ['focused-pass', 'preserved-current-head'], true)) {
                $rowBlockers[] = 'artifact-status-not-countable';
            }
            if ($nextCountable && $rowScripts === []) {
                $rowBlockers[] = 'countable-runner-missing-test-scripts';
            }
            if ($nextCountable && ($auditTests <= 0 || $logTests <= 0)) {
                $rowBlockers[] = 'missing-parsed-runner-counts';
            }
            if ($nextCountable && $auditTests !== $logTests) {
                $rowBlockers[] = 'audit-log-test-count-mismatch';
            }
            if ($auditErrors !== 0 || $logErrors !== 0) {
                $rowBlockers[] = 'runner-artifact-has-errors';
            }
            if ($currentCountable && !$nextCountable) {
                $rowBlockers[] = 'runner-countability-regressed';
            }
            if ($nextRowTests < $currentRowTests) {
                $rowBlockers[] = 'runner-test-count-regressed';
            }
            if (($row['counts_release_parity'] ?? false) === true) {
                $rowBlockers[] = 'release-parity-claim-not-allowed';
            }
            foreach (is_array($row['blockers'] ?? null) ? $row['blockers'] : [] as $rowBlocker) {
                if (is_string($rowBlocker) && $rowBlocker !== '') {
                    $rowBlockers[] = $rowBlocker;
                }
            }
            $rowBlockers = array_values(array_unique($rowBlockers));

            $movement = 'open';
            if ($rowBlockers !== []) {
                $movement = 'blocked';
                $blocked[] = $unit;
                if (
                    in_array('runner-countability-regressed', $rowBlockers, true)
                    || in_array('runner-test-count-regressed', $rowBlockers, true)
                    || in_array('audit-log-test-count-mismatch', $rowBlockers, true)
                ) {
                    $regressed[] = $unit;
                }
                $blockers[] = [
                    'id' => 'runner-row-blocked',
                    'unit' => $unit,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($nextCountable && !$currentCountable) {
                $movement = 'advanced';
                $advanced[] = $unit;
            } elseif ($nextCountable) {
                $movement = 'preserved';
                $preserved[] = $unit;
            }

            if ($currentCountable) {
                $currentRunnerCount++;
                $currentTests += $currentRowTests;
            }
            if ($nextCountable) {
                $nextRunnerCount++;
                $nextTests += $nextRowTests;
            }
            $categories[$category] = ($categories[$category] ?? 0) + 1;

            $entries[] = [
                'unit' => $unit,
                'category' => $category,
                'movement' => $movement,
                'run_id' => $runId,
                'source_head' => $sourceHead,
                'audit_path' => $auditPath,
                'log_path' => $logPath,
                'current_countable' => $currentCountable,
                'next_countable' => $nextCountable,
                'current_tests' => $currentRowTests,
                'next_tests' => $nextRowTests,
                'audit_tests' => $auditTests,
                'log_tests' => $logTests,
                'scripts' => $rowScripts,
                'blocker_ids' => $rowBlockers,
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'current-head-focused-pass-countable') {
            $blockers[] = [
                'id' => 'focused-current-head-php-pass-blocked',
                'evidence' => 'focused PHP PASS-line admission did not satisfy current-head gates',
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
            ];
        }

        ksort($categories, SORT_STRING);
        sort($advanced, SORT_STRING);
        sort($preserved, SORT_STRING);
        sort($blocked, SORT_STRING);
        sort($regressed, SORT_STRING);
        $scriptList = array_keys($scripts);
        sort($scriptList, SORT_STRING);

        $runnerDelta = max(0, $nextRunnerCount - $currentRunnerCount);
        $status = 'blocked';
        if ($blockers === [] && $runnerDelta > 0) {
            $status = 'current-next73-runner-artifact-pair-countable';
        } elseif ($blockers === []) {
            $status = 'current-next73-runner-artifact-pair-preserved';
        }

        return [
            'status' => $status,
            'countable' => $status === 'current-next73-runner-artifact-pair-countable',
            'accepted_repository_head' => $acceptedRepositoryHead,
            'evidence_repository_head' => $evidenceRepositoryHead,
            'current_mapped' => $currentMapped,
            'next_mapped' => $currentMapped,
            'mapped_delta' => 0,
            'current_php_pass' => $currentPhpPass,
            'php_pass_delta' => $blockers === [] ? (int) ($phpAdmission['pass_delta'] ?? 0) : 0,
            'next_php_pass' => $blockers === [] ? (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass) : $currentPhpPass,
            'row_count' => count($entries),
            'category_count' => count($categories),
            'categories' => $categories,
            'current_runner_countable_count' => $currentRunnerCount,
            'next_runner_countable_count' => $blockers === [] ? $nextRunnerCount : $currentRunnerCount,
            'runner_countable_delta' => $blockers === [] ? $runnerDelta : 0,
            'current_tests_total' => $currentTests,
            'next_tests_total' => $blockers === [] ? $nextTests : $currentTests,
            'tests_total_delta' => $blockers === [] ? max(0, $nextTests - $currentTests) : 0,
            'parsed_audit_row_count' => $parsedAuditRows,
            'parsed_log_row_count' => $parsedLogRows,
            'target_script_count' => count($scriptList),
            'target_scripts' => $scriptList,
            'advanced_units' => $advanced,
            'preserved_units' => $preserved,
            'blocked_units' => $blocked,
            'regressed_units' => $regressed,
            'entries' => $entries,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'php_pass_admission' => $phpAdmission,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_release_parity' => false,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => $status === 'current-next73-runner-artifact-pair-countable'
                ? 'publish current-next73 runner artifact-pair countability only for lane-local audit/log pairs whose accepted source head, command, parsed zero-error counts, and focused PASS-line evidence agree; release/all parity remains unclaimed'
                : 'keep current-next73 runner denominator movement uncounted until audit/log pair provenance, parsed counts, duplicate-runner, and focused PASS-line blockers are clear',
            'dependency_closure' => 'no new support component needed; current-next73 runner denominator admission composes lane-local audit/log pair metadata, accepted-source heads, guarded runner command strings, duplicate-runner gates, and focused TestRunner PASS-line output only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function suiteReleaseRunnerAdmission(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $currentAcceptedHead,
        string $nextAcceptedHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        if ($artifactRows === []) {
            throw new \InvalidArgumentException('SQLite current-next72 release-runner admission requires at least one artifact row');
        }
        if ($currentMapped < 0) {
            throw new \InvalidArgumentException('SQLite current-next72 release-runner admission requires a non-negative current mapped count');
        }
        if (trim($currentAcceptedHead) === '' || trim($nextAcceptedHead) === '') {
            throw new \InvalidArgumentException('SQLite current-next72 release-runner admission requires current and next accepted HEAD values');
        }

        $phpAdmission = $this->focusedPhpPassCurrentHeadAdmission(
            $currentPhpPass,
            $currentAcceptedHead,
            $currentAcceptedHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta
        );
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $entries = [];
        $blockers = [];
        $seen = [];
        $admittedUnits = [];
        $preservedUnits = [];
        $blockedUnits = [];
        $regressedUnits = [];
        $categories = [];
        $scripts = [];
        $currentTestsTotal = 0;
        $nextTestsTotal = 0;
        $zeroErrorArtifacts = 0;

        foreach ($artifactRows as $label => $row) {
            $fallbackUnit = is_string($label) ? $label : 'current-next72-artifact-' . count($entries);
            if (!is_array($row)) {
                $blockedUnits[] = $fallbackUnit;
                $blockers[] = [
                    'id' => 'current-next72-artifact-row-invalid',
                    'unit' => $fallbackUnit,
                    'evidence' => 'release-runner artifact row must be an array',
                ];
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== '' ? $row['unit'] : $fallbackUnit;
            $category = is_string($row['category'] ?? null) && $row['category'] !== '' ? $row['category'] : 'release-runner-admission';
            $currentHead = is_string($row['current_head'] ?? null) ? trim($row['current_head']) : '';
            $nextHead = is_string($row['next_head'] ?? null) ? trim($row['next_head']) : '';
            $artifactPath = is_string($row['artifact_path'] ?? null) ? trim($row['artifact_path']) : '';
            $command = is_string($row['runner_command'] ?? null) ? trim($row['runner_command']) : '';
            $evidence = is_string($row['evidence'] ?? null) ? trim($row['evidence']) : '';
            $currentStatus = is_string($row['current_status'] ?? null) ? $row['current_status'] : 'missing';
            $nextStatus = is_string($row['next_status'] ?? null) ? $row['next_status'] : 'missing';
            $currentCountable = (bool) ($row['current_countable'] ?? in_array($currentStatus, ['countable', 'admitted', 'mapped'], true));
            $nextCountable = (bool) ($row['next_countable'] ?? in_array($nextStatus, ['countable', 'admitted', 'mapped'], true));
            $errors = max(0, $this->denominatorAuditInt($row, 'errors'));
            $tests = max(0, $this->denominatorAuditInt($row, 'tests'));
            $currentTests = max(0, $this->denominatorAuditInt($row, 'current_tests'));
            $nextTests = max(0, $this->denominatorAuditInt($row, 'next_tests'));
            $rowScripts = array_values(array_unique(array_filter(
                is_array($row['scripts'] ?? null) ? $row['scripts'] : [],
                static fn (mixed $script): bool => is_string($script) && str_ends_with($script, '.test')
            )));
            sort($rowScripts, SORT_STRING);
            foreach ($rowScripts as $script) {
                $scripts[$script] = true;
            }

            $rowBlockers = [];
            if (isset($seen[$unit])) {
                $rowBlockers[] = 'duplicate-release-runner-unit';
            }
            $seen[$unit] = true;
            if ($currentHead !== $currentAcceptedHead) {
                $rowBlockers[] = 'current-head-mismatch';
            }
            if ($nextHead !== $nextAcceptedHead) {
                $rowBlockers[] = 'next-head-mismatch';
            }
            if ($artifactPath === '' || !str_starts_with($artifactPath, 'lanes/libsqlite/')) {
                $rowBlockers[] = 'artifact-path-not-lane-local';
            }
            if ($command === '' || !str_contains($command, 'testfixture') || !str_contains($command, 'testrunner.tcl')) {
                $rowBlockers[] = 'runner-command-missing';
            }
            if ($nextCountable && $rowScripts === []) {
                $rowBlockers[] = 'countable-artifact-missing-test-scripts';
            }
            if ($nextCountable && $evidence === '') {
                $rowBlockers[] = 'countable-artifact-missing-evidence';
            }
            if ($nextCountable && $errors !== 0) {
                $rowBlockers[] = 'artifact-errors-not-zero';
            }
            if ($nextCountable && $tests < 1) {
                $rowBlockers[] = 'artifact-tests-missing';
            }
            if ($currentCountable && !$nextCountable) {
                $rowBlockers[] = 'countable-artifact-regressed';
            }
            if ($nextTests < $currentTests) {
                $rowBlockers[] = 'artifact-test-count-regressed';
            }
            if (($row['counts_release_parity'] ?? false) === true) {
                $rowBlockers[] = 'release-parity-claim-not-allowed';
            }
            foreach (is_array($row['blockers'] ?? null) ? $row['blockers'] : [] as $blocker) {
                if (is_string($blocker) && $blocker !== '') {
                    $rowBlockers[] = $blocker;
                }
            }
            $rowBlockers = array_values(array_unique($rowBlockers));

            $movement = 'open';
            if ($rowBlockers !== []) {
                $movement = 'blocked';
                $blockedUnits[] = $unit;
                if (in_array('countable-artifact-regressed', $rowBlockers, true) || in_array('artifact-test-count-regressed', $rowBlockers, true)) {
                    $regressedUnits[] = $unit;
                }
                $blockers[] = [
                    'id' => 'current-next72-artifact-blocked',
                    'unit' => $unit,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($nextCountable && !$currentCountable) {
                $movement = 'admitted';
                $admittedUnits[] = $unit;
                $zeroErrorArtifacts++;
            } elseif ($nextCountable) {
                $movement = 'preserved';
                $preservedUnits[] = $unit;
                $zeroErrorArtifacts++;
            }

            if ($currentCountable) {
                $currentTestsTotal += $currentTests;
            }
            if ($nextCountable) {
                $nextTestsTotal += $nextTests > 0 ? $nextTests : $tests;
            }
            $categories[$category] = ($categories[$category] ?? 0) + 1;

            $entries[] = [
                'unit' => $unit,
                'category' => $category,
                'movement' => $movement,
                'current_head' => $currentHead,
                'next_head' => $nextHead,
                'current_countable' => $currentCountable,
                'next_countable' => $nextCountable,
                'tests' => $tests,
                'errors' => $errors,
                'current_tests' => $currentTests,
                'next_tests' => $nextTests,
                'scripts' => $rowScripts,
                'artifact_path' => $artifactPath,
                'blocker_ids' => $rowBlockers,
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'current-head-focused-pass-countable') {
            $blockers[] = [
                'id' => 'focused-current-head-php-pass-blocked',
                'evidence' => 'focused PHP PASS-line admission did not satisfy current-head gates',
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
            ];
        }

        ksort($categories, SORT_STRING);
        sort($admittedUnits, SORT_STRING);
        sort($preservedUnits, SORT_STRING);
        sort($blockedUnits, SORT_STRING);
        sort($regressedUnits, SORT_STRING);
        $scriptList = array_keys($scripts);
        sort($scriptList, SORT_STRING);

        $mappedDelta = count($admittedUnits);
        $blocked = $blockers !== [];
        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-next72-release-runner-admitted';
        } elseif (!$blocked) {
            $status = 'current-next72-release-runner-preserved';
        }

        return [
            'status' => $status,
            'countable' => $status === 'current-next72-release-runner-admitted',
            'current_accepted_head' => $currentAcceptedHead,
            'next_accepted_head' => $nextAcceptedHead,
            'current_mapped' => $currentMapped,
            'next_mapped' => $blocked ? $currentMapped : $currentMapped + $mappedDelta,
            'mapped_delta' => $blocked ? 0 : $mappedDelta,
            'current_php_pass' => $currentPhpPass,
            'php_pass_delta' => $blocked ? 0 : (int) ($phpAdmission['pass_delta'] ?? 0),
            'next_php_pass' => $blocked ? $currentPhpPass : (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass),
            'row_count' => count($entries),
            'category_count' => count($categories),
            'categories' => $categories,
            'zero_error_artifact_count' => $blocked ? 0 : $zeroErrorArtifacts,
            'admitted_units' => $admittedUnits,
            'preserved_units' => $preservedUnits,
            'blocked_units' => $blockedUnits,
            'regressed_units' => $regressedUnits,
            'current_tests_total' => $currentTestsTotal,
            'next_tests_total' => $nextTestsTotal,
            'tests_total_delta' => $blocked ? 0 : max(0, $nextTestsTotal - $currentTestsTotal),
            'target_script_count' => count($scriptList),
            'target_scripts' => $scriptList,
            'entries' => $entries,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'php_pass_admission' => $phpAdmission,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_release_runner_admission_current_next72' => $status === 'current-next72-release-runner-admitted',
            'counts_release_parity' => false,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => $status === 'current-next72-release-runner-admitted'
                ? 'publish only current-next72 release-runner artifact admission and exact focused PASS-line movement; release/all parity remains gated on a separate broad zero-error artifact'
                : 'keep current-next72 admission uncounted until current/next heads, lane-local artifacts, zero-error runner output, duplicate-runner, and focused PASS-line gates are clear',
            'dependency_closure' => 'no new support component needed; current-next72 release-runner admission composes lane-local artifact rows, guarded runner commands, zero-error result metadata, active-runner gates, and focused TestRunner PASS-line output only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function suiteReleaseRunnerUpstreamAdmission(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $acceptedRepositoryHead,
        string $expectedSqliteCommit,
        string $expectedManifestUuid,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        if ($artifactRows === []) {
            throw new \InvalidArgumentException('SQLite current-next81 upstream runner admission requires at least one artifact row');
        }
        if ($currentMapped < 0) {
            throw new \InvalidArgumentException('SQLite current-next81 upstream runner admission requires a non-negative mapped count');
        }
        if (trim($acceptedRepositoryHead) === '' || trim($expectedSqliteCommit) === '' || trim($expectedManifestUuid) === '') {
            throw new \InvalidArgumentException('SQLite current-next81 upstream runner admission requires accepted HEAD, SQLite commit, and manifest UUID values');
        }

        $phpAdmission = $this->focusedPhpPassCurrentHeadAdmission(
            $currentPhpPass,
            $acceptedRepositoryHead,
            $acceptedRepositoryHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta
        );
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $entries = [];
        $blockers = [];
        $seen = [];
        $advanced = [];
        $preserved = [];
        $blocked = [];
        $regressed = [];
        $tiers = [];
        $scripts = [];
        $currentTestsTotal = 0;
        $nextTestsTotal = 0;

        foreach ($artifactRows as $label => $row) {
            $fallbackUnit = is_string($label) ? $label : 'current-next81-upstream-artifact-' . count($entries);
            if (!is_array($row)) {
                $blocked[] = $fallbackUnit;
                $blockers[] = [
                    'id' => 'current-next81-artifact-row-invalid',
                    'unit' => $fallbackUnit,
                    'evidence' => 'upstream runner artifact row must be an array',
                ];
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== '' ? $row['unit'] : $fallbackUnit;
            $tier = is_string($row['tier'] ?? null) && $row['tier'] !== '' ? strtolower($row['tier']) : 'unknown';
            $head = is_string($row['repository_head'] ?? null) ? trim($row['repository_head']) : '';
            $sqliteCommit = is_string($row['sqlite_commit'] ?? null) ? trim($row['sqlite_commit']) : '';
            $manifestUuid = is_string($row['manifest_uuid'] ?? null) ? trim($row['manifest_uuid']) : '';
            $artifactPath = is_string($row['artifact_path'] ?? null) ? trim($row['artifact_path']) : '';
            $command = is_string($row['runner_command'] ?? null) ? trim($row['runner_command']) : '';
            $evidence = is_string($row['evidence'] ?? null) ? trim($row['evidence']) : '';
            $currentCountable = (bool) ($row['current_countable'] ?? false);
            $nextCountable = (bool) ($row['next_countable'] ?? false);
            $exit = $this->denominatorAuditInt($row, 'exit');
            $errors = max(0, $this->denominatorAuditInt($row, 'errors'));
            $currentTests = max(0, $this->denominatorAuditInt($row, 'current_tests'));
            $nextTests = max(0, $this->denominatorAuditInt($row, 'next_tests'));
            $rowScripts = array_values(array_unique(array_filter(
                is_array($row['scripts'] ?? null) ? $row['scripts'] : [],
                static fn (mixed $script): bool => is_string($script) && (str_ends_with($script, '.test') || str_contains($script, '*.test'))
            )));
            sort($rowScripts, SORT_STRING);
            foreach ($rowScripts as $script) {
                $scripts[$script] = true;
            }

            $rowBlockers = [];
            if (isset($seen[$unit])) {
                $rowBlockers[] = 'duplicate-upstream-runner-unit';
            }
            $seen[$unit] = true;
            if (!in_array($tier, ['release', 'all'], true)) {
                $rowBlockers[] = 'unsupported-upstream-runner-tier';
            }
            if ($head !== $acceptedRepositoryHead) {
                $rowBlockers[] = 'accepted-head-mismatch';
            }
            if ($sqliteCommit !== $expectedSqliteCommit) {
                $rowBlockers[] = 'sqlite-commit-mismatch';
            }
            if ($manifestUuid !== $expectedManifestUuid) {
                $rowBlockers[] = 'sqlite-manifest-uuid-mismatch';
            }
            if ($artifactPath === '' || !str_starts_with($artifactPath, 'lanes/libsqlite/')) {
                $rowBlockers[] = 'artifact-path-not-lane-local';
            }
            if ($command === '' || !str_contains($command, 'testfixture') || !str_contains($command, 'testrunner.tcl') || !preg_match('/(?:^|\s)(all|release)(?:\s|$)/', $command)) {
                $rowBlockers[] = 'upstream-runner-command-missing';
            }
            if ($nextCountable && $exit !== 0) {
                $rowBlockers[] = 'runner-exit-not-zero';
            }
            if ($nextCountable && $errors !== 0) {
                $rowBlockers[] = 'runner-errors-not-zero';
            }
            if ($nextCountable && $nextTests < 1) {
                $rowBlockers[] = 'runner-test-count-missing';
            }
            if ($nextCountable && $rowScripts === []) {
                $rowBlockers[] = 'upstream-runner-scripts-missing';
            }
            if ($nextCountable && $evidence === '') {
                $rowBlockers[] = 'upstream-runner-evidence-missing';
            }
            if ($currentCountable && !$nextCountable) {
                $rowBlockers[] = 'upstream-runner-countability-regressed';
            }
            if ($nextTests < $currentTests) {
                $rowBlockers[] = 'upstream-runner-test-count-regressed';
            }
            if (($row['counts_release_parity'] ?? false) === true) {
                $rowBlockers[] = 'release-parity-claim-not-allowed';
            }
            foreach (is_array($row['blockers'] ?? null) ? $row['blockers'] : [] as $blocker) {
                if (is_string($blocker) && $blocker !== '') {
                    $rowBlockers[] = $blocker;
                }
            }
            $rowBlockers = array_values(array_unique($rowBlockers));

            $movement = 'open';
            if ($rowBlockers !== []) {
                $movement = 'blocked';
                $blocked[] = $unit;
                if (in_array('upstream-runner-countability-regressed', $rowBlockers, true) || in_array('upstream-runner-test-count-regressed', $rowBlockers, true)) {
                    $regressed[] = $unit;
                }
                $blockers[] = [
                    'id' => 'current-next81-artifact-blocked',
                    'unit' => $unit,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($nextCountable && !$currentCountable) {
                $movement = 'advanced';
                $advanced[] = $unit;
            } elseif ($nextCountable) {
                $movement = 'preserved';
                $preserved[] = $unit;
            }

            if ($currentCountable) {
                $currentTestsTotal += $currentTests;
            }
            if ($nextCountable) {
                $nextTestsTotal += $nextTests;
            }
            $tiers[$tier] = ($tiers[$tier] ?? 0) + 1;

            $entries[] = [
                'unit' => $unit,
                'tier' => $tier,
                'movement' => $movement,
                'repository_head' => $head,
                'sqlite_commit' => $sqliteCommit,
                'manifest_uuid' => $manifestUuid,
                'current_countable' => $currentCountable,
                'next_countable' => $nextCountable,
                'exit' => $exit,
                'errors' => $errors,
                'current_tests' => $currentTests,
                'next_tests' => $nextTests,
                'scripts' => $rowScripts,
                'artifact_path' => $artifactPath,
                'blocker_ids' => $rowBlockers,
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'current-head-focused-pass-countable') {
