            if ($currentCountable) {
                $currentTestsTotal += $currentTests;
            }
            if ($nextCountable) {
                $nextTestsTotal += $nextTests;
            }
            $tiers[$tier] = ($tiers[$tier] ?? 0) + 1;

            $entries[] = [
                'unit' => $unit,
                'tier' => $tier,
                'movement' => $movement,
                'repository_head' => $head,
                'current_countable' => $currentCountable,
                'next_countable' => $nextCountable,
                'exit' => $exit,
                'errors' => $errors,
                'current_tests' => $currentTests,
                'next_tests' => $nextTests,
                'scripts' => $rowScripts,
                'artifact_path' => $artifactPath,
                'blocker_ids' => $rowBlockers,
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'current-head-focused-pass-countable') {
            $blockers[] = [
                'id' => 'focused-current-head-php-pass-blocked',
                'evidence' => 'focused PHP PASS-line admission did not satisfy current-head gates',
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
            ];
        }

        ksort($tiers, SORT_STRING);
        sort($countedUnits, SORT_STRING);
        sort($preservedUnits, SORT_STRING);
        sort($blockedUnits, SORT_STRING);
        sort($regressedUnits, SORT_STRING);
        $scriptList = array_keys($scripts);
        sort($scriptList, SORT_STRING);

        $blocked = $blockers !== [];
        $mappedDelta = count($countedUnits) > 0 ? 1 : 0;
        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-next75-release-all-countable';
        } elseif (!$blocked) {
            $status = 'current-next75-release-all-preserved';
        }

        return [
            'status' => $status,
            'countable' => $status === 'current-next75-release-all-countable',
            'accepted_repository_head' => $acceptedRepositoryHead,
            'current_mapped' => $currentMapped,
            'next_mapped' => $blocked ? $currentMapped : $currentMapped + $mappedDelta,
            'mapped_delta' => $blocked ? 0 : $mappedDelta,
            'current_php_pass' => $currentPhpPass,
            'php_pass_delta' => $blocked ? 0 : (int) ($phpAdmission['pass_delta'] ?? 0),
            'next_php_pass' => $blocked ? $currentPhpPass : (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass),
            'row_count' => count($entries),
            'tier_count' => count($tiers),
            'tiers' => $tiers,
            'counted_units' => $countedUnits,
            'preserved_units' => $preservedUnits,
            'blocked_units' => $blockedUnits,
            'regressed_units' => $regressedUnits,
            'current_tests_total' => $currentTestsTotal,
            'next_tests_total' => $nextTestsTotal,
            'tests_total_delta' => $blocked ? 0 : max(0, $nextTestsTotal - $currentTestsTotal),
            'target_script_count' => count($scriptList),
            'target_scripts' => $scriptList,
            'entries' => $entries,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'php_pass_admission' => $phpAdmission,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_release_all_runner_countability_current_next75' => $status === 'current-next75-release-all-countable',
            'counts_release_parity' => false,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => $status === 'current-next75-release-all-countable'
                ? 'publish current-next75 release/all runner countability as one mapped blocker removal; full release/all parity still requires a separately accepted broad zero-error closure record'
                : 'keep current-next75 release/all countability uncounted until accepted-head, lane-local artifact, zero-error runner, duplicate-runner, and focused PASS-line gates are clear',
            'dependency_closure' => 'no new support component needed; current-next75 release/all countability composes lane-local artifact metadata, guarded runner commands, active-runner gates, and focused TestRunner PASS-line output only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $evidenceRows
     * @return array<string, mixed>
     */
    public function suiteEvidenceSlice(
        array $evidenceRows,
        int $currentMapped,
        int $currentPhpPass,
        string $acceptedRepositoryHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        if ($evidenceRows === []) {
            throw new \InvalidArgumentException('SQLite suite evidence slice requires at least one evidence row');
        }
        if ($currentMapped < 0) {
            throw new \InvalidArgumentException('SQLite suite evidence slice requires a non-negative mapped count');
        }
        if (trim($acceptedRepositoryHead) === '') {
            throw new \InvalidArgumentException('SQLite suite evidence slice requires an accepted repository HEAD');
        }
        if (trim($nonOverlapNote) === '') {
            throw new \InvalidArgumentException('SQLite suite evidence slice requires a non-overlap note');
        }

        $phpAdmission = $this->focusedPhpPassCurrentHeadAdmission(
            $currentPhpPass,
            $acceptedRepositoryHead,
            $acceptedRepositoryHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta
        );
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $entries = [];
        $blockers = [];
        $seen = [];
        $advanced = [];
        $preserved = [];
        $blockedUnits = [];
        $regressed = [];
        $tiers = [];
        $scripts = [];
        $currentTestsTotal = 0;
        $nextTestsTotal = 0;

        foreach ($evidenceRows as $label => $row) {
            $fallbackUnit = is_string($label) ? $label : 'suite-evidence-' . count($entries);
            if (!is_array($row)) {
                $blockedUnits[] = $fallbackUnit;
                $blockers[] = [
                    'id' => 'suite-evidence-row-invalid',
                    'unit' => $fallbackUnit,
                    'evidence' => 'suite evidence row must be an array',
                ];
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== '' ? $row['unit'] : $fallbackUnit;
            $tier = is_string($row['tier'] ?? null) && $row['tier'] !== '' ? strtolower($row['tier']) : 'unknown';
            $head = is_string($row['repository_head'] ?? null) ? trim($row['repository_head']) : '';
            $artifactPath = is_string($row['artifact_path'] ?? null) ? trim($row['artifact_path']) : '';
            $command = is_string($row['runner_command'] ?? null) ? trim($row['runner_command']) : '';
            $evidence = is_string($row['evidence'] ?? null) ? trim($row['evidence']) : '';
            $currentCountable = (bool) ($row['current_countable'] ?? false);
            $nextCountable = (bool) ($row['next_countable'] ?? false);
            $exit = $this->denominatorAuditInt($row, 'exit');
            $errors = max(0, $this->denominatorAuditInt($row, 'errors'));
            $currentTests = max(0, $this->denominatorAuditInt($row, 'current_tests'));
            $nextTests = max(0, $this->denominatorAuditInt($row, 'next_tests'));
            $rowScripts = array_values(array_unique(array_filter(
                is_array($row['scripts'] ?? null) ? $row['scripts'] : [],
                static fn (mixed $script): bool => is_string($script) && (str_ends_with($script, '.test') || str_contains($script, '*.test'))
            )));
            sort($rowScripts, SORT_STRING);
            foreach ($rowScripts as $script) {
                $scripts[$script] = true;
            }

            $rowBlockers = [];
            if (isset($seen[$unit])) {
                $rowBlockers[] = 'duplicate-suite-evidence-unit';
            }
            $seen[$unit] = true;
            if (!in_array($tier, ['veryquick', 'release', 'all', 'focused'], true)) {
                $rowBlockers[] = 'unsupported-suite-evidence-tier';
            }
            if ($head !== $acceptedRepositoryHead) {
                $rowBlockers[] = 'accepted-head-mismatch';
            }
            if ($artifactPath === '' || !str_starts_with($artifactPath, 'lanes/libsqlite/')) {
                $rowBlockers[] = 'artifact-path-not-lane-local';
            }
            if ($command === '' || !str_contains($command, 'testfixture') || !str_contains($command, 'testrunner.tcl')) {
                $rowBlockers[] = 'suite-runner-command-missing';
            }
            if ($nextCountable && $exit !== 0) {
                $rowBlockers[] = 'runner-exit-not-zero';
            }
            if ($nextCountable && $errors !== 0) {
                $rowBlockers[] = 'runner-errors-not-zero';
            }
            if ($nextCountable && $nextTests < 1) {
                $rowBlockers[] = 'runner-test-count-missing';
            }
            if ($nextCountable && $rowScripts === []) {
                $rowBlockers[] = 'suite-scripts-missing';
            }
            if ($nextCountable && $evidence === '') {
                $rowBlockers[] = 'suite-evidence-missing';
            }
            if ($currentCountable && !$nextCountable) {
                $rowBlockers[] = 'suite-evidence-countability-regressed';
            }
            if ($nextTests < $currentTests) {
                $rowBlockers[] = 'suite-evidence-test-count-regressed';
            }
            if (($row['counts_release_parity'] ?? false) === true) {
                $rowBlockers[] = 'release-parity-claim-not-allowed';
            }
            foreach (is_array($row['blockers'] ?? null) ? $row['blockers'] : [] as $blocker) {
                if (is_string($blocker) && $blocker !== '') {
                    $rowBlockers[] = $blocker;
                }
            }
            $rowBlockers = array_values(array_unique($rowBlockers));

            $movement = 'open';
            if ($rowBlockers !== []) {
                $movement = 'blocked';
                $blockedUnits[] = $unit;
                if (in_array('suite-evidence-countability-regressed', $rowBlockers, true) || in_array('suite-evidence-test-count-regressed', $rowBlockers, true)) {
                    $regressed[] = $unit;
                }
                $blockers[] = [
                    'id' => 'suite-evidence-blocked',
                    'unit' => $unit,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($nextCountable && !$currentCountable) {
                $movement = 'advanced';
                $advanced[] = $unit;
            } elseif ($nextCountable) {
                $movement = 'preserved';
                $preserved[] = $unit;
            }

            if ($currentCountable) {
                $currentTestsTotal += $currentTests;
            }
            if ($nextCountable) {
                $nextTestsTotal += $nextTests;
            }
            $tiers[$tier] = ($tiers[$tier] ?? 0) + 1;

            $entries[] = [
                'unit' => $unit,
                'tier' => $tier,
                'movement' => $movement,
                'repository_head' => $head,
                'current_countable' => $currentCountable,
                'next_countable' => $nextCountable,
                'exit' => $exit,
                'errors' => $errors,
                'current_tests' => $currentTests,
                'next_tests' => $nextTests,
                'scripts' => $rowScripts,
                'artifact_path' => $artifactPath,
                'blocker_ids' => $rowBlockers,
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'current-head-focused-pass-countable') {
            $blockers[] = [
                'id' => 'focused-current-head-php-pass-blocked',
                'evidence' => 'focused PHP PASS-line admission did not satisfy current-head gates',
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
            ];
        }

        ksort($tiers, SORT_STRING);
        sort($advanced, SORT_STRING);
        sort($preserved, SORT_STRING);
        sort($blockedUnits, SORT_STRING);
        sort($regressed, SORT_STRING);
        $scriptList = array_keys($scripts);
        sort($scriptList, SORT_STRING);

        $blocked = $blockers !== [];
        $mappedDelta = count($advanced) > 0 ? 1 : 0;
        $extractCurrentNextIds = static function (string $text): array {
            $ids = [];
            if (preg_match_all('/(?:current[\s_-]*next|(?<=-)next)(\d+)/i', $text, $matches) > 0) {
                foreach ($matches[1] as $id) {
                    $ids[(int) $id] = 'current-next' . $id;
                }
            }

            return $ids;
        };

        $currentNextIds = [];
        foreach (array_merge($advanced, $preserved, $blockedUnits) as $unit) {
            $currentNextIds += $extractCurrentNextIds($unit);
        }
        foreach ($entries as $entry) {
            $entryText = (string) $entry['unit'] . ' ' . (string) $entry['artifact_path'] . ' ' . implode(' ', $entry['scripts']);
            $currentNextIds += $extractCurrentNextIds($entryText);
        }
        $currentNextIds += $extractCurrentNextIds($nonOverlapNote);
        ksort($currentNextIds, SORT_NUMERIC);
        $primaryCurrentNext = null;
        foreach ($advanced as $unit) {
            if (preg_match('/current[\s_-]*next(\d+)/i', $unit, $matches) === 1) {
                $primaryCurrentNext = 'current-next' . $matches[1];
                break;
            }
        }
        if ($primaryCurrentNext === null) {
            foreach ($entries as $entry) {
                if ($entry['movement'] !== 'advanced') {
                    continue;
                }

                $entryText = (string) $entry['unit'] . ' ' . (string) $entry['artifact_path'] . ' ' . implode(' ', $entry['scripts']);
                if (preg_match('/current[\s_-]*next(\d+)/i', $entryText, $matches) === 1) {
                    $primaryCurrentNext = 'current-next' . $matches[1];
                    break;
                }
            }
        }
        if ($primaryCurrentNext === null && preg_match('/current[\s_-]*next(\d+)/i', $nonOverlapNote, $matches) === 1) {
            $primaryCurrentNext = 'current-next' . $matches[1];
        }

        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'suite-evidence-countable';
        } elseif (!$blocked) {
            $status = 'suite-evidence-preserved';
        }
        $legacyGenericStatusIds = ['current-next93' => true, 'current-next98' => true];
        if ($primaryCurrentNext !== null && $status !== 'blocked' && !isset($legacyGenericStatusIds[$primaryCurrentNext])) {
            $status = $primaryCurrentNext . '-' . $status;
        }

        $record = [
            'status' => $status,
            'countable' => !$blocked && $mappedDelta > 0,
            'accepted_repository_head' => $acceptedRepositoryHead,
            'current_mapped' => $currentMapped,
            'next_mapped' => $blocked ? $currentMapped : $currentMapped + $mappedDelta,
            'mapped_delta' => $blocked ? 0 : $mappedDelta,
            'current_php_pass' => $currentPhpPass,
            'php_pass_delta' => $blocked ? 0 : (int) ($phpAdmission['pass_delta'] ?? 0),
            'next_php_pass' => $blocked ? $currentPhpPass : (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass),
            'row_count' => count($entries),
            'tier_count' => count($tiers),
            'tiers' => $tiers,
            'advanced_units' => $advanced,
            'preserved_units' => $preserved,
            'blocked_units' => $blockedUnits,
            'regressed_units' => $regressed,
            'current_tests_total' => $currentTestsTotal,
            'next_tests_total' => $nextTestsTotal,
            'tests_total_delta' => $blocked ? 0 : max(0, $nextTestsTotal - $currentTestsTotal),
            'target_script_count' => count($scriptList),
            'target_scripts' => $scriptList,
            'entries' => $entries,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'php_pass_admission' => $phpAdmission,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_suite_evidence' => !$blocked && $mappedDelta > 0,
            'counts_release_parity' => false,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => (!$blocked && $mappedDelta > 0)
                ? 'publish this bounded suite-evidence countability slice; release/all parity remains blocked until complete zero-error closure evidence is separately accepted'
                : 'keep suite evidence uncounted until accepted-head, lane-local artifact, zero-error runner, duplicate-runner, and focused PASS-line gates are clear',
            'dependency_closure' => 'no new support component needed; ' . ($primaryCurrentNext !== null ? $primaryCurrentNext . ' suite evidence ' : '') . 'composes lane-local artifact metadata, guarded runner commands, active-runner gates, and focused TestRunner PASS-line output only',
        ];
        foreach ($currentNextIds as $currentNextId) {
            $record['counts_suite_evidence_' . str_replace('-', '_', $currentNextId)] = !$blocked && $mappedDelta > 0 && $currentNextId === $primaryCurrentNext;
        }

        return $record;
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function releaseShardCountability(
        array $artifactRows,
        int $currentPhpPass,
        string $acceptedRepositoryHead,
        string $evidenceRepositoryHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        if ($artifactRows === []) {
            throw new \InvalidArgumentException('SQLite current-next70 release shard countability requires at least one artifact row');
        }

        $phpAdmission = $this->focusedPhpPassCurrentHeadAdmission(
            $currentPhpPass,
            $acceptedRepositoryHead,
            $evidenceRepositoryHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta
        );
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $entries = [];
        $blockers = [];
        $seen = [];
        $advanced = [];
        $preserved = [];
        $blocked = [];
        $regressed = [];
        $suites = [];
        $scripts = [];
        $testsBefore = 0;
        $testsAfter = 0;
        $releaseShardDelta = 0;
        $zeroErrorArtifacts = 0;

        foreach ($artifactRows as $label => $row) {
            $fallbackUnit = is_string($label) ? $label : 'current-next70-release-shard-' . count($entries);
            if (!is_array($row)) {
                $blocked[] = $fallbackUnit;
                $blockers[] = [
                    'id' => 'release-shard-row-invalid',
                    'unit' => $fallbackUnit,
                    'evidence' => 'release shard row must be an array',
                ];
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== '' ? $row['unit'] : $fallbackUnit;
            $suite = is_string($row['suite'] ?? null) && $row['suite'] !== '' ? strtolower($row['suite']) : 'unknown';
            $artifactHead = is_string($row['repository_head'] ?? null) ? trim($row['repository_head']) : '';
            $currentCountable = (bool) ($row['current_countable'] ?? false);
            $nextCountable = (bool) ($row['next_countable'] ?? false);
            $testsCurrent = max(0, $this->denominatorAuditInt($row, 'current_tests'));
            $testsNext = max(0, $this->denominatorAuditInt($row, 'next_tests'));
            $errors = max(0, $this->denominatorAuditInt($row, 'errors'));
            $command = is_string($row['command'] ?? null) ? trim($row['command']) : '';
            $rowScripts = array_values(array_unique(array_filter(
                is_array($row['scripts'] ?? null) ? $row['scripts'] : [],
                static fn (mixed $script): bool => is_string($script) && (str_ends_with($script, '.test') || str_contains($script, '*.test'))
            )));
            sort($rowScripts, SORT_STRING);
            foreach ($rowScripts as $script) {
                $scripts[$script] = true;
            }

            $rowBlockers = [];
            if (isset($seen[$unit])) {
                $rowBlockers[] = 'duplicate-release-shard-unit';
            }
            $seen[$unit] = true;
            if (!in_array($suite, ['release', 'all'], true)) {
                $rowBlockers[] = 'unsupported-suite-tier';
            }
            if ($artifactHead !== $acceptedRepositoryHead) {
                $rowBlockers[] = 'artifact-head-mismatch';
            }
            if (($row['artifact_path'] ?? '') === '') {
                $rowBlockers[] = 'missing-artifact-path';
            }
            if ($command === '') {
                $rowBlockers[] = 'missing-runner-command';
            }
            if ($errors > 0) {
                $rowBlockers[] = 'runner-artifact-has-errors';
            }
            if ($testsNext <= 0) {
                $rowBlockers[] = 'missing-runner-test-count';
            }
            if ($nextCountable && $rowScripts === []) {
                $rowBlockers[] = 'countable-release-shard-missing-scripts';
            }
            if ($currentCountable && !$nextCountable) {
                $rowBlockers[] = 'release-shard-countability-regressed';
            }
            if ($testsNext < $testsCurrent) {
                $rowBlockers[] = 'release-shard-test-count-regressed';
            }
            foreach (is_array($row['blockers'] ?? null) ? $row['blockers'] : [] as $rowBlocker) {
                if (is_string($rowBlocker) && $rowBlocker !== '') {
                    $rowBlockers[] = $rowBlocker;
                }
            }
            $rowBlockers = array_values(array_unique($rowBlockers));

            $movement = 'open';
            if ($rowBlockers !== []) {
                $movement = 'blocked';
                $blocked[] = $unit;
                if (in_array('release-shard-countability-regressed', $rowBlockers, true) || in_array('release-shard-test-count-regressed', $rowBlockers, true)) {
                    $regressed[] = $unit;
                }
                $blockers[] = [
                    'id' => 'release-shard-row-blocked',
                    'unit' => $unit,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($nextCountable && !$currentCountable) {
                $movement = 'advanced';
                $advanced[] = $unit;
                $releaseShardDelta++;
                $zeroErrorArtifacts++;
            } elseif ($nextCountable) {
                $movement = 'preserved';
                $preserved[] = $unit;
                $zeroErrorArtifacts++;
            }

            if ($currentCountable) {
                $testsBefore += $testsCurrent;
            }
            if ($nextCountable) {
                $testsAfter += $testsNext;
            }
            $suites[$suite] = ($suites[$suite] ?? 0) + 1;

            $entries[] = [
                'unit' => $unit,
                'suite' => $suite,
                'movement' => $movement,
                'repository_head' => $artifactHead,
                'current_countable' => $currentCountable,
                'next_countable' => $nextCountable,
                'current_tests' => $testsCurrent,
                'next_tests' => $testsNext,
                'errors' => $errors,
                'command' => $command,
                'scripts' => $rowScripts,
                'blocker_ids' => $rowBlockers,
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'current-head-focused-pass-countable') {
            $blockers[] = [
                'id' => 'focused-current-head-php-pass-blocked',
                'evidence' => 'focused PHP PASS-line admission did not satisfy current-head gates',
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
            ];
        }

        ksort($suites, SORT_STRING);
        sort($advanced, SORT_STRING);
        sort($preserved, SORT_STRING);
        sort($blocked, SORT_STRING);
        sort($regressed, SORT_STRING);
        $scriptList = array_keys($scripts);
        sort($scriptList, SORT_STRING);

        $status = 'blocked';
        if ($blockers === [] && $releaseShardDelta > 0) {
            $status = 'current-next70-release-shards-countable';
        } elseif ($blockers === []) {
            $status = 'current-next70-release-shards-preserved';
        }

        return [
            'status' => $status,
            'countable' => $status === 'current-next70-release-shards-countable',
            'accepted_repository_head' => $acceptedRepositoryHead,
            'evidence_repository_head' => $evidenceRepositoryHead,
            'current_php_pass' => $currentPhpPass,
            'php_pass_delta' => $blockers === [] ? (int) ($phpAdmission['pass_delta'] ?? 0) : 0,
            'next_php_pass' => $blockers === [] ? (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass) : $currentPhpPass,
            'release_shard_delta' => $blockers === [] ? $releaseShardDelta : 0,
            'zero_error_artifact_count' => $blockers === [] ? $zeroErrorArtifacts : 0,
            'current_tests_total' => $testsBefore,
            'next_tests_total' => $testsAfter,
            'tests_total_delta' => $blockers === [] ? max(0, $testsAfter - $testsBefore) : 0,
            'row_count' => count($entries),
            'suite_count' => count($suites),
            'suites' => $suites,
            'target_script_count' => count($scriptList),
            'target_scripts' => $scriptList,
            'advanced_units' => $advanced,
            'preserved_units' => $preserved,
            'blocked_units' => $blocked,
            'regressed_units' => $regressed,
            'entries' => $entries,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'php_pass_admission' => $phpAdmission,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_release_parity' => false,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => $status === 'current-next70-release-shards-countable'
                ? 'publish current-next70 accepted-HEAD zero-error release/all shard countability while keeping full release/all parity gated on a complete broad artifact'
                : 'keep current-next70 release shard countability uncounted until artifact provenance, zero-error output, duplicate-runner, and focused PHP admission blockers are clear',
            'dependency_closure' => 'no new support component needed; current-next70 release shard countability composes accepted-HEAD runner artifacts, zero-error shard outputs, duplicate-runner gating, and focused TestRunner PASS-line output only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function suiteReleaseRunnerRebaseAdmission(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $launcherBaseHead,
        string $nextAcceptedHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        if (trim($launcherBaseHead) === '') {
            throw new \InvalidArgumentException('SQLite current-next74 release-runner admission requires the launcher base HEAD');
        }

        $rebasedRows = [];
        $rebaseBlockers = [];
        $sharedSourceHeads = [];
        foreach ($artifactRows as $label => $row) {
            if (!is_array($row)) {
                $rebasedRows[$label] = $row;
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== '' ? $row['unit'] : (is_string($label) ? $label : 'current-next74-artifact-' . count($rebasedRows));
            $baseHead = is_string($row['launcher_base_head'] ?? null) ? trim($row['launcher_base_head']) : '';
            $sharedHead = is_string($row['shared_source_head'] ?? null) ? trim($row['shared_source_head']) : '';
            if ($sharedHead !== '') {
                $sharedSourceHeads[$sharedHead] = true;
            }
            if ($baseHead !== $launcherBaseHead) {
                $rebaseBlockers[] = [
                    'id' => 'launcher-base-head-mismatch',
                    'unit' => $unit,
                    'expected' => $launcherBaseHead,
                    'actual' => $baseHead,
                    'evidence' => 'current-next74 release-runner admission must be rebased on the launcher-printed Base accepted HEAD, not mutable shared main/dashboard source',
                ];
            }

            $row['current_head'] = $launcherBaseHead;
            $row['next_head'] = $nextAcceptedHead;
            $rebasedRows[$label] = $row;
        }

        $record = $this->suiteReleaseRunnerAdmission(
            $rebasedRows,
            $currentMapped,
            $currentPhpPass,
            $launcherBaseHead,
            $nextAcceptedHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta,
            $processSnapshot
        );

        $blockers = array_merge($rebaseBlockers, is_array($record['blockers'] ?? null) ? $record['blockers'] : []);
        $blocked = $blockers !== [];
        $mappedDelta = $blocked ? 0 : (int) ($record['mapped_delta'] ?? 0);
        $phpPassDelta = $blocked ? 0 : (int) ($record['php_pass_delta'] ?? 0);
        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-next74-release-runner-rebased-admitted';
        } elseif (!$blocked) {
            $status = 'current-next74-release-runner-rebased-preserved';
        }

        $record['status'] = $status;
        $record['countable'] = $status === 'current-next74-release-runner-rebased-admitted';
        $record['launcher_base_head'] = $launcherBaseHead;
        $record['current_accepted_head'] = $launcherBaseHead;
        $record['next_accepted_head'] = $nextAcceptedHead;
        $record['shared_source_heads'] = array_keys($sharedSourceHeads);
        sort($record['shared_source_heads'], SORT_STRING);
        $record['blocker_count'] = count($blockers);
        $record['blockers'] = $blockers;
        $record['mapped_delta'] = $mappedDelta;
        $record['next_mapped'] = $blocked ? $currentMapped : $currentMapped + $mappedDelta;
        $record['php_pass_delta'] = $phpPassDelta;
        $record['next_php_pass'] = $blocked ? $currentPhpPass : $currentPhpPass + $phpPassDelta;
        $record['zero_error_artifact_count'] = $blocked ? 0 : (int) ($record['zero_error_artifact_count'] ?? 0);
        $record['counts_release_runner_admission_current_next72'] = false;
        $record['counts_release_runner_admission_current_next74'] = $status === 'current-next74-release-runner-rebased-admitted';
        $record['counts_release_parity'] = false;
        $record['next_gate'] = $status === 'current-next74-release-runner-rebased-admitted'
            ? 'publish only current-next74 rebased release-runner artifact admission and exact focused PASS-line movement; release/all parity remains gated on a separate broad zero-error artifact'
            : 'keep current-next74 admission uncounted until launcher-base, lane-local artifact, zero-error runner, duplicate-runner, and focused PASS-line gates are clear';
        $record['dependency_closure'] = 'no new support component needed; current-next74 release-runner rebase admission composes lane-local artifact rows, launcher Base accepted HEAD provenance, guarded runner commands, active-runner gates, and focused TestRunner PASS-line output only';

        return $record;
    }

