            $implementationHead = is_string($row['implementation_source_head'] ?? null) ? trim($row['implementation_source_head']) : '';

            foreach ([
                'dashboard' => $dashboardHead,
                'status' => $statusHead,
                'implementation' => $implementationHead,
            ] as $source => $head) {
                if ($head !== '') {
                    $sourceHeads[$source][$head] = true;
                }
            }

            if ($baseHead !== $launcherBaseHead) {
                $rebaseBlockers[] = [
                    'id' => 'launcher-base-head-mismatch',
                    'unit' => $unit,
                    'expected' => $launcherBaseHead,
                    'actual' => $baseHead,
                    'evidence' => 'current-next82 release-runner countability must be rebased on the launcher-printed Base accepted HEAD, not the dashboard/status/current-source heads',
                ];
            }
            if ($dashboardHead !== $dashboardSourceHead) {
                $rebaseBlockers[] = [
                    'id' => 'dashboard-source-head-mismatch',
                    'unit' => $unit,
                    'expected' => $dashboardSourceHead,
                    'actual' => $dashboardHead,
                    'evidence' => 'current-next82 release-runner countability keeps dashboard source provenance explicit before admitting the artifact',
                ];
            }
            if ($statusHead !== $statusSourceHead) {
                $rebaseBlockers[] = [
                    'id' => 'status-source-head-mismatch',
                    'unit' => $unit,
                    'expected' => $statusSourceHead,
                    'actual' => $statusHead,
                    'evidence' => 'current-next82 release-runner countability keeps lane-status source provenance explicit before admitting the artifact',
                ];
            }
            if ($implementationHead !== $implementationSourceHead) {
                $rebaseBlockers[] = [
                    'id' => 'implementation-source-head-mismatch',
                    'unit' => $unit,
                    'expected' => $implementationSourceHead,
                    'actual' => $implementationHead,
                    'evidence' => 'current-next82 release-runner countability keeps latest integrated implementation source provenance explicit before admitting the artifact',
                ];
            }

            $row['current_head'] = $launcherBaseHead;
            $row['next_head'] = $nextAcceptedHead;
            $rebasedRows[$label] = $row;
        }

        $record = $this->suiteReleaseRunnerAdmission(
            $rebasedRows,
            $currentMapped,
            $currentPhpPass,
            $launcherBaseHead,
            $nextAcceptedHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta,
            $processSnapshot
        );

        $blockers = array_merge($rebaseBlockers, is_array($record['blockers'] ?? null) ? $record['blockers'] : []);
        $blocked = $blockers !== [];
        $mappedDelta = $blocked ? 0 : min(1, (int) ($record['mapped_delta'] ?? 0));
        $phpPassDelta = $blocked ? 0 : (int) ($record['php_pass_delta'] ?? 0);
        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-next82-release-runner-current-source-countable';
        } elseif (!$blocked) {
            $status = 'current-next82-release-runner-current-source-preserved';
        }

        $normalizedSourceHeads = [];
        foreach ($sourceHeads as $source => $heads) {
            $normalizedSourceHeads[$source] = array_keys($heads);
            sort($normalizedSourceHeads[$source], SORT_STRING);
        }
        ksort($normalizedSourceHeads, SORT_STRING);

        $record['status'] = $status;
        $record['countable'] = $status === 'current-next82-release-runner-current-source-countable';
        $record['launcher_base_head'] = $launcherBaseHead;
        $record['dashboard_source_head'] = $dashboardSourceHead;
        $record['status_source_head'] = $statusSourceHead;
        $record['implementation_source_head'] = $implementationSourceHead;
        $record['current_accepted_head'] = $launcherBaseHead;
        $record['next_accepted_head'] = $nextAcceptedHead;
        $record['source_heads'] = $normalizedSourceHeads;
        $record['blocker_count'] = count($blockers);
        $record['blockers'] = $blockers;
        $record['mapped_delta'] = $mappedDelta;
        $record['next_mapped'] = $blocked ? $currentMapped : $currentMapped + $mappedDelta;
        $record['php_pass_delta'] = $phpPassDelta;
        $record['next_php_pass'] = $blocked ? $currentPhpPass : $currentPhpPass + $phpPassDelta;
        $record['zero_error_artifact_count'] = $blocked ? 0 : (int) ($record['zero_error_artifact_count'] ?? 0);
        $record['counts_release_runner_admission_current_next72'] = false;
        $record['counts_release_runner_countability_current_source_next82'] = $status === 'current-next82-release-runner-current-source-countable';
        $record['counts_release_parity'] = false;
        $record['next_gate'] = $status === 'current-next82-release-runner-current-source-countable'
            ? 'publish only current-next82 rebased current-source release-runner countability and exact focused PASS-line movement; release/all parity remains gated on a separate broad zero-error artifact'
            : 'keep current-next82 countability uncounted until launcher-base, dashboard/status/source provenance, lane-local artifact, zero-error runner, duplicate-runner, and focused PASS-line gates are clear';
        $record['dependency_closure'] = 'no new support component needed; current-next82 release-runner countability composes lane-local artifact rows, launcher Base accepted HEAD provenance, dashboard/status/source heads, guarded runner commands, active-runner gates, and focused TestRunner PASS-line output only';

        return $record;
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function suiteUpstreamRunnerAdmissionBurnupCurrentSource(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $launcherBaseHead,
        string $dashboardSourceHead,
        string $statusSourceHead,
        string $implementationSourceHead,
        string $nextAcceptedHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        if ($artifactRows === []) {
            throw new \InvalidArgumentException('SQLite current-source next94 upstream-runner admission burnup requires at least one artifact row');
        }
        foreach ([
            'launcher base HEAD' => $launcherBaseHead,
            'dashboard source HEAD' => $dashboardSourceHead,
            'status source HEAD' => $statusSourceHead,
            'implementation source HEAD' => $implementationSourceHead,
            'next accepted HEAD' => $nextAcceptedHead,
        ] as $label => $head) {
            if (trim($head) === '') {
                throw new \InvalidArgumentException("SQLite current-source next94 upstream-runner admission burnup requires {$label}");
            }
        }

        $phpAdmission = $this->focusedPhpPassCurrentHeadAdmission(
            $currentPhpPass,
            $launcherBaseHead,
            $launcherBaseHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta
        );
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $entries = [];
        $blockers = [];
        $seen = [];
        $admitted = [];
        $preserved = [];
        $blocked = [];
        $regressed = [];
        $categories = [];
        $scripts = [];
        $testsDelta = 0;

        foreach ($artifactRows as $label => $row) {
            $fallbackUnit = is_string($label) ? $label : 'current-source-next94-artifact-' . count($entries);
            if (!is_array($row)) {
                $blocked[] = $fallbackUnit;
                $blockers[] = [
                    'id' => 'current-source-next94-row-invalid',
                    'unit' => $fallbackUnit,
                    'evidence' => 'upstream-runner admission burnup row must be an array',
                ];
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== '' ? $row['unit'] : $fallbackUnit;
            $category = is_string($row['category'] ?? null) && $row['category'] !== '' ? $row['category'] : 'upstream-runner-admission';
            $baseHead = is_string($row['launcher_base_head'] ?? null) ? trim($row['launcher_base_head']) : '';
            $dashboardHead = is_string($row['dashboard_source_head'] ?? null) ? trim($row['dashboard_source_head']) : '';
            $statusHead = is_string($row['status_source_head'] ?? null) ? trim($row['status_source_head']) : '';
            $implementationHead = is_string($row['implementation_source_head'] ?? null) ? trim($row['implementation_source_head']) : '';
            $artifactPath = is_string($row['artifact_path'] ?? null) ? trim($row['artifact_path']) : '';
            $command = is_string($row['runner_command'] ?? null) ? trim($row['runner_command']) : '';
            $evidence = is_string($row['evidence'] ?? null) ? trim($row['evidence']) : '';
            $currentStatus = is_string($row['current_status'] ?? null) ? $row['current_status'] : 'missing';
            $nextStatus = is_string($row['next_status'] ?? null) ? $row['next_status'] : 'missing';
            $currentCountable = $currentStatus === 'countable' || (bool) ($row['current_countable'] ?? false);
            $nextCountable = $nextStatus === 'admitted' || $nextStatus === 'countable' || (bool) ($row['next_countable'] ?? false);
            $exit = $this->denominatorAuditInt($row, 'exit');
            $errors = max(0, $this->denominatorAuditInt($row, 'errors'));
            $currentTests = max(0, $this->denominatorAuditInt($row, 'current_tests'));
            $nextTests = max(0, $this->denominatorAuditInt($row, 'next_tests'));
            $rowScripts = array_values(array_unique(array_filter(
                is_array($row['scripts'] ?? null) ? $row['scripts'] : [],
                static fn (mixed $script): bool => is_string($script) && str_ends_with($script, '.test')
            )));
            sort($rowScripts, SORT_STRING);
            foreach ($rowScripts as $script) {
                $scripts[$script] = true;
            }

            $rowBlockers = [];
            if (isset($seen[$unit])) {
                $rowBlockers[] = 'duplicate-current-source-next94-unit';
            }
            $seen[$unit] = true;
            if ($baseHead !== $launcherBaseHead) {
                $rowBlockers[] = 'launcher-base-head-mismatch';
            }
            if ($dashboardHead !== $dashboardSourceHead) {
                $rowBlockers[] = 'dashboard-source-head-mismatch';
            }
            if ($statusHead !== $statusSourceHead) {
                $rowBlockers[] = 'status-source-head-mismatch';
            }
            if ($implementationHead !== $implementationSourceHead) {
                $rowBlockers[] = 'implementation-source-head-mismatch';
            }
            if ($artifactPath === '' || !str_starts_with($artifactPath, 'lanes/libsqlite/')) {
                $rowBlockers[] = 'artifact-path-not-lane-local';
            }
            if ($command === '' || !str_contains($command, 'testfixture') || !str_contains($command, 'testrunner.tcl') || !preg_match('/(?:^|\s)--stop-on-error(?:\s|$)/', $command)) {
                $rowBlockers[] = 'guarded-runner-command-missing';
            }
            if ($nextCountable && $exit !== 0) {
                $rowBlockers[] = 'runner-exit-not-zero';
            }
            if ($nextCountable && $errors !== 0) {
                $rowBlockers[] = 'runner-errors-not-zero';
            }
            if ($nextCountable && $nextTests < 1) {
                $rowBlockers[] = 'runner-test-count-missing';
            }
            if ($nextCountable && $rowScripts === []) {
                $rowBlockers[] = 'runner-scripts-missing';
            }
            if ($nextCountable && $evidence === '') {
                $rowBlockers[] = 'runner-evidence-missing';
            }
            if ($currentCountable && !$nextCountable) {
                $rowBlockers[] = 'runner-countability-regressed';
            }
            if ($nextTests < $currentTests) {
                $rowBlockers[] = 'runner-test-count-regressed';
            }
            if (($row['counts_release_parity'] ?? false) === true) {
                $rowBlockers[] = 'release-parity-claim-not-allowed';
            }
            foreach (is_array($row['blockers'] ?? null) ? $row['blockers'] : [] as $rowBlocker) {
                if (is_string($rowBlocker) && $rowBlocker !== '') {
                    $rowBlockers[] = $rowBlocker;
                }
            }
            $rowBlockers = array_values(array_unique($rowBlockers));

            $movement = 'open';
            if ($rowBlockers !== []) {
                $movement = 'blocked';
                $blocked[] = $unit;
                if (in_array('runner-countability-regressed', $rowBlockers, true) || in_array('runner-test-count-regressed', $rowBlockers, true)) {
                    $regressed[] = $unit;
                }
                $blockers[] = [
                    'id' => 'current-source-next94-artifact-blocked',
                    'unit' => $unit,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($nextCountable && !$currentCountable) {
                $movement = 'admitted';
                $admitted[] = $unit;
                $testsDelta += max(0, $nextTests - $currentTests);
            } elseif ($nextCountable) {
                $movement = 'preserved';
                $preserved[] = $unit;
            }

            $categories[$category] = ($categories[$category] ?? 0) + 1;
            $entries[] = [
                'unit' => $unit,
                'category' => $category,
                'movement' => $movement,
                'current_status' => $currentStatus,
                'next_status' => $nextStatus,
                'current_countable' => $currentCountable,
                'next_countable' => $nextCountable,
                'exit' => $exit,
                'errors' => $errors,
                'current_tests' => $currentTests,
                'next_tests' => $nextTests,
                'scripts' => $rowScripts,
                'artifact_path' => $artifactPath,
                'blocker_ids' => $rowBlockers,
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'current-head-focused-pass-countable') {
            $blockers[] = [
                'id' => 'focused-current-head-php-pass-blocked',
                'evidence' => 'focused PHP PASS-line admission did not satisfy current-source next94 gates',
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
            ];
        }

        ksort($categories, SORT_STRING);
        sort($admitted, SORT_STRING);
        sort($preserved, SORT_STRING);
        sort($blocked, SORT_STRING);
        sort($regressed, SORT_STRING);
        $scriptList = array_keys($scripts);
        sort($scriptList, SORT_STRING);

        $isBlocked = $blockers !== [];
        $mappedDelta = !$isBlocked && $admitted !== [] ? 1 : 0;
        $phpPassDelta = !$isBlocked ? (int) ($phpAdmission['pass_delta'] ?? 0) : 0;
        $status = 'blocked';
        if (!$isBlocked && $mappedDelta > 0) {
            $status = 'current-source-next94-upstream-runner-admission-burnup-countable';
        } elseif (!$isBlocked) {
            $status = 'current-source-next94-upstream-runner-admission-burnup-preserved';
        }

        return [
            'status' => $status,
            'countable' => $status === 'current-source-next94-upstream-runner-admission-burnup-countable',
            'launcher_base_head' => $launcherBaseHead,
            'dashboard_source_head' => $dashboardSourceHead,
            'status_source_head' => $statusSourceHead,
            'implementation_source_head' => $implementationSourceHead,
            'next_accepted_head' => $nextAcceptedHead,
            'current_mapped' => $currentMapped,
            'next_mapped' => $isBlocked ? $currentMapped : $currentMapped + $mappedDelta,
            'mapped_delta' => $isBlocked ? 0 : $mappedDelta,
            'current_php_pass' => $currentPhpPass,
            'php_pass_delta' => $phpPassDelta,
            'next_php_pass' => $isBlocked ? $currentPhpPass : $currentPhpPass + $phpPassDelta,
            'row_count' => count($entries),
            'category_count' => count($categories),
            'categories' => $categories,
            'admitted_units' => $admitted,
            'preserved_units' => $preserved,
            'blocked_units' => $blocked,
            'regressed_units' => $regressed,
            'tests_total_delta' => $isBlocked ? 0 : $testsDelta,
            'target_script_count' => count($scriptList),
            'target_scripts' => $scriptList,
            'entries' => $entries,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'php_pass_admission' => $phpAdmission,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_upstream_runner_admission_burnup_current_source_next94' => $status === 'current-source-next94-upstream-runner-admission-burnup-countable',
            'counts_release_parity' => false,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => $status === 'current-source-next94-upstream-runner-admission-burnup-countable'
                ? 'publish only the current-source next94 upstream-runner admission burnup row and exact focused PASS-line movement; release/all parity remains gated on separate zero-error broad artifacts'
                : 'keep current-source next94 admission burnup uncounted until source provenance, lane-local artifacts, zero-error guarded runner rows, duplicate-runner, and focused PASS-line gates are clear',
            'dependency_closure' => 'no new support component needed; current-source next94 upstream-runner admission burnup composes lane-local artifact rows, launcher Base accepted HEAD provenance, dashboard/status/implementation heads, guarded runner commands, active-runner gates, and focused TestRunner PASS-line output only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function releaseRunnerCountabilityCurrentSource(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $launcherBaseHead,
        string $dashboardSourceHead,
        string $statusSourceHead,
        string $implementationSourceHead,
        string $nextAcceptedHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        $releaseBlockers = [];
        foreach ($artifactRows as $label => $row) {
            $unit = is_array($row) && is_string($row['unit'] ?? null) && $row['unit'] !== ''
                ? $row['unit']
                : (is_string($label) ? $label : 'current-source-next99-artifact');
            $command = is_array($row) && is_string($row['runner_command'] ?? null) ? trim($row['runner_command']) : '';
            $scripts = is_array($row) && is_array($row['scripts'] ?? null) ? $row['scripts'] : [];
            $hasReleaseCommand = preg_match('/(?:^|\s)release(?:\s|$)/', $command) === 1;
            $hasReleaseScript = in_array('testrunner.test', $scripts, true);

            if (!$hasReleaseCommand || !$hasReleaseScript) {
                $releaseBlockers[] = [
                    'id' => 'current-source-next99-release-runner-command-blocked',
                    'unit' => $unit,
                    'evidence' => 'current-source next99 countability admits only guarded release-runner artifacts with release command scope and testrunner.test provenance',
                ];
            }
        }

        $record = $this->suiteUpstreamRunnerAdmissionBurnupCurrentSource(
            $artifactRows,
            $currentMapped,
            $currentPhpPass,
            $launcherBaseHead,
            $dashboardSourceHead,
            $statusSourceHead,
            $implementationSourceHead,
            $nextAcceptedHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta,
            $processSnapshot
        );

        $blockers = array_merge($releaseBlockers, is_array($record['blockers'] ?? null) ? $record['blockers'] : []);
        $blocked = $blockers !== [];
        $mappedDelta = !$blocked && ($record['admitted_units'] ?? []) !== [] ? 1 : 0;
        $phpPassDelta = !$blocked ? (int) ($record['php_pass_delta'] ?? 0) : 0;
        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-source-next99-release-runner-countability-countable';
        } elseif (!$blocked) {
            $status = 'current-source-next99-release-runner-countability-preserved';
        }

        $record['status'] = $status;
        $record['countable'] = $status === 'current-source-next99-release-runner-countability-countable';
        $record['blocker_count'] = count($blockers);
        $record['blockers'] = $blockers;
        $record['mapped_delta'] = $blocked ? 0 : $mappedDelta;
        $record['next_mapped'] = $blocked ? $currentMapped : $currentMapped + $mappedDelta;
        $record['php_pass_delta'] = $phpPassDelta;
        $record['next_php_pass'] = $blocked ? $currentPhpPass : $currentPhpPass + $phpPassDelta;
        $record['tests_total_delta'] = $blocked ? 0 : (int) ($record['tests_total_delta'] ?? 0);
        $record['counts_upstream_runner_admission_burnup_current_source_next94'] = false;
        $record['counts_release_runner_countability_current_source_next99'] = $status === 'current-source-next99-release-runner-countability-countable';
        $record['counts_release_parity'] = false;
        $record['next_gate'] = $status === 'current-source-next99-release-runner-countability-countable'
            ? 'publish only the current-source next99 release-runner countability row and exact focused PASS-line movement; release/all parity remains gated on a separate broad zero-error artifact'
            : 'keep current-source next99 release-runner countability uncounted until source provenance, lane-local artifacts, guarded release runner rows, duplicate-runner, and focused PASS-line gates are clear';
        $record['dependency_closure'] = 'no new support component needed; current-source next99 release-runner countability composes lane-local artifact rows, launcher Base accepted HEAD provenance, dashboard/status/implementation heads, guarded release-runner commands, active-runner gates, and focused TestRunner PASS-line output only';

        return $record;
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function upstreamRunnerAdmission(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $launcherBaseHead,
        string $dashboardSourceHead,
        string $statusSourceHead,
        string $implementationSourceHead,
        string $nextSourceHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        if ($artifactRows === []) {
            throw new \InvalidArgumentException('SQLite current-source next102 upstream-runner admission requires at least one artifact row');
        }
        foreach ([
            'launcher base HEAD' => $launcherBaseHead,
            'dashboard source HEAD' => $dashboardSourceHead,
            'status source HEAD' => $statusSourceHead,
            'implementation source HEAD' => $implementationSourceHead,
            'next source HEAD' => $nextSourceHead,
        ] as $label => $head) {
            if (trim($head) === '') {
                throw new \InvalidArgumentException("SQLite current-source next102 upstream-runner admission requires {$label}");
            }
        }

        $phpAdmission = $this->focusedPhpPassCurrentHeadAdmission(
            $currentPhpPass,
            $launcherBaseHead,
            $launcherBaseHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta
        );
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $entries = [];
        $blockers = [];
        $seen = [];
        $admitted = [];
        $preserved = [];
        $blocked = [];
        $sourceHeads = [];
        $scripts = [];
        $testsDelta = 0;

        foreach ($artifactRows as $label => $row) {
            $fallbackUnit = is_string($label) ? $label : 'current-source-next102-artifact-' . count($entries);
            if (!is_array($row)) {
                $blocked[] = $fallbackUnit;
                $blockers[] = [
                    'id' => 'current-source-next102-row-invalid',
                    'unit' => $fallbackUnit,
                    'evidence' => 'upstream-runner admission row must be an array',
                ];
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== '' ? $row['unit'] : $fallbackUnit;
            $artifactPath = is_string($row['artifact_path'] ?? null) ? trim($row['artifact_path']) : '';
            $command = is_string($row['runner_command'] ?? null) ? trim($row['runner_command']) : '';
            $evidence = is_string($row['evidence'] ?? null) ? trim($row['evidence']) : '';
            $kind = is_string($row['kind'] ?? null) && $row['kind'] !== '' ? $row['kind'] : 'bounded-upstream-runner';
            $artifactSourceHead = is_string($row['source_head'] ?? null) ? trim($row['source_head']) : '';
            $rowLauncherHead = is_string($row['launcher_base_head'] ?? null) ? trim($row['launcher_base_head']) : '';
            $rowDashboardHead = is_string($row['dashboard_source_head'] ?? null) ? trim($row['dashboard_source_head']) : '';
            $rowStatusHead = is_string($row['status_source_head'] ?? null) ? trim($row['status_source_head']) : '';
            $rowImplementationHead = is_string($row['implementation_source_head'] ?? null) ? trim($row['implementation_source_head']) : '';
            $currentCountable = (bool) ($row['current_countable'] ?? false);
            $nextCountable = (bool) ($row['next_countable'] ?? false);
            $exit = $this->denominatorAuditInt($row, 'exit');
            $errors = max(0, $this->denominatorAuditInt($row, 'errors'));
            $currentTests = max(0, $this->denominatorAuditInt($row, 'current_tests'));
            $nextTests = max(0, $this->denominatorAuditInt($row, 'next_tests'));
            $rowScripts = array_values(array_unique(array_filter(
                is_array($row['scripts'] ?? null) ? $row['scripts'] : [],
                static fn (mixed $script): bool => is_string($script) && preg_match('/^[A-Za-z0-9_.*+-]+\.test$/', $script) === 1
            )));
            sort($rowScripts, SORT_STRING);
            foreach ($rowScripts as $script) {
                $scripts[$script] = true;
            }

            $rowBlockers = [];
            if (isset($seen[$unit])) {
                $rowBlockers[] = 'duplicate-current-source-next102-unit';
            }
            $seen[$unit] = true;
            if ($artifactSourceHead !== $nextSourceHead) {
                $rowBlockers[] = 'next-source-head-mismatch';
            }
            if ($rowLauncherHead !== $launcherBaseHead) {
                $rowBlockers[] = 'launcher-base-head-mismatch';
            }
            if ($rowDashboardHead !== $dashboardSourceHead) {
                $rowBlockers[] = 'dashboard-source-head-mismatch';
            }
            if ($rowStatusHead !== $statusSourceHead) {
                $rowBlockers[] = 'status-source-head-mismatch';
            }
            if ($rowImplementationHead !== $implementationSourceHead) {
                $rowBlockers[] = 'implementation-source-head-mismatch';
            }
            if ($artifactPath === '' || !str_starts_with($artifactPath, 'lanes/libsqlite/')) {
                $rowBlockers[] = 'artifact-path-not-lane-local';
            }
            if ($command === '' || !str_contains($command, 'testfixture') || !str_contains($command, 'testrunner.tcl') || !preg_match('/(?:^|\s)--stop-on-error(?:\s|$)/', $command)) {
                $rowBlockers[] = 'guarded-runner-command-missing';
            }
            if ($nextCountable && $exit !== 0) {
                $rowBlockers[] = 'runner-exit-not-zero';
            }
            if ($nextCountable && $errors !== 0) {
                $rowBlockers[] = 'runner-errors-not-zero';
            }
            if ($nextCountable && $nextTests < 1) {
                $rowBlockers[] = 'runner-test-count-missing';
            }
            if ($nextCountable && $rowScripts === []) {
                $rowBlockers[] = 'runner-scripts-missing';
            }
            if ($nextCountable && $evidence === '') {
                $rowBlockers[] = 'runner-evidence-missing';
            }
            if ($currentCountable && !$nextCountable) {
                $rowBlockers[] = 'runner-countability-regressed';
            }
            if ($nextTests < $currentTests) {
                $rowBlockers[] = 'runner-test-count-regressed';
            }
            if (($row['counts_release_parity'] ?? false) === true) {
                $rowBlockers[] = 'release-parity-claim-not-allowed';
            }
            foreach (is_array($row['blockers'] ?? null) ? $row['blockers'] : [] as $rowBlocker) {
                if (is_string($rowBlocker) && $rowBlocker !== '') {
                    $rowBlockers[] = $rowBlocker;
                }
            }
            $rowBlockers = array_values(array_unique($rowBlockers));

            $movement = 'open';
            if ($rowBlockers !== []) {
                $movement = 'blocked';
                $blocked[] = $unit;
                $blockers[] = [
                    'id' => 'current-source-next102-artifact-blocked',
                    'unit' => $unit,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($nextCountable && !$currentCountable) {
                $movement = 'next-source-admitted';
                $admitted[] = $unit;
                $testsDelta += max(0, $nextTests - $currentTests);
            } elseif ($nextCountable) {
                $movement = 'current-source-preserved';
                $preserved[] = $unit;
            }

            if ($artifactSourceHead !== '') {
                $sourceHeads[$artifactSourceHead] = true;
            }

            $entries[] = [
                'unit' => $unit,
                'kind' => $kind,
                'movement' => $movement,
                'source_head' => $artifactSourceHead,
                'current_countable' => $currentCountable,
                'next_countable' => $nextCountable,
                'exit' => $exit,
                'errors' => $errors,
                'current_tests' => $currentTests,
                'next_tests' => $nextTests,
                'scripts' => $rowScripts,
                'artifact_path' => $artifactPath,
                'blocker_ids' => $rowBlockers,
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'current-head-focused-pass-countable') {
            $blockers[] = [
                'id' => 'focused-current-head-php-pass-blocked',
                'evidence' => 'focused PHP PASS-line admission did not satisfy current-source next102 gates',
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
            ];
        }

        sort($admitted, SORT_STRING);
        sort($preserved, SORT_STRING);
        sort($blocked, SORT_STRING);
        $sourceHeadList = array_keys($sourceHeads);
        sort($sourceHeadList, SORT_STRING);
        $scriptList = array_keys($scripts);
        sort($scriptList, SORT_STRING);

        $isBlocked = $blockers !== [];
        $mappedDelta = !$isBlocked && $admitted !== [] ? 1 : 0;
        $phpPassDelta = !$isBlocked ? (int) ($phpAdmission['pass_delta'] ?? 0) : 0;
        $status = 'blocked';
        if (!$isBlocked && $mappedDelta > 0) {
            $status = 'current-source-next102-upstream-runner-admission-countable';
        } elseif (!$isBlocked) {
            $status = 'current-source-next102-upstream-runner-admission-preserved';
        }

        return [
            'status' => $status,
            'countable' => $status === 'current-source-next102-upstream-runner-admission-countable',
            'launcher_base_head' => $launcherBaseHead,
            'dashboard_source_head' => $dashboardSourceHead,
            'status_source_head' => $statusSourceHead,
            'implementation_source_head' => $implementationSourceHead,
            'next_source_head' => $nextSourceHead,
            'artifact_source_heads' => $sourceHeadList,
            'current_mapped' => $currentMapped,
            'next_mapped' => $isBlocked ? $currentMapped : $currentMapped + $mappedDelta,
            'mapped_delta' => $isBlocked ? 0 : $mappedDelta,
            'current_php_pass' => $currentPhpPass,
            'php_pass_delta' => $phpPassDelta,
            'next_php_pass' => $isBlocked ? $currentPhpPass : $currentPhpPass + $phpPassDelta,
            'row_count' => count($entries),
            'admitted_units' => $admitted,
            'preserved_units' => $preserved,
            'blocked_units' => $blocked,
            'tests_total_delta' => $isBlocked ? 0 : $testsDelta,
            'target_script_count' => count($scriptList),
            'target_scripts' => $scriptList,
            'entries' => $entries,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'php_pass_admission' => $phpAdmission,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_upstream_runner_admission_current_source_next102' => $status === 'current-source-next102-upstream-runner-admission-countable',
            'counts_release_runner_admission_current_next72' => false,
            'counts_release_runner_countability_current_source_next99' => false,
            'counts_release_parity' => false,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => $status === 'current-source-next102-upstream-runner-admission-countable'
                ? 'publish only the current-source next102 upstream-runner admission row and exact focused PASS-line movement; release/all parity remains gated on a separate broad zero-error artifact'
                : 'keep current-source next102 admission uncounted until next-source provenance, lane-local artifacts, zero-error guarded runner rows, duplicate-runner state, and focused PASS-line gates are clear',
            'dependency_closure' => 'no new support component needed; current-source next102 upstream-runner admission composes lane-local bounded runner artifacts, launcher/dashboard/status/implementation source heads, active-runner gates, and focused TestRunner PASS-line output only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function suiteUpstreamRunnerGapBurnup(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $launcherBaseHead,
        string $dashboardSourceHead,
        string $statusSourceHead,
        string $implementationSourceHead,
        string $nextSourceHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        $record = $this->upstreamRunnerAdmission(
            $artifactRows,
            $currentMapped,
            $currentPhpPass,
            $launcherBaseHead,
            $dashboardSourceHead,
            $statusSourceHead,
            $implementationSourceHead,
            $nextSourceHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta,
            $processSnapshot
        );

        $gapRows = [];
        $resolvedGapIds = [];
        $preservedGapIds = [];
        $blockedGapIds = [];
        $blockedReasons = [];

        foreach (is_array($record['entries'] ?? null) ? $record['entries'] : [] as $entry) {
            if (!is_array($entry)) {
                continue;
            }

            $unit = is_string($entry['unit'] ?? null) ? $entry['unit'] : '';
            $source = $artifactRows[$unit] ?? null;
            if (!is_array($source)) {
                foreach ($artifactRows as $candidate) {
                    if (is_array($candidate) && ($candidate['unit'] ?? null) === $unit) {
                        $source = $candidate;
                        break;
                    }
                }
            }

            $gapId = is_array($source) && is_string($source['gap_id'] ?? null) && $source['gap_id'] !== ''
                ? $source['gap_id']
                : $unit;
            $gapStatus = is_array($source) && is_string($source['gap_status'] ?? null) && $source['gap_status'] !== ''
                ? $source['gap_status']
                : 'open';
            $removedBlocker = is_array($source) && is_string($source['removed_blocker'] ?? null)
                ? trim($source['removed_blocker'])
                : '';
            $movement = is_string($entry['movement'] ?? null) ? $entry['movement'] : 'open';
            $rowBlockers = is_array($entry['blocker_ids'] ?? null) ? $entry['blocker_ids'] : [];

            if ($movement === 'next-source-admitted') {
                if ($gapStatus !== 'removed') {
                    $rowBlockers[] = 'gap-status-not-removed';
                }
                if ($removedBlocker === '') {
                    $rowBlockers[] = 'removed-blocker-missing';
                }
            }

            $rowBlockers = array_values(array_unique(array_filter($rowBlockers, 'is_string')));
            if ($rowBlockers !== []) {
                $blockedGapIds[] = $gapId;
                $blockedReasons[] = [
                    'id' => 'current-source-next104-gap-burnup-row-blocked',
                    'unit' => $unit,
                    'gap_id' => $gapId,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($movement === 'next-source-admitted') {
                $resolvedGapIds[] = $gapId;
            } elseif ($movement === 'current-source-preserved') {
                $preservedGapIds[] = $gapId;
            }

            $gapRows[] = [
                'unit' => $unit,
                'gap_id' => $gapId,
                'gap_status' => $gapStatus,
                'removed_blocker' => $removedBlocker,
                'movement' => $movement,
                'blocker_ids' => $rowBlockers,
            ];
        }

        sort($resolvedGapIds, SORT_STRING);
        sort($preservedGapIds, SORT_STRING);
        sort($blockedGapIds, SORT_STRING);

        $blockers = array_merge(is_array($record['blockers'] ?? null) ? $record['blockers'] : [], $blockedReasons);
        $blocked = $blockers !== [];
        $mappedDelta = !$blocked && $resolvedGapIds !== [] ? 1 : 0;
        $phpPassDelta = !$blocked ? (int) ($record['php_pass_delta'] ?? 0) : 0;
        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-source-next104-upstream-runner-gap-burnup-countable';
        } elseif (!$blocked) {
            $status = 'current-source-next104-upstream-runner-gap-burnup-preserved';
        }

        $record['status'] = $status;
        $record['countable'] = $status === 'current-source-next104-upstream-runner-gap-burnup-countable';
        $record['blocker_count'] = count($blockers);
        $record['blockers'] = $blockers;
        $record['mapped_delta'] = $blocked ? 0 : $mappedDelta;
        $record['next_mapped'] = $blocked ? $currentMapped : $currentMapped + $mappedDelta;
        $record['php_pass_delta'] = $phpPassDelta;
        $record['next_php_pass'] = $blocked ? $currentPhpPass : $currentPhpPass + $phpPassDelta;
        $record['tests_total_delta'] = $blocked ? 0 : (int) ($record['tests_total_delta'] ?? 0);
        $record['gap_rows'] = $gapRows;
        $record['resolved_gap_ids'] = $resolvedGapIds;
        $record['preserved_gap_ids'] = $preservedGapIds;
        $record['blocked_gap_ids'] = $blockedGapIds;
        $record['counts_upstream_runner_admission_current_source_next102'] = false;
        $record['counts_upstream_runner_gap_burnup_current_source_next104'] = $status === 'current-source-next104-upstream-runner-gap-burnup-countable';
        $record['counts_release_parity'] = false;
        $record['next_gate'] = $status === 'current-source-next104-upstream-runner-gap-burnup-countable'
            ? 'publish only the current-source next104 upstream-runner gap-burnup row and exact focused PASS-line movement; release/all parity remains gated on separate zero-error broad artifacts'
            : 'keep current-source next104 upstream-runner gap burnup uncounted until source provenance, lane-local artifacts, zero-error guarded runner rows, removed-blocker evidence, duplicate-runner state, and focused PASS-line gates are clear';
        $record['dependency_closure'] = 'no new support component needed; current-source next104 upstream-runner gap burnup composes lane-local bounded runner artifacts, removed-blocker classifications, launcher/dashboard/status/implementation source heads, active-runner gates, and focused TestRunner PASS-line output only';

        return $record;
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function upstreamRunnerSuiteEvidenceRebase(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $launcherBaseHead,
        string $dashboardSourceHead,
        string $statusSourceHead,
        string $implementationSourceHead,
        string $nextSourceHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        $record = $this->suiteUpstreamRunnerGapBurnup(
            $artifactRows,
            $currentMapped,
            $currentPhpPass,
            $launcherBaseHead,
            $dashboardSourceHead,
            $statusSourceHead,
            $implementationSourceHead,
            $nextSourceHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta,
            $processSnapshot
        );

        $rebaseRows = [];
        $rebasedGapIds = [];
        $preservedGapIds = [];
        $blockedGapIds = [];
        $blockers = is_array($record['blockers'] ?? null) ? $record['blockers'] : [];

        foreach (is_array($record['gap_rows'] ?? null) ? $record['gap_rows'] : [] as $gapRow) {
            if (!is_array($gapRow)) {
                continue;
            }

            $unit = is_string($gapRow['unit'] ?? null) ? $gapRow['unit'] : '';
            $source = null;
            foreach ($artifactRows as $candidate) {
                if (is_array($candidate) && ($candidate['unit'] ?? null) === $unit) {
                    $source = $candidate;
                    break;
                }
            }

            $rebaseStatus = is_array($source) && is_string($source['rebase_status'] ?? null) && $source['rebase_status'] !== ''
                ? $source['rebase_status']
                : 'open';
            $rebaseReason = is_array($source) && is_string($source['rebase_reason'] ?? null)
                ? trim($source['rebase_reason'])
                : '';
            $gapId = is_string($gapRow['gap_id'] ?? null) ? $gapRow['gap_id'] : $unit;
            $movement = is_string($gapRow['movement'] ?? null) ? $gapRow['movement'] : 'open';
            $rowBlockers = is_array($gapRow['blocker_ids'] ?? null) ? $gapRow['blocker_ids'] : [];

            if ($movement === 'next-source-admitted') {
                if ($rebaseStatus !== 'rebased') {
                    $rowBlockers[] = 'rebase-status-not-rebased';
                }
                if ($rebaseReason === '') {
                    $rowBlockers[] = 'rebase-reason-missing';
                }
            }

            $rowBlockers = array_values(array_unique(array_filter($rowBlockers, 'is_string')));
            if ($rowBlockers !== []) {
                $blockedGapIds[] = $gapId;
                $blockers[] = [
                    'id' => 'current-source-next108-rebase-row-blocked',
                    'unit' => $unit,
                    'gap_id' => $gapId,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($movement === 'next-source-admitted') {
                $rebasedGapIds[] = $gapId;
            } elseif ($movement === 'current-source-preserved') {
                $preservedGapIds[] = $gapId;
            }

            $gapRow['rebase_status'] = $rebaseStatus;
            $gapRow['rebase_reason'] = $rebaseReason;
            $gapRow['blocker_ids'] = $rowBlockers;
            $rebaseRows[] = $gapRow;
        }

        sort($rebasedGapIds, SORT_STRING);
        sort($preservedGapIds, SORT_STRING);
        sort($blockedGapIds, SORT_STRING);

        $blocked = $blockers !== [];
        $mappedDelta = !$blocked && $rebasedGapIds !== [] ? 1 : 0;
        $phpPassDelta = !$blocked ? (int) ($record['php_pass_delta'] ?? 0) : 0;
        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-source-next108-upstream-runner-suite-evidence-rebase-countable';
        } elseif (!$blocked) {
            $status = 'current-source-next108-upstream-runner-suite-evidence-rebase-preserved';
        }

        $record['status'] = $status;
        $record['countable'] = $status === 'current-source-next108-upstream-runner-suite-evidence-rebase-countable';
        $record['blockers'] = $blockers;
        $record['blocker_count'] = count($blockers);
        $record['mapped_delta'] = $blocked ? 0 : $mappedDelta;
        $record['next_mapped'] = $blocked ? $currentMapped : $currentMapped + $mappedDelta;
        $record['php_pass_delta'] = $phpPassDelta;
        $record['next_php_pass'] = $blocked ? $currentPhpPass : $currentPhpPass + $phpPassDelta;
        $record['tests_total_delta'] = $blocked ? 0 : (int) ($record['tests_total_delta'] ?? 0);
        $record['rebase_rows'] = $rebaseRows;
        $record['rebased_gap_ids'] = $rebasedGapIds;
        $record['preserved_rebase_gap_ids'] = $preservedGapIds;
        $record['blocked_rebase_gap_ids'] = $blockedGapIds;
        $record['counts_upstream_runner_gap_burnup_current_source_next104'] = false;
        $record['counts_upstream_runner_suite_evidence_rebase_current_source_next108'] = $status === 'current-source-next108-upstream-runner-suite-evidence-rebase-countable';
        $record['counts_release_parity'] = false;
        $record['next_gate'] = $status === 'current-source-next108-upstream-runner-suite-evidence-rebase-countable'
            ? 'publish only the current-source next108 upstream-runner suite evidence rebase row and exact focused PASS-line movement; release/all parity remains gated on separate zero-error broad artifacts'
            : 'keep current-source next108 suite evidence rebase uncounted until provenance, lane-local artifacts, removed-blocker and rebase classifications, duplicate-runner state, and focused PASS-line gates are clear';
        $record['dependency_closure'] = 'no new support component needed; current-source next108 upstream-runner suite evidence rebase composes accepted artifact rows, rebase classifications, source-head provenance gates, active-runner gates, and focused TestRunner PASS-line output only';

        return $record;
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function upstreamRunnerFinalEvidence(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $launcherBaseHead,
        string $dashboardSourceHead,
        string $statusSourceHead,
        string $implementationSourceHead,
        string $nextSourceHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        $record = $this->upstreamRunnerSuiteEvidenceRebase(
            $artifactRows,
            $currentMapped,
            $currentPhpPass,
            $launcherBaseHead,
            $dashboardSourceHead,
            $statusSourceHead,
            $implementationSourceHead,
            $nextSourceHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta,
            $processSnapshot
        );

        $finalRows = [];
        $finalizedIds = [];
        $preservedIds = [];
        $blockedIds = [];
        $seenBaselines = [];
        $duplicateBaselines = [];
        $finalBlockers = [];

        foreach (is_array($record['rebase_rows'] ?? null) ? $record['rebase_rows'] : [] as $row) {
            if (!is_array($row)) {
                continue;
            }

            $unit = is_string($row['unit'] ?? null) ? $row['unit'] : '';
            $source = null;
            foreach ($artifactRows as $candidate) {
                if (is_array($candidate) && ($candidate['unit'] ?? null) === $unit) {
                    $source = $candidate;
                    break;
                }
            }

            $finalId = is_array($source) && is_string($source['final_evidence_id'] ?? null) && $source['final_evidence_id'] !== ''
                ? $source['final_evidence_id']
                : (is_string($row['gap_id'] ?? null) && $row['gap_id'] !== '' ? $row['gap_id'] : $unit);
            $finalStatus = is_array($source) && is_string($source['final_evidence_status'] ?? null) && $source['final_evidence_status'] !== ''
                ? $source['final_evidence_status']
                : 'open';
            $baselineId = is_array($source) && is_string($source['stale_baseline_id'] ?? null)
                ? trim($source['stale_baseline_id'])
                : '';
            $movement = is_string($row['movement'] ?? null) ? $row['movement'] : 'open';
            $rowBlockers = is_array($row['blocker_ids'] ?? null) ? $row['blocker_ids'] : [];

            if ($baselineId !== '') {
                if (isset($seenBaselines[$baselineId])) {
                    $duplicateBaselines[$baselineId] = true;
                    $rowBlockers[] = 'duplicate-stale-baseline-id';
                }
                $seenBaselines[$baselineId] = true;
            }

            if ($movement === 'next-source-admitted') {
                if ($finalStatus !== 'finalized') {
                    $rowBlockers[] = 'final-evidence-status-not-finalized';
                }
                if ($baselineId === '') {
                    $rowBlockers[] = 'stale-baseline-id-missing';
                }
            }

            $rowBlockers = array_values(array_unique(array_filter($rowBlockers, 'is_string')));
            if ($rowBlockers !== []) {
                $blockedIds[] = $finalId;
                $finalBlockers[] = [
                    'id' => 'current-source-next109-final-evidence-row-blocked',
                    'unit' => $unit,
                    'final_evidence_id' => $finalId,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($movement === 'next-source-admitted') {
                $finalizedIds[] = $finalId;
            } elseif ($movement === 'current-source-preserved') {
                $preservedIds[] = $finalId;
            }

            $row['final_evidence_id'] = $finalId;
            $row['final_evidence_status'] = $finalStatus;
            $row['stale_baseline_id'] = $baselineId;
            $row['blocker_ids'] = $rowBlockers;
            $finalRows[] = $row;
        }

        sort($finalizedIds, SORT_STRING);
        sort($preservedIds, SORT_STRING);
        sort($blockedIds, SORT_STRING);
        $duplicateBaselineIds = array_keys($duplicateBaselines);
        sort($duplicateBaselineIds, SORT_STRING);

        $blockers = array_merge(is_array($record['blockers'] ?? null) ? $record['blockers'] : [], $finalBlockers);
        $blocked = $blockers !== [];
        $mappedDelta = !$blocked && $finalizedIds !== [] ? 1 : 0;
        $phpPassDelta = !$blocked ? (int) ($record['php_pass_delta'] ?? 0) : 0;
        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-source-next109-upstream-runner-final-countable';
        } elseif (!$blocked) {
            $status = 'current-source-next109-upstream-runner-final-preserved';
        }

        $record['status'] = $status;
        $record['countable'] = $status === 'current-source-next109-upstream-runner-final-countable';
        $record['blocker_count'] = count($blockers);
        $record['blockers'] = $blockers;
        $record['mapped_delta'] = $blocked ? 0 : $mappedDelta;
        $record['next_mapped'] = $blocked ? $currentMapped : $currentMapped + $mappedDelta;
        $record['php_pass_delta'] = $phpPassDelta;
        $record['next_php_pass'] = $blocked ? $currentPhpPass : $currentPhpPass + $phpPassDelta;
        $record['tests_total_delta'] = $blocked ? 0 : (int) ($record['tests_total_delta'] ?? 0);
        $record['final_evidence_rows'] = $finalRows;
        $record['finalized_evidence_ids'] = $finalizedIds;
        $record['preserved_final_evidence_ids'] = $preservedIds;
        $record['blocked_final_evidence_ids'] = $blockedIds;
        $record['duplicate_stale_baseline_ids'] = $duplicateBaselineIds;
        $record['counts_upstream_runner_suite_evidence_rebase_current_source_next108'] = false;
        $record['counts_upstream_runner_final_current_source_next109'] = $status === 'current-source-next109-upstream-runner-final-countable';
        $record['counts_release_parity'] = false;
        $record['next_gate'] = $status === 'current-source-next109-upstream-runner-final-countable'
            ? 'publish only the current-source next109 final upstream-runner evidence row and exact focused PASS-line movement; duplicate stale baselines and release/all parity remain blocked'
            : 'keep current-source next109 final upstream-runner evidence uncounted until rebase provenance, finalized evidence status, unique stale-baseline IDs, duplicate-runner state, and focused PASS-line gates are clear';
        $record['dependency_closure'] = 'no new support component needed; current-source next109 final evidence composes next108 rebase rows, unique stale-baseline IDs, source-head provenance gates, active-runner gates, and focused TestRunner PASS-line output only';

        return $record;
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function suiteUpstreamRunnerFinalEvidence(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $launcherBaseHead,
        string $dashboardSourceHead,
        string $statusSourceHead,
        string $implementationSourceHead,
        string $nextSourceHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        if ($artifactRows === []) {
            throw new \InvalidArgumentException('SQLite current-source next106 final suite evidence requires at least one artifact row');
        }

        $record = $this->upstreamRunnerFullSuiteCountability(
            array_values($artifactRows),
            $currentMapped,
            $currentPhpPass,
            $launcherBaseHead,
            $dashboardSourceHead,
            $statusSourceHead,
            $implementationSourceHead,
            $nextSourceHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            null,
            $processSnapshot
        );
        $focusedOutput = $this->parseFocusedPhpTestOutput($focusedTestOutput);

        $finalRows = [];
        $isolatedIds = [];
        $preservedIds = [];
        $blockedPrerequisiteIds = [];
        $blockedFinalIds = [];
        $finalBlockers = [];

        foreach (is_array($record['admitted_units'] ?? null) || is_array($record['preserved_units'] ?? null) || is_array($record['blockers'] ?? null) ? array_values($artifactRows) : [] as $row) {
            if (!is_array($row)) {
                continue;
            }

            $unit = is_string($row['unit'] ?? null) ? $row['unit'] : '';
            $gapId = is_string($row['gap_id'] ?? null) && $row['gap_id'] !== '' ? $row['gap_id'] : $unit;
            $currentCountable = (bool) ($row['current_countable'] ?? false);
            $nextCountable = (bool) ($row['next_countable'] ?? false);
            $movement = $nextCountable && !$currentCountable ? 'next-source-admitted' : ($nextCountable ? 'current-source-preserved' : 'open');
            $rowBlockers = [];

            $prerequisiteRange = is_string($row['prerequisite_range'] ?? null) ? trim($row['prerequisite_range']) : '';
            $prerequisiteStatus = is_string($row['prerequisite_status'] ?? null) ? trim($row['prerequisite_status']) : '';
            $readinessEvidence = is_string($row['readiness_evidence'] ?? null) ? trim($row['readiness_evidence']) : '';
            $finalRange = is_string($row['final_range'] ?? null) ? trim($row['final_range']) : '';
            $finalStatus = is_string($row['final_range_status'] ?? null) ? trim($row['final_range_status']) : '';
            $finalEvidence = is_string($row['final_range_evidence'] ?? null) ? trim($row['final_range_evidence']) : '';

            if ($movement === 'next-source-admitted') {
                if ($prerequisiteRange !== 'current-source-next101-103') {
                    $rowBlockers[] = 'prerequisite-range-not-next101-103';
                }
                if ($prerequisiteStatus !== 'ready') {
                    $rowBlockers[] = 'prerequisite-status-not-ready';
                }
                if ($readinessEvidence === '') {
                    $rowBlockers[] = 'readiness-evidence-missing';
                }
                if ($finalRange !== 'current-source-next104-106') {
                    $rowBlockers[] = 'final-range-not-next104-106';
                }
                if ($finalStatus !== 'isolated') {
                    $rowBlockers[] = 'final-range-not-isolated';
                }
                if ($finalEvidence === '') {
                    $rowBlockers[] = 'final-range-evidence-missing';
                }
            }

            if ($rowBlockers !== []) {
                if (in_array('prerequisite-range-not-next101-103', $rowBlockers, true)
                    || in_array('prerequisite-status-not-ready', $rowBlockers, true)
                    || in_array('readiness-evidence-missing', $rowBlockers, true)) {
                    $blockedPrerequisiteIds[] = $gapId;
                }
                if (in_array('final-range-not-next104-106', $rowBlockers, true)
                    || in_array('final-range-not-isolated', $rowBlockers, true)
                    || in_array('final-range-evidence-missing', $rowBlockers, true)) {
                    $blockedFinalIds[] = $gapId;
                }
                $finalBlockers[] = [
                    'id' => 'current-source-next106-final-suite-row-blocked',
                    'unit' => $unit,
                    'gap_id' => $gapId,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($movement === 'next-source-admitted') {
                $isolatedIds[] = $gapId;
            } elseif ($movement === 'current-source-preserved') {
                $preservedIds[] = $gapId;
            }

            $finalRows[] = [
                'unit' => $unit,
                'gap_id' => $gapId,
                'prerequisite_range' => $prerequisiteRange,
                'prerequisite_status' => $prerequisiteStatus,
                'readiness_evidence' => $readinessEvidence,
                'final_range' => $finalRange,
                'final_range_status' => $finalStatus,
                'final_range_evidence' => $finalEvidence,
                'movement' => $movement,
                'blocker_ids' => $rowBlockers,
            ];
        }

        sort($isolatedIds, SORT_STRING);
        sort($preservedIds, SORT_STRING);
        sort($blockedPrerequisiteIds, SORT_STRING);
        sort($blockedFinalIds, SORT_STRING);

        $blockers = array_merge(is_array($record['blockers'] ?? null) ? $record['blockers'] : [], $finalBlockers);
        if ($expectedPassDelta !== null && $focusedOutput['pass_lines'] !== $expectedPassDelta) {
            $blockers[] = [
                'id' => 'focused-php-pass-delta-mismatch',
                'evidence' => 'focused PHP PASS-line admission did not match current-source next106 expected PASS movement',
                'expected' => $expectedPassDelta,
                'actual' => $focusedOutput['pass_lines'],
            ];
        }
        $blocked = $blockers !== [];
        $mappedDelta = !$blocked && $isolatedIds !== [] ? 1 : 0;
        $phpPassDelta = !$blocked ? ($expectedPassDelta ?? (int) ($record['php_pass_delta'] ?? 0)) : 0;
        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-source-next106-final-suite-evidence-countable';
        } elseif (!$blocked) {
            $status = 'current-source-next106-final-suite-evidence-preserved';
        }

        $record['status'] = $status;
        $record['countable'] = $status === 'current-source-next106-final-suite-evidence-countable';
        $record['blockers'] = $blockers;
        $record['blocker_count'] = count($blockers);
        $record['mapped_delta'] = $blocked ? 0 : $mappedDelta;
        $record['next_mapped'] = $blocked ? $currentMapped : $currentMapped + $mappedDelta;
        $record['php_pass_delta'] = $phpPassDelta;
        $record['next_php_pass'] = $blocked ? $currentPhpPass : $currentPhpPass + $phpPassDelta;
        $record['tests_total_delta'] = $blocked ? 0 : (int) ($record['tests_total_delta'] ?? 0);
        $record['final_range_rows'] = $finalRows;
        $record['isolated_final_gap_ids'] = $isolatedIds;
        $record['preserved_final_gap_ids'] = $preservedIds;
        $record['blocked_prerequisite_gap_ids'] = array_values(array_unique($blockedPrerequisiteIds));
        $record['blocked_final_gap_ids'] = array_values(array_unique($blockedFinalIds));
        $record['counts_upstream_runner_gap_burnup_current_source_next104'] = false;
        $record['counts_upstream_runner_prerequisite_ready_current_source_next105'] = false;
        $record['counts_upstream_runner_final_current_source_next106'] = $status === 'current-source-next106-final-suite-evidence-countable';
        $record['counts_release_parity'] = false;
        $record['next_gate'] = $status === 'current-source-next106-final-suite-evidence-countable'
            ? 'publish only the isolated current-source next104-106 final suite-evidence row and exact focused PASS-line movement; release/all parity remains blocked'
            : 'keep current-source next106 final suite evidence uncounted until next101-103 readiness, next104-106 isolation, source provenance, duplicate-runner state, and focused PASS-line gates are clear';
        $record['dependency_closure'] = 'no new support component needed; current-source next106 final suite evidence composes next101-103 readiness, isolated next104-106 final rows, source-head provenance, active-runner gates, and focused TestRunner PASS-line output only';

        return $record;
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function upstreamRunnerSuiteEvidenceInitialPreparedTriplet(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $launcherBaseHead,
        string $dashboardSourceHead,
        string $statusSourceHead,
        string $implementationSourceHead,
        string $nextSourceHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        $record = $this->upstreamRunnerFinalEvidence(
            $artifactRows,
            $currentMapped,
            $currentPhpPass,
            $launcherBaseHead,
            $dashboardSourceHead,
            $statusSourceHead,
            $implementationSourceHead,
            $nextSourceHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta,
            $processSnapshot
        );

        $expectedPhases = ['next110', 'next111', 'next112'];
        $phaseRows = [];
        $preparedPhases = [];
        $preservedPhases = [];
        $blockedPhases = [];
        $seenPhaseIds = [];
        $duplicatePhaseIds = [];
        $phaseBlockers = [];

        foreach (is_array($record['final_evidence_rows'] ?? null) ? $record['final_evidence_rows'] : [] as $row) {
            if (!is_array($row)) {
                continue;
            }

            $unit = is_string($row['unit'] ?? null) ? $row['unit'] : '';
            $source = null;
            foreach ($artifactRows as $candidate) {
                if (is_array($candidate) && ($candidate['unit'] ?? null) === $unit) {
                    $source = $candidate;
                    break;
                }
            }

            $phase = is_array($source) && is_string($source['suite_phase'] ?? null)
                ? trim($source['suite_phase'])
                : '';
            $phaseStatus = is_array($source) && is_string($source['suite_phase_status'] ?? null)
                ? trim($source['suite_phase_status'])
                : '';
            $phaseId = is_array($source) && is_string($source['suite_phase_id'] ?? null) && $source['suite_phase_id'] !== ''
                ? $source['suite_phase_id']
                : ($phase !== '' ? $phase : $unit);
            $phaseEvidence = is_array($source) && is_string($source['suite_phase_evidence'] ?? null)
                ? trim($source['suite_phase_evidence'])
                : '';
            $artifactPath = is_array($source) && is_string($source['artifact_path'] ?? null)
                ? $source['artifact_path']
                : (is_string($row['artifact_path'] ?? null) ? $row['artifact_path'] : '');
            $movement = is_string($row['movement'] ?? null) ? $row['movement'] : 'open';
            $rowBlockers = is_array($row['blocker_ids'] ?? null) ? $row['blocker_ids'] : [];

            if ($phase !== '' && !in_array($phase, $expectedPhases, true)) {
                $rowBlockers[] = 'suite-phase-outside-next110-112';
            }
            if ($phase !== '' && isset($seenPhaseIds[$phase])) {
                $duplicatePhaseIds[$phase] = true;
                $rowBlockers[] = 'duplicate-suite-phase';
            }
            if ($phase !== '') {
                $seenPhaseIds[$phase] = true;
            }
            if ($phase !== '' && !str_starts_with($artifactPath, 'lanes/libsqlite/notes/')) {
                $rowBlockers[] = 'suite-phase-artifact-not-lane-note';
            }
            if ($movement === 'next-source-admitted') {
                if ($phase === '') {
                    $rowBlockers[] = 'suite-phase-missing';
                }
                if ($phaseStatus !== 'prepared') {
                    $rowBlockers[] = 'suite-phase-status-not-prepared';
                }
                if ($phaseEvidence === '') {
                    $rowBlockers[] = 'suite-phase-evidence-missing';
                }
                if (is_array($source) && ($source['current_source_only'] ?? false) !== true) {
                    $rowBlockers[] = 'current-source-only-flag-missing';
                }
            }
            if (is_array($source) && ($source['counts_release_parity'] ?? false) === true) {
                $rowBlockers[] = 'release-parity-claim-not-allowed';
            }

            $rowBlockers = array_values(array_unique(array_filter($rowBlockers, 'is_string')));
            if ($rowBlockers !== []) {
                $blockedPhases[] = $phaseId;
                $phaseBlockers[] = [
                    'id' => 'current-source-next110-112-suite-phase-row-blocked',
                    'unit' => $unit,
                    'suite_phase_id' => $phaseId,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($movement === 'next-source-admitted') {
                $preparedPhases[] = $phase;
            } elseif ($movement === 'current-source-preserved' && $phase !== '') {
                $preservedPhases[] = $phase;
            }

            $row['suite_phase'] = $phase;
            $row['suite_phase_id'] = $phaseId;
            $row['suite_phase_status'] = $phaseStatus;
            $row['suite_phase_evidence'] = $phaseEvidence;
            $row['blocker_ids'] = $rowBlockers;
            $phaseRows[] = $row;
        }

        sort($preparedPhases, SORT_STRING);
        sort($preservedPhases, SORT_STRING);
        sort($blockedPhases, SORT_STRING);
        $coveredPhases = array_values(array_unique(array_merge($preparedPhases, $preservedPhases)));
        $missingPhases = array_values(array_diff($expectedPhases, $coveredPhases));
        $duplicatePhases = array_keys($duplicatePhaseIds);
        sort($duplicatePhases, SORT_STRING);

        if ($missingPhases !== []) {
            $phaseBlockers[] = [
                'id' => 'current-source-next110-112-suite-phases-incomplete',
                'unit' => 'upstream-runner-suite-evidence-current-source-next110-112',
                'suite_phase_id' => implode(',', $missingPhases),
                'evidence' => 'missing prepared suite phases: ' . implode(', ', $missingPhases),
            ];
        }

        $blockers = array_merge(is_array($record['blockers'] ?? null) ? $record['blockers'] : [], $phaseBlockers);
        $blocked = $blockers !== [];
        $mappedDelta = !$blocked && $missingPhases === [] && $preparedPhases !== [] ? count($preparedPhases) : 0;
        $phpPassDelta = !$blocked ? (int) ($record['php_pass_delta'] ?? 0) : 0;
        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-source-next110-112-upstream-suite-evidence-prepared';
        } elseif (!$blocked) {
            $status = 'current-source-next110-112-upstream-suite-evidence-preserved';
        }

        $record['status'] = $status;
        $record['countable'] = $status === 'current-source-next110-112-upstream-suite-evidence-prepared';
        $record['blockers'] = $blockers;
        $record['blocker_count'] = count($blockers);
        $record['mapped_delta'] = $mappedDelta;
        $record['next_mapped'] = $blocked ? $currentMapped : $currentMapped + $mappedDelta;
        $record['php_pass_delta'] = $phpPassDelta;
        $record['next_php_pass'] = $blocked ? $currentPhpPass : $currentPhpPass + $phpPassDelta;
        $record['tests_total_delta'] = $blocked ? 0 : (int) ($record['tests_total_delta'] ?? 0);
        $record['suite_phase_rows'] = $phaseRows;
        $record['prepared_suite_phases'] = $preparedPhases;
        $record['preserved_suite_phases'] = $preservedPhases;
        $record['blocked_suite_phase_ids'] = $blockedPhases;
        $record['missing_suite_phases'] = $missingPhases;
        $record['duplicate_suite_phases'] = $duplicatePhases;
        $record['counts_upstream_runner_final_current_source_next109'] = false;
        $record['counts_upstream_suite_evidence_current_source_next110_112'] = $status === 'current-source-next110-112-upstream-suite-evidence-prepared';
        $record['counts_release_parity'] = false;
        $record['next_gate'] = $status === 'current-source-next110-112-upstream-suite-evidence-prepared'
            ? 'publish only the isolated current-source next110-112 upstream-suite evidence triplet and exact focused PASS-line movement; release/all parity remains blocked'
            : 'keep current-source next110-112 suite evidence uncounted until all three prepared phases, current-source-only flags, lane-local notes, duplicate-runner state, and focused PASS-line gates are clear';
        $record['dependency_closure'] = 'no new support component needed; current-source next110-112 suite evidence composes next109 final rows with three prepared current-source-only suite phases and focused TestRunner PASS-line output only';

        return $record;
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function upstreamRunnerSuiteEvidenceRebasedPreparedTriplet(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $launcherBaseHead,
        string $dashboardSourceHead,
        string $statusSourceHead,
        string $implementationSourceHead,
        string $nextSourceHead,
