        $mappedDelta = !$blocked && $missingPhases === [] && $preparedPhases !== [] ? count($preparedPhases) : 0;
        $phpAdmission = is_array($record['php_pass_admission'] ?? null) ? $record['php_pass_admission'] : [];
        $phpPassDelta = !$blocked ? (int) ($phpAdmission['pass_delta'] ?? $record['php_pass_delta'] ?? 0) : 0;
        $testsTotalDelta = 0;
        if (!$blocked) {
            foreach ($phaseRows as $phaseRow) {
                if (($phaseRow['movement'] ?? null) !== 'next-source-admitted') {
                    continue;
                }
                foreach ($artifactRows as $candidate) {
                    if (is_array($candidate) && ($candidate['unit'] ?? null) === ($phaseRow['unit'] ?? null)) {
                        $testsTotalDelta += max(0, (int) ($candidate['next_tests'] ?? 0) - (int) ($candidate['current_tests'] ?? 0));
                        break;
                    }
                }
            }
        }

        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-source-prepared-octet-upstream-suite-evidence-prepared';
        } elseif (!$blocked) {
            $status = 'current-source-prepared-octet-upstream-suite-evidence-preserved';
        }

        $record['status'] = $status;
        $record['countable'] = $status === 'current-source-prepared-octet-upstream-suite-evidence-prepared';
        $record['blockers'] = $blockers;
        $record['blocker_count'] = count($blockers);
        $record['mapped_delta'] = $mappedDelta;
        $record['next_mapped'] = $blocked ? $currentMapped : $currentMapped + $mappedDelta;
        $record['php_pass_delta'] = $phpPassDelta;
        $record['next_php_pass'] = $blocked ? $currentPhpPass : $currentPhpPass + $phpPassDelta;
        $record['tests_total_delta'] = $testsTotalDelta;
        $record['suite_phase_rows'] = $phaseRows;
