    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function upstreamRunnerSuiteEvidenceFinalPreparedOctet(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $launcherBaseHead,
        string $dashboardSourceHead,
        string $statusSourceHead,
        string $implementationSourceHead,
        string $nextSourceHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        $record = $this->upstreamRunnerSuiteEvidencePreparedOctet(
            $artifactRows,
            $currentMapped,
            $currentPhpPass,
            $launcherBaseHead,
            $dashboardSourceHead,
            $statusSourceHead,
            $implementationSourceHead,
            $nextSourceHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta,
            $processSnapshot
        );

        $expectedPhases = ['next157', 'next158', 'next159', 'next160', 'next161', 'next162', 'next163', 'next164'];
        $phaseRows = [];
        $preparedPhases = [];
        $preservedPhases = [];
        $blockedPhases = [];
        $seenPhaseIds = [];
        $duplicatePhaseIds = [];
        $phaseBlockers = [];

        foreach (is_array($record['final_evidence_rows'] ?? null) ? $record['final_evidence_rows'] : [] as $row) {
            if (!is_array($row)) {
                continue;
            }

            $unit = is_string($row['unit'] ?? null) ? $row['unit'] : '';
            $source = null;
            foreach ($artifactRows as $candidate) {
                if (is_array($candidate) && ($candidate['unit'] ?? null) === $unit) {
                    $source = $candidate;
                    break;
                }
            }

            $phase = is_array($source) && is_string($source['suite_phase'] ?? null) ? trim($source['suite_phase']) : '';
            $phaseStatus = is_array($source) && is_string($source['suite_phase_status'] ?? null) ? trim($source['suite_phase_status']) : '';
            $phaseId = is_array($source) && is_string($source['suite_phase_id'] ?? null) && $source['suite_phase_id'] !== '' ? $source['suite_phase_id'] : ($phase !== '' ? $phase : $unit);
            $phaseEvidence = is_array($source) && is_string($source['suite_phase_evidence'] ?? null) ? trim($source['suite_phase_evidence']) : '';
            $artifactPath = is_array($source) && is_string($source['artifact_path'] ?? null) ? $source['artifact_path'] : (is_string($row['artifact_path'] ?? null) ? $row['artifact_path'] : '');
            $movement = is_string($row['movement'] ?? null) ? $row['movement'] : 'open';
            $rowBlockers = is_array($row['blocker_ids'] ?? null) ? $row['blocker_ids'] : [];

            if ($phase !== '' && !in_array($phase, $expectedPhases, true)) {
                $rowBlockers[] = 'suite-phase-outside-next157-164';
            }
            if ($phase !== '' && isset($seenPhaseIds[$phase])) {
                $duplicatePhaseIds[$phase] = true;
                $rowBlockers[] = 'duplicate-suite-phase';
            }
            if ($phase !== '') {
                $seenPhaseIds[$phase] = true;
            }
            if ($phase !== '' && !str_starts_with($artifactPath, 'lanes/libsqlite/notes/')) {
                $rowBlockers[] = 'suite-phase-artifact-not-lane-note';
            }
            if ($movement === 'next-source-admitted') {
                if ($phase === '') {
                    $rowBlockers[] = 'suite-phase-missing';
                }
                if ($phaseStatus !== 'prepared') {
                    $rowBlockers[] = 'suite-phase-status-not-prepared';
                }
                if ($phaseEvidence === '') {
                    $rowBlockers[] = 'suite-phase-evidence-missing';
                }
                if (is_array($source) && ($source['current_source_only'] ?? false) !== true) {
                    $rowBlockers[] = 'current-source-only-flag-missing';
                }
            }
            if (is_array($source) && ($source['counts_release_parity'] ?? false) === true) {
                $rowBlockers[] = 'release-parity-claim-not-allowed';
            }

            $rowBlockers = array_values(array_unique(array_filter($rowBlockers, 'is_string')));
            if ($rowBlockers !== []) {
                $blockedPhases[] = $phaseId;
                $phaseBlockers[] = [
                    'id' => 'current-source-next157-164-suite-phase-row-blocked',
                    'unit' => $unit,
                    'suite_phase_id' => $phaseId,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($movement === 'next-source-admitted') {
                $preparedPhases[] = $phase;
            } elseif ($movement === 'current-source-preserved' && $phase !== '') {
                $preservedPhases[] = $phase;
            }

            $row['suite_phase'] = $phase;
            $row['suite_phase_id'] = $phaseId;
            $row['suite_phase_status'] = $phaseStatus;
            $row['suite_phase_evidence'] = $phaseEvidence;
            $row['blocker_ids'] = $rowBlockers;
            $phaseRows[] = $row;
        }

        sort($preparedPhases, SORT_STRING);
        sort($preservedPhases, SORT_STRING);
        sort($blockedPhases, SORT_STRING);
        $coveredPhases = array_values(array_unique(array_merge($preparedPhases, $preservedPhases)));
        $missingPhases = array_values(array_diff($expectedPhases, $coveredPhases));
        $duplicatePhases = array_keys($duplicatePhaseIds);
        sort($duplicatePhases, SORT_STRING);

        if ($missingPhases !== []) {
            $phaseBlockers[] = [
                'id' => 'current-source-next157-164-suite-phases-incomplete',
                'unit' => 'upstream-runner-suite-evidence-current-source-next157-164',
                'suite_phase_id' => implode(',', $missingPhases),
                'evidence' => 'missing prepared suite phases: ' . implode(', ', $missingPhases),
            ];
        }

        $baseBlockers = [];
        foreach (is_array($record['blockers'] ?? null) ? $record['blockers'] : [] as $blocker) {
            if (!is_array($blocker)) {
                continue;
            }
            $evidence = is_string($blocker['evidence'] ?? null) ? $blocker['evidence'] : '';
            if ($evidence === 'suite-phase-outside-prepared-octet'
                || str_contains($evidence, 'missing prepared suite phases: prepared-manifest')
                || str_contains($evidence, 'missing prepared suite phases: prepared-runner')
                || str_contains($evidence, 'missing prepared suite phases: prepared-artifacts')
                || str_contains($evidence, 'missing prepared suite phases: prepared-provenance')
                || str_contains($evidence, 'missing prepared suite phases: prepared-pass-lines')
                || str_contains($evidence, 'missing prepared suite phases: prepared-current-source')
                || str_contains($evidence, 'missing prepared suite phases: prepared-blockers')
                || str_contains($evidence, 'missing prepared suite phases: prepared-handoff')) {
                continue;
            }
            $baseBlockers[] = $blocker;
        }

        $blockers = array_merge($baseBlockers, $phaseBlockers);
        $blocked = $blockers !== [];
        $mappedDelta = !$blocked && $missingPhases === [] && $preparedPhases !== [] ? count($preparedPhases) : 0;
        $phpAdmission = is_array($record['php_pass_admission'] ?? null) ? $record['php_pass_admission'] : [];
        $phpPassDelta = !$blocked ? (int) ($phpAdmission['pass_delta'] ?? $record['php_pass_delta'] ?? 0) : 0;
        $testsTotalDelta = 0;
        if (!$blocked) {
            foreach ($phaseRows as $phaseRow) {
                if (($phaseRow['movement'] ?? null) !== 'next-source-admitted') {
                    continue;
                }
                foreach ($artifactRows as $candidate) {
                    if (is_array($candidate) && ($candidate['unit'] ?? null) === ($phaseRow['unit'] ?? null)) {
                        $testsTotalDelta += max(0, (int) ($candidate['next_tests'] ?? 0) - (int) ($candidate['current_tests'] ?? 0));
                        break;
                    }
                }
            }
        }

        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-source-next157-164-upstream-suite-evidence-prepared';
        } elseif (!$blocked) {
            $status = 'current-source-next157-164-upstream-suite-evidence-preserved';
        }

        $record['status'] = $status;
        $record['countable'] = $status === 'current-source-next157-164-upstream-suite-evidence-prepared';
        $record['blockers'] = $blockers;
        $record['blocker_count'] = count($blockers);
        $record['mapped_delta'] = $mappedDelta;
        $record['next_mapped'] = $blocked ? $currentMapped : $currentMapped + $mappedDelta;
        $record['php_pass_delta'] = $phpPassDelta;
        $record['next_php_pass'] = $blocked ? $currentPhpPass : $currentPhpPass + $phpPassDelta;
        $record['tests_total_delta'] = $testsTotalDelta;
        $record['suite_phase_rows'] = $phaseRows;
        $record['prepared_suite_phases'] = $preparedPhases;
        $record['preserved_suite_phases'] = $preservedPhases;
        $record['blocked_suite_phase_ids'] = $blockedPhases;
        $record['missing_suite_phases'] = $missingPhases;
        $record['duplicate_suite_phases'] = $duplicatePhases;
        $record['counts_upstream_runner_final_current_source_next109'] = false;
        $record['counts_upstream_suite_evidence_current_source_full-suite-countability_118'] = false;
        $record['counts_upstream_suite_evidence_current_source_next119_121'] = false;
        $record['counts_upstream_suite_evidence_current_source_rebase-gap_124'] = false;
        $record['counts_upstream_suite_evidence_current_source_next125_132'] = false;
        $record['counts_upstream_suite_evidence_current_source_next133_140'] = false;
        $record['counts_upstream_suite_evidence_current_source_next141_148'] = false;
        $record['counts_upstream_suite_evidence_prepared_octet'] = false;
        foreach ([164, 162, 161, 160, 159, 157, 155] as $priorShard) {
            $record['counts_upstream_veryquick_shard_current_source_next' . $priorShard] = false;
        }
        $record['counts_upstream_veryquick_shard_runner_current_source_next158'] = false;
        $record['counts_upstream_runner_release_admission_current_source_next114'] = false;
        $record['counts_upstream_runner_full_suite_countability'] = false;
        $record['counts_upstream_runner_countability_current_source_next118'] = false;
        $record['counts_upstream_suite_evidence_current_source_next157_164'] = $status === 'current-source-next157-164-upstream-suite-evidence-prepared';
        $record['counts_release_parity'] = false;
        $record['next_gate'] = $status === 'current-source-next157-164-upstream-suite-evidence-prepared'
            ? 'publish only the isolated current-source next157-164 upstream-suite evidence octet and exact focused PASS-line movement; release/all parity remains blocked'
            : 'keep current-source next157-164 suite evidence uncounted until all eight prepared phases, current-source-only flags, lane-local notes, duplicate-runner state, and focused PASS-line gates are clear';
        $record['dependency_closure'] = 'no new support component needed; current-source next157-164 suite evidence composes the merged prepared-octet evidence with eight prepared current-source-only suite phases and focused TestRunner PASS-line output only';

        return $record;
    }

    /**
     * @param array<int|string, array<string, mixed>> $artifactRows
     * @return array<string, mixed>
     */
    public function upstreamRunnerReleaseAdmission(
        array $artifactRows,
        int $currentMapped,
        int $currentPhpPass,
        string $launcherBaseHead,
        string $dashboardSourceHead,
        string $statusSourceHead,
        string $implementationSourceHead,
        string $nextSourceHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        $record = $this->upstreamRunnerSuiteEvidenceRebase(
            $artifactRows,
            $currentMapped,
            $currentPhpPass,
            $launcherBaseHead,
            $dashboardSourceHead,
            $statusSourceHead,
            $implementationSourceHead,
            $nextSourceHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta,
            $processSnapshot
        );

        $admissionRows = [];
        $admittedDecisions = [];
        $preservedDecisions = [];
        $blockedDecisions = [];
        $admissionBlockers = [];

        foreach (is_array($record['entries'] ?? null) ? $record['entries'] : [] as $entry) {
            if (!is_array($entry)) {
                continue;
            }

            $unit = is_string($entry['unit'] ?? null) ? $entry['unit'] : '';
            $source = null;
            foreach ($artifactRows as $candidate) {
                if (is_array($candidate) && ($candidate['unit'] ?? null) === $unit) {
                    $source = $candidate;
                    break;
                }
            }

            $decisionId = is_array($source) && is_string($source['release_admission_id'] ?? null) && $source['release_admission_id'] !== ''
                ? $source['release_admission_id']
                : $unit;
            $decisionStatus = is_array($source) && is_string($source['release_admission_status'] ?? null) && $source['release_admission_status'] !== ''
                ? $source['release_admission_status']
                : 'open';
            $decisionReason = is_array($source) && is_string($source['release_admission_reason'] ?? null)
                ? trim($source['release_admission_reason'])
                : '';
            $releaseScope = is_array($source) && is_string($source['release_scope'] ?? null)
                ? trim($source['release_scope'])
                : '';
            $movement = is_string($entry['movement'] ?? null) ? $entry['movement'] : 'open';
            $nextCountable = ($entry['next_countable'] ?? false) === true;
            $currentCountable = ($entry['current_countable'] ?? false) === true;
            $newAdmissionCandidate = $movement === 'next-source-admitted' || ($nextCountable && !$currentCountable);
            $rowBlockers = is_array($entry['blocker_ids'] ?? null) ? $entry['blocker_ids'] : [];

            if ($newAdmissionCandidate) {
                if ($decisionStatus !== 'admitted') {
                    $rowBlockers[] = 'release-admission-status-not-admitted';
                }
                if ($decisionReason === '') {
                    $rowBlockers[] = 'release-admission-reason-missing';
                }
                if ($releaseScope !== 'focused-current-source') {
                    $rowBlockers[] = 'release-scope-not-focused-current-source';
                }
            }
            if ($releaseScope === 'release-all' || (is_array($source) && ($source['counts_release_parity'] ?? false) === true)) {
                $rowBlockers[] = 'release-all-parity-claim-not-allowed';
            }
            if (is_array($source) && ($source['launcher_base_authoritative'] ?? true) !== true) {
                $rowBlockers[] = 'launcher-base-authority-missing';
            }

            $rowBlockers = array_values(array_unique(array_filter($rowBlockers, 'is_string')));
            if ($rowBlockers !== []) {
                $blockedDecisions[] = $decisionId;
                $admissionBlockers[] = [
                    'id' => 'current-source-next114-release-admission-row-blocked',
                    'unit' => $unit,
                    'release_admission_id' => $decisionId,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($movement === 'next-source-admitted') {
                $admittedDecisions[] = $decisionId;
            } elseif ($movement === 'current-source-preserved') {
                $preservedDecisions[] = $decisionId;
            }

            $admissionRows[] = [
                'unit' => $unit,
                'release_admission_id' => $decisionId,
                'release_admission_status' => $decisionStatus,
                'release_admission_reason' => $decisionReason,
                'release_scope' => $releaseScope,
                'movement' => $movement,
                'blocker_ids' => $rowBlockers,
            ];
        }

        sort($admittedDecisions, SORT_STRING);
        sort($preservedDecisions, SORT_STRING);
        sort($blockedDecisions, SORT_STRING);

        $blockers = array_merge(is_array($record['blockers'] ?? null) ? $record['blockers'] : [], $admissionBlockers);
        $blocked = $blockers !== [];
        $mappedDelta = !$blocked && $admittedDecisions !== [] ? 1 : 0;
        $phpPassDelta = !$blocked ? (int) ($record['php_pass_delta'] ?? 0) : 0;
        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-source-next114-upstream-runner-release-admission-countable';
        } elseif (!$blocked) {
            $status = 'current-source-next114-upstream-runner-release-admission-preserved';
        }

        $record['status'] = $status;
        $record['countable'] = $status === 'current-source-next114-upstream-runner-release-admission-countable';
        $record['blocker_count'] = count($blockers);
        $record['blockers'] = $blockers;
        $record['mapped_delta'] = $blocked ? 0 : $mappedDelta;
        $record['next_mapped'] = $blocked ? $currentMapped : $currentMapped + $mappedDelta;
        $record['php_pass_delta'] = $phpPassDelta;
        $record['next_php_pass'] = $blocked ? $currentPhpPass : $currentPhpPass + $phpPassDelta;
        $record['tests_total_delta'] = $blocked ? 0 : (int) ($record['tests_total_delta'] ?? 0);
        $record['release_admission_rows'] = $admissionRows;
        $record['admitted_release_admission_ids'] = $admittedDecisions;
        $record['preserved_release_admission_ids'] = $preservedDecisions;
        $record['blocked_release_admission_ids'] = $blockedDecisions;
        $record['counts_upstream_runner_admission_current_source_next102'] = false;
        $record['counts_upstream_runner_gap_burnup_current_source_next104'] = false;
        $record['counts_upstream_runner_suite_evidence_rebase_current_source_next108'] = false;
        $record['counts_upstream_runner_release_admission_current_source_next114'] = $status === 'current-source-next114-upstream-runner-release-admission-countable';
        $record['counts_release_parity'] = false;
        $record['next_gate'] = $status === 'current-source-next114-upstream-runner-release-admission-countable'
            ? 'publish only the current-source next114 focused release-admission row and exact focused PASS-line movement; release/all parity remains gated on a separate zero-error broad artifact'
            : 'keep current-source next114 release admission uncounted until authoritative launcher-base provenance, focused current-source scope, lane-local zero-error guarded runner rows, duplicate-runner state, and focused PASS-line gates are clear';
        $record['dependency_closure'] = 'no new support component needed; current-source next114 release admission composes lane-local bounded runner artifacts, authoritative launcher Base accepted HEAD provenance, dashboard/status/implementation source heads, active-runner gates, focused-scope release admission decisions, and focused TestRunner PASS-line output only';

        return $record;
    }

