    /**
     * @param list<array<string, mixed>> $rows
     * @return array<string, mixed>
     */
    /**
     * @return array{focused:bool,selected_test_files:int,summary_test_files:int,assertions:int,failures:int,pass_lines:int}
     */
    private function parseFocusedPhpTestOutput(string $output): array
    {
        $focused = preg_match('/Focused test run:\s+(\d+)\s+selected test files \(root lock skipped\)/', $output, $focusedMatch) === 1;
        $summary = preg_match('/\n(\d+)\s+test files,\s+(\d+)\s+assertions,\s+(\d+)\s+failures\s*$/', $output, $summaryMatch) === 1;
        $passLines = preg_match_all('/^PASS(?:\s|$)/m', $output);

        return [
            'focused' => $focused,
            'selected_test_files' => $focused ? (int) $focusedMatch[1] : 0,
            'summary_test_files' => $summary ? (int) $summaryMatch[1] : 0,
            'assertions' => $summary ? (int) $summaryMatch[2] : 0,
            'failures' => $summary ? (int) $summaryMatch[3] : 0,
            'pass_lines' => $passLines === false ? 0 : $passLines,
        ];
    }

    /**
     * @param array{focused:bool,selected_test_files:int,summary_test_files:int,assertions:int,failures:int,pass_lines:int} $parsed
     */
    private function focusedPhpPassAdmissionBlocker(array $parsed): string
    {
        if (!$parsed['focused']) {
            return 'missing focused TestRunner output';
        }
        if ($parsed['selected_test_files'] !== 1 || $parsed['summary_test_files'] !== 1) {
            return 'phpPass admission requires exactly one focused lane test file for this slice';
        }
        if ($parsed['failures'] !== 0) {
            return 'focused TestRunner output contains failures';
        }
        if ($parsed['assertions'] <= 0) {
            return 'focused TestRunner output has no assertions to count';
        }

        return 'focused TestRunner output was not countable';
    }

    /**
     * @param array<string, mixed> $currentDenominator
     * @param array<string, mixed> $nextDenominator
     * @return array<string, mixed>
     */
    public function releaseRunnerDenominatorAudit(
        array $currentDenominator,
        array $nextDenominator,
        int $currentPhpPass,
        string $focusedPath,
        string $testOutput,
        string $nonOverlapNote
    ): array {
        $currentMapped = $this->denominatorAuditInt($currentDenominator, 'mapped');
        $nextMapped = $this->denominatorAuditInt($nextDenominator, 'mapped');
        $currentRunnerCount = $this->denominatorAuditInt($currentDenominator, 'runner_countable_count');
        $nextRunnerCount = $this->denominatorAuditInt($nextDenominator, 'runner_countable_count');
        $currentRunnerBlocked = $this->denominatorAuditInt($currentDenominator, 'runner_blocked_count');
        $nextRunnerBlocked = $this->denominatorAuditInt($nextDenominator, 'runner_blocked_count');
        $currentTotal = $this->denominatorAuditInt($currentDenominator, 'total');
        $nextTotal = $this->denominatorAuditInt($nextDenominator, 'total');

        $phpAdmission = $this->focusedPhpPassAdmission(
            $currentPhpPass,
            $focusedPath,
            $testOutput,
            $nonOverlapNote
        );

        $blockers = [];
        if (($phpAdmission['status'] ?? null) !== 'admitted') {
            $blockers[] = [
                'id' => 'focused-php-pass-not-admitted',
                'evidence' => $phpAdmission['blocker'],
            ];
        }
        if ($currentMapped < 0 || $nextMapped < 0) {
            $blockers[] = [
                'id' => 'mapped-count-missing',
                'evidence' => 'current and next denominator mapped counts must be present and non-negative',
            ];
        } elseif ($nextMapped < $currentMapped) {
            $blockers[] = [
                'id' => 'mapped-count-regressed',
                'evidence' => 'next denominator mapped count is lower than the current accepted baseline',
                'current_mapped' => $currentMapped,
                'next_mapped' => $nextMapped,
            ];
        }
        if ($currentTotal > 0 && $nextTotal > 0 && $nextTotal !== $currentTotal) {
            $blockers[] = [
                'id' => 'denominator-total-changed',
                'evidence' => 'current and next denominator totals differ; refresh the static upstream inventory before publishing movement',
                'current_total' => $currentTotal,
                'next_total' => $nextTotal,
            ];
        }
        if ($currentRunnerCount < 0 || $nextRunnerCount < 0) {
            $blockers[] = [
                'id' => 'runner-count-missing',
                'evidence' => 'current and next runner countable counts must be present and non-negative',
            ];
        } elseif ($nextRunnerCount < $currentRunnerCount) {
            $blockers[] = [
                'id' => 'runner-count-regressed',
                'evidence' => 'next countable runner artifact count is lower than the current accepted baseline',
                'current_runner_countable_count' => $currentRunnerCount,
                'next_runner_countable_count' => $nextRunnerCount,
            ];
        }
        if ($currentRunnerBlocked > 0) {
            $blockers[] = [
                'id' => 'current-runner-evidence-blocked',
                'evidence' => 'current accepted runner evidence still has blocked artifacts and cannot anchor a clean denominator audit',
                'blocked_count' => $currentRunnerBlocked,
            ];
        }
        if ($nextRunnerBlocked > 0) {
            $blockers[] = [
                'id' => 'next-runner-evidence-blocked',
                'evidence' => 'next runner evidence still has stale, failed, active, or missing-log artifacts',
                'blocked_count' => $nextRunnerBlocked,
            ];
        }

        $mappedDelta = max(0, $nextMapped - $currentMapped);
        $runnerDelta = max(0, $nextRunnerCount - $currentRunnerCount);
        $phpDelta = (int) ($phpAdmission['assertion_delta'] ?? 0);
        $status = 'blocked';
        if ($blockers === []) {
            $status = ($mappedDelta > 0 || $runnerDelta > 0 || $phpDelta > 0)
                ? 'countable-current-next34-denominator-movement'
                : 'current-next34-denominator-preserved';
        }

        return [
            'status' => $status,
            'current_total' => $currentTotal,
            'next_total' => $nextTotal,
            'current_mapped' => $currentMapped,
            'next_mapped' => $nextMapped,
            'mapped_delta' => $blockers === [] ? $mappedDelta : 0,
            'current_runner_countable_count' => $currentRunnerCount,
            'next_runner_countable_count' => $nextRunnerCount,
            'runner_countable_delta' => $blockers === [] ? $runnerDelta : 0,
            'current_runner_blocked_count' => $currentRunnerBlocked,
            'next_runner_blocked_count' => $nextRunnerBlocked,
            'php_pass_admission' => $phpAdmission,
            'php_pass_delta' => $blockers === [] ? $phpDelta : 0,
            'next_php_pass' => $blockers === [] ? $currentPhpPass + $phpDelta : $currentPhpPass,
            'counts_dashboard_movement' => $blockers === [] && ($mappedDelta > 0 || $phpDelta > 0),
            'counts_runner_denominator_movement' => $blockers === [] && $runnerDelta > 0,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => $blockers === []
                ? 'publish only the admitted focused phpPass delta and clean current/next runner denominator movement for next34'
                : 'keep next34 denominator movement uncounted until focused TestRunner output, mapped totals, and runner artifact counts are clean',
            'dependency_closure' => 'no new support component needed; current-next34 denominator audit composes lane-local TestRunner output and runner count snapshots only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $burnupRows
     * @return array<string, mixed>
     */
    public function releaseRunnerDenominatorBurnup(
        array $burnupRows,
        string $currentAcceptedHead,
        string $nextAcceptedHead,
        int $currentMapped,
        int $currentPhpPass,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote
    ): array {
        if ($currentAcceptedHead === '' || $nextAcceptedHead === '') {
            throw new \InvalidArgumentException('SQLite release-runner denominator burnup requires current and next accepted HEAD values');
        }
        if ($currentMapped < 0) {
            throw new \InvalidArgumentException('SQLite release-runner denominator burnup requires a non-negative current mapped count');
        }
        if ($burnupRows === []) {
            throw new \InvalidArgumentException('SQLite release-runner denominator burnup requires at least one row');
        }

        $phpAdmission = $this->focusedPhpPassAdmission(
            $currentPhpPass,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote
        );

        $entries = [];
        $blockers = [];
        $mappedUnits = [];
        $preservedUnits = [];
        $openUnits = [];
        $regressedUnits = [];
        $seen = [];
        $evidenceTypes = [];
        $categories = [];
        $nextTests = 0;
        $currentTests = 0;

        foreach ($burnupRows as $label => $row) {
            if (!is_array($row)) {
                $blockers[] = [
                    'id' => 'burnup-row-invalid',
                    'evidence' => 'denominator burnup row is not an array',
                    'label' => is_string($label) ? $label : 'row-' . (string) count($entries),
                ];
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== ''
                ? $row['unit']
                : (is_string($label) ? $label : 'unit-' . (string) count($entries));
            $category = is_string($row['category'] ?? null) && $row['category'] !== ''
                ? $row['category']
                : 'unclassified';
            $currentStatus = is_string($row['current_status'] ?? null) ? $row['current_status'] : 'unmapped';
            $nextStatus = is_string($row['next_status'] ?? null) ? $row['next_status'] : 'unmapped';
            $currentRowMapped = (bool) ($row['current_mapped'] ?? ($currentStatus === 'mapped'));
            $nextRowMapped = (bool) ($row['next_mapped'] ?? ($nextStatus === 'mapped'));
            $evidence = is_string($row['evidence'] ?? null) ? trim($row['evidence']) : '';
            $evidenceType = is_string($row['evidence_type'] ?? null) && $row['evidence_type'] !== ''
                ? $row['evidence_type']
                : 'unspecified';
            $currentRowTests = max(0, (int) ($row['current_tests'] ?? 0));
            $nextRowTests = max(0, (int) ($row['next_tests'] ?? 0));
            $rowBlockers = [];

            if (isset($seen[$unit])) {
                $rowBlockers[] = 'duplicate-denominator-unit';
            }
            $seen[$unit] = true;

            if ($nextRowMapped && $evidence === '') {
                $rowBlockers[] = 'mapped-unit-missing-evidence';
            }
            if ($currentRowMapped && !$nextRowMapped) {
                $rowBlockers[] = 'mapped-unit-regressed';
                $regressedUnits[] = $unit;
            }
            if (is_array($row['blockers'] ?? null)) {
                foreach ($row['blockers'] as $blocker) {
                    if (is_string($blocker) && $blocker !== '') {
                        $rowBlockers[] = $blocker;
                    }
                }
            }
            if (is_string($row['blocker'] ?? null) && $row['blocker'] !== '') {
                $rowBlockers[] = $row['blocker'];
            }

            $movement = 'open';
            if ($nextRowMapped && !$currentRowMapped) {
                $movement = 'newly-mapped';
                $mappedUnits[] = $unit;
            } elseif ($nextRowMapped && $currentRowMapped) {
                $movement = 'preserved';
                $preservedUnits[] = $unit;
            } elseif (!$nextRowMapped && !$currentRowMapped) {
                $openUnits[] = $unit;
            }

            if ($nextRowMapped) {
                $evidenceTypes[$evidenceType] = ($evidenceTypes[$evidenceType] ?? 0) + 1;
                $nextTests += $nextRowTests;
            }
            if ($currentRowMapped) {
                $currentTests += $currentRowTests;
            }
            $categories[$category] = ($categories[$category] ?? 0) + 1;

            $rowBlockers = array_values(array_unique($rowBlockers));
            foreach ($rowBlockers as $blocker) {
                $blockers[] = [
                    'id' => 'denominator-burnup-row-blocked',
                    'unit' => $unit,
                    'evidence' => $blocker,
                ];
            }

            $entries[] = [
                'unit' => $unit,
                'category' => $category,
                'current_status' => $currentStatus,
                'next_status' => $nextStatus,
                'current_mapped' => $currentRowMapped,
                'next_mapped' => $nextRowMapped,
                'movement' => $movement,
                'evidence_type' => $evidenceType,
                'evidence' => $evidence,
                'current_tests' => $currentRowTests,
                'next_tests' => $nextRowTests,
                'blockers' => $rowBlockers,
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'admitted') {
            $blockers[] = [
                'id' => 'focused-php-pass-admission-blocked',
                'evidence' => $phpAdmission['blocker'] ?? 'focused PHP output did not satisfy admission gates',
            ];
        }

        ksort($categories);
        ksort($evidenceTypes);
        sort($mappedUnits);
        sort($preservedUnits);
        sort($openUnits);
        sort($regressedUnits);

        $mappedDelta = count($mappedUnits);
        $nextMapped = $currentMapped + ($blockers === [] ? $mappedDelta : 0);
        $status = 'blocked';
        if ($blockers === [] && $mappedDelta > 0) {
            $status = 'current-next52-denominator-burnup-advanced';
        } elseif ($blockers === [] && count($preservedUnits) > 0) {
            $status = 'current-next52-denominator-preserved';
        }

        return [
            'status' => $status,
            'current_accepted_head' => $currentAcceptedHead,
            'next_accepted_head' => $nextAcceptedHead,
            'row_count' => count($entries),
            'category_count' => count($categories),
            'categories' => $categories,
            'current_mapped' => $currentMapped,
            'next_mapped' => $nextMapped,
            'mapped_delta' => $blockers === [] ? $mappedDelta : 0,
            'newly_mapped_count' => count($mappedUnits),
            'newly_mapped_units' => $mappedUnits,
            'preserved_count' => count($preservedUnits),
            'preserved_units' => $preservedUnits,
            'open_count' => count($openUnits),
            'open_units' => $openUnits,
            'regressed_count' => count($regressedUnits),
            'regressed_units' => $regressedUnits,
            'current_tests_total' => $currentTests,
            'next_tests_total' => $nextTests,
            'tests_total_delta' => max(0, $nextTests - $currentTests),
            'evidence_types' => $evidenceTypes,
            'entries' => $entries,
            'php_pass_admission' => $phpAdmission,
            'php_pass_delta' => $blockers === [] ? (int) ($phpAdmission['assertion_delta'] ?? 0) : 0,
            'next_php_pass' => $blockers === [] ? (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass) : $currentPhpPass,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_denominator_burnup' => $status === 'current-next52-denominator-burnup-advanced',
            'counts_release_parity' => false,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => $status === 'current-next52-denominator-burnup-advanced'
                ? 'publish only the newly mapped current-next52 denominator units and keep release/all parity gated on zero-error runner artifacts'
                : 'keep current-next52 denominator movement uncounted until rows have evidence, no regressions, and focused PHP admission is clean',
            'dependency_closure' => 'no new support component needed; current-next52 denominator burnup composes lane-local mapped-unit rows, evidence labels, and focused PHP TestRunner admission only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $burnupRows
     * @return array<string, mixed>
     */
    public function upstreamReleaseDenominatorBurnup(
        array $burnupRows,
        string $launcherBaseHead,
        string $integrationSourceHead,
        string $nextSourceHead,
        int $currentMapped,
        int $currentPhpPass,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote
    ): array {
        $record = $this->releaseRunnerDenominatorBurnup(
            $burnupRows,
            $launcherBaseHead,
            $nextSourceHead,
            $currentMapped,
            $currentPhpPass,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote
        );

        $expectedLauncherBase = '6b824ac24854056466145761d32a9f27720d286a';
        $expectedIntegrationSource = '8a447f445e5d2fd32fc9fd463117f585d1416551';
        $sourceBlockers = [];

        if ($launcherBaseHead !== $expectedLauncherBase) {
            $sourceBlockers[] = [
                'id' => 'current-source-next119-source-blocked',
                'evidence' => 'launcher-base-head-mismatch',
            ];
        }
        if ($integrationSourceHead !== $expectedIntegrationSource) {
            $sourceBlockers[] = [
                'id' => 'current-source-next119-source-blocked',
                'evidence' => 'integration-source-head-mismatch',
            ];
        }

        $admittedUnits = [];
        $preservedUnits = [];
        $blockedUnits = [];
        $next119Rows = [];
        foreach (is_array($record['entries'] ?? null) ? $record['entries'] : [] as $entry) {
            if (!is_array($entry)) {
                continue;
            }

            $unit = is_string($entry['unit'] ?? null) ? $entry['unit'] : '';
            $source = null;
            foreach ($burnupRows as $candidate) {
                if (is_array($candidate) && ($candidate['unit'] ?? null) === $unit) {
                    $source = $candidate;
                    break;
                }
            }

            $admissionStatus = is_array($source) && is_string($source['release_admission_status'] ?? null)
                ? $source['release_admission_status']
                : '';
            $admissionScope = is_array($source) && is_string($source['release_scope'] ?? null)
                ? $source['release_scope']
                : '';
            $removedBlocker = is_array($source) && is_string($source['removed_blocker'] ?? null)
                ? trim($source['removed_blocker'])
                : '';
            $runnerCommand = is_array($source) && is_string($source['runner_command'] ?? null)
                ? $source['runner_command']
                : '';
            $artifactPath = is_array($source) && is_string($source['artifact_path'] ?? null)
                ? $source['artifact_path']
                : '';
            $movement = is_string($entry['movement'] ?? null) ? $entry['movement'] : 'open';
            $nextMapped = ($entry['next_mapped'] ?? false) === true;
            $currentMappedRow = ($entry['current_mapped'] ?? false) === true;
            $newAdmission = $nextMapped && !$currentMappedRow;
            $rowBlockers = is_array($entry['blockers'] ?? null) ? $entry['blockers'] : [];

            if ($newAdmission) {
                if ($admissionStatus !== 'admitted') {
                    $rowBlockers[] = 'release-admission-status-not-admitted';
                }
                if ($admissionScope !== 'focused-current-source-denominator') {
                    $rowBlockers[] = 'release-scope-not-focused-current-source-denominator';
                }
                if ($removedBlocker === '') {
                    $rowBlockers[] = 'removed-blocker-missing';
                }
                if (!str_starts_with($artifactPath, 'lanes/libsqlite/')) {
                    $rowBlockers[] = 'artifact-path-not-lane-local';
                }
                if (!str_contains($runnerCommand, '--jobs 1') || !str_contains($runnerCommand, '--stop-on-error')) {
                    $rowBlockers[] = 'guarded-runner-command-missing';
                }
            }
            if (is_array($source) && ($source['counts_release_parity'] ?? false) === true) {
                $rowBlockers[] = 'release-all-parity-claim-not-allowed';
            }

            $rowBlockers = array_values(array_unique(array_filter($rowBlockers, 'is_string')));
            if ($rowBlockers !== []) {
                $blockedUnits[] = $unit;
                $sourceBlockers[] = [
                    'id' => 'current-source-next119-denominator-row-blocked',
                    'unit' => $unit,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($newAdmission) {
                $admittedUnits[] = $unit;
            } elseif ($movement === 'preserved') {
                $preservedUnits[] = $unit;
            }

            $entry['release_admission_status'] = $admissionStatus;
            $entry['release_scope'] = $admissionScope;
            $entry['removed_blocker'] = $removedBlocker;
            $entry['artifact_path'] = $artifactPath;
            $entry['runner_command'] = $runnerCommand;
            $entry['blockers'] = $rowBlockers;
            $next119Rows[] = $entry;
        }

        sort($admittedUnits, SORT_STRING);
        sort($preservedUnits, SORT_STRING);
        sort($blockedUnits, SORT_STRING);

        $blockers = array_merge(is_array($record['blockers'] ?? null) ? $record['blockers'] : [], $sourceBlockers);
        $blocked = $blockers !== [];
        $mappedDelta = $blocked ? 0 : count($admittedUnits);
        $status = 'blocked';
        if (!$blocked && $mappedDelta > 0) {
            $status = 'current-source-next119-upstream-release-denominator-burnup-countable';
        } elseif (!$blocked) {
            $status = 'current-source-next119-upstream-release-denominator-burnup-preserved';
        }

        $record['status'] = $status;
        $record['countable'] = $status === 'current-source-next119-upstream-release-denominator-burnup-countable';
        $record['launcher_base_head'] = $launcherBaseHead;
        $record['integration_source_head'] = $integrationSourceHead;
        $record['expected_launcher_base_head'] = $expectedLauncherBase;
        $record['expected_integration_source_head'] = $expectedIntegrationSource;
        $record['entries'] = $next119Rows;
        $record['admitted_units'] = $admittedUnits;
        $record['preserved_units'] = $preservedUnits;
        $record['blocked_units'] = $blockedUnits;
        $record['mapped_delta'] = $mappedDelta;
        $record['next_mapped'] = $blocked ? $currentMapped : $currentMapped + $mappedDelta;
        $record['php_pass_delta'] = $blocked ? 0 : (int) ($record['php_pass_delta'] ?? 0);
        $record['next_php_pass'] = $blocked ? $currentPhpPass : $currentPhpPass + (int) ($record['php_pass_delta'] ?? 0);
        $record['blocker_count'] = count($blockers);
        $record['blockers'] = $blockers;
        $record['counts_denominator_burnup'] = false;
        $record['counts_upstream_release_denominator_burnup_current_source_next119'] = $status === 'current-source-next119-upstream-release-denominator-burnup-countable';
        $record['counts_release_parity'] = false;
        $record['next_gate'] = $status === 'current-source-next119-upstream-release-denominator-burnup-countable'
            ? 'publish only the current-source next119 focused denominator burnup unit; release/all parity stays gated on separate zero-error broad artifacts'
            : 'keep current-source next119 denominator burnup uncounted until launcher-base, integration-source, lane-local guarded artifact, focused-scope admission, and focused PHP gates are clear';
        $record['dependency_closure'] = 'no new support component needed; current-source next119 denominator burnup composes lane-local release-runner rows, authoritative launcher base, integration source provenance, guarded runner command evidence, and focused TestRunner PASS-line admission only';

        return $record;
    }

    /**
     * @param array<int|string, array<string, mixed>> $rows
     * @return array<string, mixed>
     */
    public function releaseRunnerSuiteDenominatorFocusedAdmission(
        array $rows,
        string $currentAcceptedHead,
        string $nextAcceptedHead,
        int $currentMapped,
        int $currentPhpPass,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        int $minimumPhpDelta = 64
    ): array {
        if ($currentAcceptedHead === '' || $nextAcceptedHead === '') {
            throw new \InvalidArgumentException('SQLite current-next64 suite denominator requires current and next accepted HEAD values');
        }
        if ($rows === []) {
            throw new \InvalidArgumentException('SQLite current-next64 suite denominator requires at least one row');
        }
        if ($currentMapped < 0) {
            throw new \InvalidArgumentException('SQLite current-next64 suite denominator requires a non-negative current mapped count');
        }
        if ($minimumPhpDelta < 1) {
            throw new \InvalidArgumentException('SQLite current-next64 suite denominator requires a positive minimum PHP delta');
        }

        $phpAdmission = $this->focusedPhpPassAdmission($currentPhpPass, $focusedPath, $focusedTestOutput, $nonOverlapNote);

        $entries = [];
        $blockers = [];
        $seen = [];
        $tiers = [];
        $newlyCountable = [];
        $preserved = [];
        $open = [];
        $regressed = [];
        $testsBefore = 0;
        $testsAfter = 0;

        foreach ($rows as $label => $row) {
            if (!is_array($row)) {
                $blockers[] = [
                    'id' => 'current-next64-row-invalid',
                    'unit' => is_string($label) ? $label : 'row-' . count($entries),
                    'evidence' => 'suite denominator row is not an array',
                ];
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== '' ? $row['unit'] : (is_string($label) ? $label : 'unit-' . count($entries));
            $tier = is_string($row['tier'] ?? null) && $row['tier'] !== '' ? $row['tier'] : 'unclassified';
            $currentStatus = is_string($row['current_status'] ?? null) ? $row['current_status'] : 'unmapped';
            $nextStatus = is_string($row['next_status'] ?? null) ? $row['next_status'] : 'unmapped';
            $currentCountable = (bool) ($row['current_countable'] ?? ($currentStatus === 'countable' || $currentStatus === 'mapped'));
            $nextCountable = (bool) ($row['next_countable'] ?? ($nextStatus === 'countable' || $nextStatus === 'mapped'));
            $evidence = is_string($row['evidence'] ?? null) ? trim($row['evidence']) : '';
            $command = is_string($row['command'] ?? null) ? trim($row['command']) : '';
            $currentTests = max(0, (int) ($row['current_tests'] ?? 0));
            $nextTests = max(0, (int) ($row['next_tests'] ?? 0));
            $rowBlockers = [];

            if (isset($seen[$unit])) {
                $rowBlockers[] = 'duplicate-suite-denominator-unit';
            }
            $seen[$unit] = true;

            if ($nextCountable && $evidence === '') {
                $rowBlockers[] = 'countable-unit-missing-evidence';
            }
            if ($nextCountable && $command === '') {
                $rowBlockers[] = 'countable-unit-missing-command';
            }
            if ($currentCountable && !$nextCountable) {
                $rowBlockers[] = 'countable-unit-regressed';
                $regressed[] = $unit;
            }
            foreach (is_array($row['blockers'] ?? null) ? $row['blockers'] : [] as $blocker) {
                if (is_string($blocker) && $blocker !== '') {
                    $rowBlockers[] = $blocker;
                }
            }

            if ($nextCountable && !$currentCountable) {
                $newlyCountable[] = $unit;
                $movement = 'newly-countable';
            } elseif ($nextCountable) {
                $preserved[] = $unit;
                $movement = 'preserved';
            } else {
                $open[] = $unit;
                $movement = 'open';
            }

            $tiers[$tier] = ($tiers[$tier] ?? 0) + 1;
            if ($currentCountable) {
                $testsBefore += $currentTests;
            }
            if ($nextCountable) {
                $testsAfter += $nextTests;
            }

            $rowBlockers = array_values(array_unique($rowBlockers));
            foreach ($rowBlockers as $blocker) {
                $blockers[] = [
                    'id' => 'current-next64-row-blocked',
                    'unit' => $unit,
                    'evidence' => $blocker,
                ];
            }

            $entries[] = [
                'unit' => $unit,
                'tier' => $tier,
                'current_status' => $currentStatus,
                'next_status' => $nextStatus,
                'current_countable' => $currentCountable,
                'next_countable' => $nextCountable,
                'movement' => $movement,
                'current_tests' => $currentTests,
                'next_tests' => $nextTests,
                'command' => $command,
                'evidence' => $evidence,
                'blockers' => $rowBlockers,
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'admitted') {
            $blockers[] = [
                'id' => 'focused-php-pass-admission-blocked',
                'evidence' => $phpAdmission['blocker'] ?? 'focused PHP output did not satisfy admission gates',
            ];
        } elseif ((int) ($phpAdmission['assertion_delta'] ?? 0) < $minimumPhpDelta) {
            $blockers[] = [
                'id' => 'focused-php-pass-delta-below-minimum',
                'evidence' => 'current-next64 requires at least ' . $minimumPhpDelta . ' focused assertions',
                'actual' => (int) ($phpAdmission['assertion_delta'] ?? 0),
            ];
        }

        ksort($tiers);
        sort($newlyCountable);
        sort($preserved);
        sort($open);
        sort($regressed);

        $mappedDelta = count($newlyCountable);
        $status = 'blocked';
        if ($blockers === [] && $mappedDelta > 0) {
            $status = 'current-next64-suite-denominator-advanced';
        } elseif ($blockers === []) {
            $status = 'current-next64-suite-denominator-preserved';
        }

        return [
            'status' => $status,
            'current_accepted_head' => $currentAcceptedHead,
            'next_accepted_head' => $nextAcceptedHead,
            'row_count' => count($entries),
            'tier_count' => count($tiers),
            'tiers' => $tiers,
            'current_mapped' => $currentMapped,
            'next_mapped' => $blockers === [] ? $currentMapped + $mappedDelta : $currentMapped,
            'mapped_delta' => $blockers === [] ? $mappedDelta : 0,
            'newly_countable_count' => count($newlyCountable),
            'newly_countable_units' => $newlyCountable,
            'preserved_count' => count($preserved),
            'preserved_units' => $preserved,
            'open_count' => count($open),
            'open_units' => $open,
            'regressed_count' => count($regressed),
            'regressed_units' => $regressed,
            'current_tests_total' => $testsBefore,
            'next_tests_total' => $testsAfter,
            'tests_total_delta' => max(0, $testsAfter - $testsBefore),
            'entries' => $entries,
            'php_pass_admission' => $phpAdmission,
            'php_pass_delta' => $blockers === [] ? (int) ($phpAdmission['assertion_delta'] ?? 0) : 0,
            'next_php_pass' => $blockers === [] ? (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass) : $currentPhpPass,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_suite_denominator_current_next64' => $status === 'current-next64-suite-denominator-advanced',
            'counts_release_parity' => false,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => $status === 'current-next64-suite-denominator-advanced'
                ? 'publish only current-next64 newly countable suite denominator units; keep release/all parity gated on accepted zero-error broad runner artifacts'
                : 'keep current-next64 suite denominator movement uncounted until rows have commands, evidence, no regressions, and focused PHP admission is clean',
            'dependency_closure' => 'no new support component needed; current-next64 suite denominator admission composes lane-local row records and focused PHP TestRunner output only',
        ];
    }

    /**
     * @param array<int|string, array<string, mixed>> $rows
     * @return array<string, mixed>
     */
    public function releaseRunnerSuiteDenominatorCurrentHeadAdmission(
        array $rows,
        string $currentAcceptedHead,
        string $evidenceAcceptedHead,
        int $currentMapped,
        int $currentPhpPass,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        string $processSnapshot = '',
        int $minimumPhpDelta = 66
    ): array {
        if ($currentAcceptedHead === '' || $evidenceAcceptedHead === '') {
            throw new \InvalidArgumentException('SQLite current-next66 suite denominator requires current and evidence accepted HEAD values');
        }
        if ($rows === []) {
            throw new \InvalidArgumentException('SQLite current-next66 suite denominator requires at least one row');
        }
        if ($currentMapped < 0) {
            throw new \InvalidArgumentException('SQLite current-next66 suite denominator requires a non-negative current mapped count');
        }
        if ($minimumPhpDelta < 1) {
            throw new \InvalidArgumentException('SQLite current-next66 suite denominator requires a positive minimum PHP delta');
        }

        $phpAdmission = $this->focusedPhpPassCurrentHeadAdmission(
            $currentPhpPass,
            $currentAcceptedHead,
            $evidenceAcceptedHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote
        );
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $entries = [];
        $blockers = [];
        $tiers = [];
        $seenUnits = [];
        $readyUnits = [];
        $preservedUnits = [];
        $blockedUnits = [];
        $openUnits = [];
        $scriptSet = [];
        $readyTests = 0;
        $preservedTests = 0;

        foreach ($rows as $label => $row) {
            if (!is_array($row)) {
                $unit = is_string($label) ? $label : 'row-' . count($entries);
                $blockedUnits[] = $unit;
                $blockers[] = [
                    'id' => 'current-next66-row-invalid',
                    'unit' => $unit,
                    'evidence' => 'suite denominator row is not an array',
                ];
                continue;
            }

            $unit = is_string($row['unit'] ?? null) && $row['unit'] !== ''
                ? $row['unit']
                : (is_string($label) ? $label : 'unit-' . count($entries));
            $tier = is_string($row['tier'] ?? null) && $row['tier'] !== '' ? $row['tier'] : 'unclassified';
            $status = is_string($row['status'] ?? null) && $row['status'] !== '' ? $row['status'] : 'open';
            $command = is_string($row['command'] ?? null) ? trim($row['command']) : '';
            $artifact = is_string($row['artifact'] ?? null) ? trim($row['artifact']) : '';
            $evidence = is_string($row['evidence'] ?? null) ? trim($row['evidence']) : '';
            $tests = max(0, (int) ($row['tests'] ?? 0));
            $scripts = array_values(array_filter(
                is_array($row['scripts'] ?? null) ? $row['scripts'] : [],
                static fn (mixed $script): bool => is_string($script) && preg_match('/^[A-Za-z0-9_.*-]+\.test$/', $script) === 1
            ));
            sort($scripts, SORT_STRING);
            foreach ($scripts as $script) {
                $scriptSet[$script] = true;
            }

            $rowBlockers = [];
            if (isset($seenUnits[$unit])) {
                $rowBlockers[] = 'duplicate-suite-denominator-unit';
            }
            $seenUnits[$unit] = true;
            if (in_array($status, ['ready', 'preserved'], true) && $command === '') {
                $rowBlockers[] = 'countable-unit-missing-command';
            }
            if (in_array($status, ['ready', 'preserved'], true) && $artifact === '') {
                $rowBlockers[] = 'countable-unit-missing-artifact';
            }
            if (in_array($status, ['ready', 'preserved'], true) && $evidence === '') {
                $rowBlockers[] = 'countable-unit-missing-evidence';
            }
            if (in_array($status, ['ready', 'preserved'], true) && $scripts === []) {
                $rowBlockers[] = 'countable-unit-missing-concrete-script';
            }
            foreach (is_array($row['blockers'] ?? null) ? $row['blockers'] : [] as $blocker) {
                if (is_string($blocker) && $blocker !== '') {
                    $rowBlockers[] = $blocker;
                }
            }
            $rowBlockers = array_values(array_unique($rowBlockers));

            if ($rowBlockers !== []) {
                $movement = 'blocked';
                $blockedUnits[] = $unit;
            } elseif ($status === 'ready') {
                $movement = 'ready';
                $readyUnits[] = $unit;
                $readyTests += $tests;
            } elseif ($status === 'preserved') {
                $movement = 'preserved';
                $preservedUnits[] = $unit;
                $preservedTests += $tests;
            } else {
                $movement = 'open';
                $openUnits[] = $unit;
            }

            $tiers[$tier] = ($tiers[$tier] ?? 0) + 1;
            foreach ($rowBlockers as $blocker) {
                $blockers[] = [
                    'id' => 'current-next66-row-blocked',
                    'unit' => $unit,
                    'evidence' => $blocker,
                ];
            }

            $entries[] = [
                'unit' => $unit,
                'tier' => $tier,
                'status' => $status,
                'movement' => $movement,
                'scripts' => $scripts,
                'script_count' => count($scripts),
                'tests' => $tests,
                'command' => $command,
                'artifact' => $artifact,
                'evidence' => $evidence,
                'blockers' => $rowBlockers,
            ];
        }

        if (($active['status'] ?? null) !== 'clear') {
            $blockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
            ];
        }
        if (($phpAdmission['status'] ?? null) !== 'current-head-focused-pass-countable') {
            $blockers[] = [
                'id' => 'focused-php-pass-admission-blocked',
                'evidence' => 'focused PHP output is not countable at the accepted repository head',
            ];
        } elseif ((int) ($phpAdmission['pass_delta'] ?? 0) < $minimumPhpDelta) {
            $blockers[] = [
                'id' => 'focused-pass-delta-below-minimum',
                'evidence' => 'current-next66 requires at least ' . $minimumPhpDelta . ' focused PASS lines',
                'actual' => (int) ($phpAdmission['pass_delta'] ?? 0),
            ];
        }

        ksort($tiers);
        sort($readyUnits);
        sort($preservedUnits);
        sort($blockedUnits);
        sort($openUnits);
        $scripts = array_keys($scriptSet);
        sort($scripts, SORT_STRING);

        $status = 'blocked';
        if ($blockers === [] && $readyUnits !== []) {
            $status = 'current-next66-suite-denominator-ready';
        } elseif ($blockers === [] && $preservedUnits !== []) {
            $status = 'current-next66-suite-denominator-preserved';
        }

        return [
            'status' => $status,
            'current_accepted_head' => $currentAcceptedHead,
            'evidence_accepted_head' => $evidenceAcceptedHead,
            'row_count' => count($entries),
            'tier_count' => count($tiers),
            'tiers' => $tiers,
            'ready_count' => count($readyUnits),
            'ready_units' => $readyUnits,
            'preserved_count' => count($preservedUnits),
            'preserved_units' => $preservedUnits,
            'open_count' => count($openUnits),
            'open_units' => $openUnits,
            'blocked_count' => count($blockedUnits),
            'blocked_units' => $blockedUnits,
            'script_count' => count($scripts),
            'scripts' => $scripts,
            'ready_tests' => $readyTests,
            'preserved_tests' => $preservedTests,
            'entries' => $entries,
            'current_mapped' => $currentMapped,
            'next_mapped' => $currentMapped,
            'mapped_delta' => 0,
            'counts_release_parity' => false,
            'php_pass_admission' => $phpAdmission,
            'php_pass_delta' => $blockers === [] ? (int) ($phpAdmission['pass_delta'] ?? 0) : 0,
            'next_php_pass' => $blockers === [] ? (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass) : $currentPhpPass,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_suite_denominator_current_next66' => $status === 'current-next66-suite-denominator-ready',
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => $status === 'current-next66-suite-denominator-ready'
                ? 'publish the current-next66 focused PASS-line delta and keep mapped coverage/release-all parity unchanged until a fresh broad zero-error artifact exists'
                : 'repair current-next66 row evidence, duplicate-runner state, or accepted-head focused PASS admission before counting this denominator gate',
            'dependency_closure' => 'no new support component needed; current-next66 suite denominator admission reuses lane-local row records, accepted-head TestRunner PASS lines, and duplicate-runner process gating only',
        ];
    }

    /**
     * @param array<string, mixed> $row
     */
    private function denominatorAuditInt(array $row, string $key): int
    {
        $value = $row[$key] ?? null;
        if (is_int($value)) {
            return $value;
        }
        if (is_string($value) && preg_match('/^-?\d+$/', $value) === 1) {
            return (int) $value;
        }

        return -1;
    }

    /**
     * @param array<int|string, array<string, mixed>> $gapRows
     * @return array<string, mixed>
     */
    public function releaseRunnerDenominatorGapBurnup(
        array $gapRows,
        string $currentAcceptedHead,
        string $nextAcceptedHead,
        int $currentPhpPass,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        string $processSnapshot = ''
    ): array {
        if ($currentAcceptedHead === '' || $nextAcceptedHead === '') {
            throw new \InvalidArgumentException('SQLite denominator gap burnup requires current and next accepted HEAD values');
        }
        if ($gapRows === []) {
            throw new \InvalidArgumentException('SQLite denominator gap burnup requires at least one gap row');
        }

        $phpAdmission = $this->focusedPhpPassAdmission(
            $currentPhpPass,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote
        );
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $entries = [];
        $blockers = [];
        $buckets = [];
        $readyIds = [];
        $advancedIds = [];
        $preservedIds = [];
        $blockedIds = [];
        $regressedIds = [];
        $targetScripts = [];
        $currentMappedTotal = 0;
        $nextMappedTotal = 0;
        $currentScriptTotal = 0;
        $nextScriptTotal = 0;
        $denominatorTotal = 0;

        foreach ($gapRows as $label => $row) {
            if (!is_array($row)) {
                $id = is_string($label) ? $label : 'gap-' . (string) count($entries);
                $blockedIds[] = $id;
                $blockers[] = [
                    'id' => 'denominator-gap-row-invalid',
                    'gap_id' => $id,
                    'evidence' => 'denominator gap row is not an array',
                ];
                continue;
            }

            $id = is_string($row['id'] ?? null) && $row['id'] !== ''
                ? $row['id']
                : (is_string($label) ? $label : 'gap-' . (string) count($entries));
            $bucket = is_string($row['bucket'] ?? null) && $row['bucket'] !== '' ? $row['bucket'] : 'unclassified';
            $currentMapped = max(0, $this->denominatorAuditInt($row, 'current_mapped'));
            $nextMapped = max(0, $this->denominatorAuditInt($row, 'next_mapped'));
            $currentScripts = max(0, $this->denominatorAuditInt($row, 'current_countable_scripts'));
            $nextScripts = max(0, $this->denominatorAuditInt($row, 'next_countable_scripts'));
            $rowTotal = max(0, $this->denominatorAuditInt($row, 'denominator_total'));
            $scripts = array_values(array_filter(
                is_array($row['scripts'] ?? null) ? $row['scripts'] : [],
                static fn (mixed $script): bool => is_string($script) && str_ends_with($script, '.test')
            ));
            sort($scripts, SORT_STRING);
            foreach ($scripts as $script) {
                $targetScripts[$script] = true;
            }

            $rowBlockers = [];
            if ($nextMapped < $currentMapped) {
                $rowBlockers[] = 'mapped-count-regressed';
            }
            if ($nextScripts < $currentScripts) {
                $rowBlockers[] = 'countable-script-count-regressed';
            }
            if (($row['hydrated'] ?? true) !== true) {
                $rowBlockers[] = 'gap-scripts-not-hydrated';
            }
            if (($row['next_artifact_present'] ?? false) === true) {
                $rowBlockers[] = 'next-artifact-already-present';
            }
            if (is_array($row['blockers'] ?? null)) {
                foreach ($row['blockers'] as $blocker) {
                    if (is_string($blocker) && $blocker !== '') {
                        $rowBlockers[] = $blocker;
                    }
                }
            }
            if (is_string($row['blocker'] ?? null) && $row['blocker'] !== '') {
                $rowBlockers[] = $row['blocker'];
            }
            $rowBlockers = array_values(array_unique($rowBlockers));

            $mappedDelta = $nextMapped - $currentMapped;
            $scriptDelta = $nextScripts - $currentScripts;
            $movement = 'open';
            if ($rowBlockers !== []) {
                $movement = 'blocked';
                $blockedIds[] = $id;
                if (in_array('mapped-count-regressed', $rowBlockers, true) || in_array('countable-script-count-regressed', $rowBlockers, true)) {
                    $regressedIds[] = $id;
                }
                $blockers[] = [
                    'id' => 'denominator-gap-row-blocked',
                    'gap_id' => $id,
                    'evidence' => implode('; ', $rowBlockers),
                ];
            } elseif ($mappedDelta > 0 || $scriptDelta > 0) {
                $movement = 'advanced';
                $advancedIds[] = $id;
                $readyIds[] = $id;
            } else {
                $movement = 'preserved';
                $preservedIds[] = $id;
            }

            if (!isset($buckets[$bucket])) {
                $buckets[$bucket] = [
                    'bucket' => $bucket,
                    'rows' => 0,
                    'advanced' => 0,
                    'preserved' => 0,
                    'blocked' => 0,
                    'current_mapped' => 0,
                    'next_mapped' => 0,
                    'mapped_delta' => 0,
                    'current_countable_scripts' => 0,
                    'next_countable_scripts' => 0,
                    'script_delta' => 0,
                    'denominator_total' => 0,
                ];
            }
            $buckets[$bucket]['rows']++;
            $buckets[$bucket][$movement]++;
            $buckets[$bucket]['current_mapped'] += $currentMapped;
            $buckets[$bucket]['next_mapped'] += $nextMapped;
            $buckets[$bucket]['mapped_delta'] += max(0, $mappedDelta);
            $buckets[$bucket]['current_countable_scripts'] += $currentScripts;
            $buckets[$bucket]['next_countable_scripts'] += $nextScripts;
            $buckets[$bucket]['script_delta'] += max(0, $scriptDelta);
            $buckets[$bucket]['denominator_total'] += $rowTotal;

            $currentMappedTotal += $currentMapped;
            $nextMappedTotal += $nextMapped;
            $currentScriptTotal += $currentScripts;
            $nextScriptTotal += $nextScripts;
            $denominatorTotal += $rowTotal;

            $entries[] = [
                'id' => $id,
                'bucket' => $bucket,
                'status' => $movement,
                'current_mapped' => $currentMapped,
                'next_mapped' => $nextMapped,
                'mapped_delta' => $mappedDelta,
                'current_countable_scripts' => $currentScripts,
                'next_countable_scripts' => $nextScripts,
                'script_delta' => $scriptDelta,
                'denominator_total' => $rowTotal,
                'scripts' => $scripts,
                'blocker_ids' => $rowBlockers,
            ];
        }

        if (($phpAdmission['status'] ?? null) !== 'admitted') {
            $blockers[] = [
                'id' => 'focused-php-pass-admission-blocked',
                'evidence' => $phpAdmission['blocker'] ?? 'focused PHP output did not satisfy admission gates',
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $blockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
            ];
        }

        ksort($buckets, SORT_STRING);
        sort($readyIds, SORT_STRING);
        sort($advancedIds, SORT_STRING);
        sort($preservedIds, SORT_STRING);
        sort($blockedIds, SORT_STRING);
        sort($regressedIds, SORT_STRING);
        $targetScripts = array_keys($targetScripts);
        sort($targetScripts, SORT_STRING);

        $mappedDeltaTotal = $nextMappedTotal - $currentMappedTotal;
        $scriptDeltaTotal = $nextScriptTotal - $currentScriptTotal;
        $status = 'blocked';
        if ($blockers === [] && ($mappedDeltaTotal > 0 || $scriptDeltaTotal > 0)) {
            $status = 'current-next53-denominator-burnup-ready';
        } elseif ($blockers === [] && $mappedDeltaTotal === 0 && $scriptDeltaTotal === 0) {
            $status = 'current-next53-denominator-preserved';
        } elseif ($advancedIds !== [] && $regressedIds === []) {
            $status = 'current-next53-denominator-burnup-partial';
        }

        return [
            'status' => $status,
            'current_accepted_head' => $currentAcceptedHead,
            'next_accepted_head' => $nextAcceptedHead,
            'row_count' => count($entries),
            'bucket_count' => count($buckets),
            'denominator_total' => $denominatorTotal,
            'current_mapped_total' => $currentMappedTotal,
            'next_mapped_total' => $nextMappedTotal,
            'mapped_delta_total' => $blockers === [] ? max(0, $mappedDeltaTotal) : 0,
            'current_countable_script_total' => $currentScriptTotal,
            'next_countable_script_total' => $nextScriptTotal,
            'countable_script_delta_total' => $blockers === [] ? max(0, $scriptDeltaTotal) : 0,
            'burnup_percent' => $denominatorTotal > 0 ? round(($nextMappedTotal / $denominatorTotal) * 100, 2) : 0.0,
            'advanced_count' => count($advancedIds),
            'preserved_count' => count($preservedIds),
            'blocked_count' => count($blockedIds),
            'regressed_count' => count($regressedIds),
            'ready_gap_ids' => $readyIds,
            'advanced_gap_ids' => $advancedIds,
            'preserved_gap_ids' => $preservedIds,
            'blocked_gap_ids' => $blockedIds,
            'regressed_gap_ids' => $regressedIds,
            'target_script_count' => count($targetScripts),
            'target_scripts' => $targetScripts,
            'buckets' => array_values($buckets),
            'entries' => $entries,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'php_pass_admission' => $phpAdmission,
            'php_pass_delta' => $blockers === [] ? (int) ($phpAdmission['assertion_delta'] ?? 0) : 0,
            'next_php_pass' => $blockers === [] ? (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass) : $currentPhpPass,
            'blocker_count' => count($blockers),
            'blockers' => $blockers,
            'counts_denominator_gap_burnup' => $status === 'current-next53-denominator-burnup-ready',
            'counts_release_parity' => false,
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => match ($status) {
                'current-next53-denominator-burnup-ready' => 'publish the admitted current-next53 denominator burnup rows and launch only the remaining ready focused runner scripts through the guarded runner',
                'current-next53-denominator-preserved' => 'preserve current denominator coverage without claiming new mapped movement',
                'current-next53-denominator-burnup-partial' => 'preserve advanced rows but repair blocked or duplicate-runner evidence before counting current-next53 movement',
                default => 'keep denominator burnup uncounted until regressed rows, duplicate runners, and focused PHP admission blockers are repaired',
            },
            'dependency_closure' => 'no new support component needed; current-next53 denominator burnup composes lane-local gap rows, script counts, active-runner gates, and focused PHP TestRunner admission only',
        ];
    }

    public function upstreamVeryquickShardCurrentSourceShard(
        int $shard,
        array $rows,
        int $currentMapped,
        int $currentPhpPass,
        string $launcherBaseHead,
        string $dashboardSourceHead,
        string $statusSourceHead,
        string $implementationSourceHead,
        string $nextSourceHead,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        ?int $expectedPassDelta = null,
        string $processSnapshot = ''
    ): array {
        if ($shard < 1) {
            throw new \InvalidArgumentException('Upstream veryquick shard id must be a positive integer');
        }

        return $this->upstreamVeryquickShardCurrentSourceEvidence(
            $shard,
            $rows,
            $currentMapped,
            $currentPhpPass,
            $launcherBaseHead,
            $dashboardSourceHead,
            $statusSourceHead,
            $implementationSourceHead,
            $nextSourceHead,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote,
            $expectedPassDelta,
            $processSnapshot
        );
    }

    /**
     * @param list<string> $scripts
     * @return array<string, mixed>
     */
    public function focusedSubsetPlan(array $scripts, ?string $repoRoot = null): array
    {
        return $this->buildFocusedSubsetPlan($scripts, 1, $repoRoot);
    }

    /**
     * @param array<int, array<string, mixed>> $artifacts
     * @return array<string, mixed>
     */
    public function upstreamSuiteReleaseGateEvidence(
        array $artifacts,
        string $acceptedHead,
        int $currentPhpPass,
        string $focusedPath,
        string $focusedTestOutput,
        string $nonOverlapNote,
        string $processSnapshot = ''
    ): array {
        if ($acceptedHead === '') {
            throw new \InvalidArgumentException('SQLite current-next60 release gate requires an accepted HEAD value');
        }

        $phpAdmission = $this->focusedPhpPassAdmission(
            $currentPhpPass,
            $focusedPath,
            $focusedTestOutput,
            $nonOverlapNote
        );
        $active = $this->activeFullSuiteRunnerGate($processSnapshot);

        $countable = [];
        $blocked = [];
        $tierCounts = [];
        $testTotal = 0;
        $errorTotal = 0;
        $requestedScripts = [];

        foreach ($artifacts as $index => $artifact) {
            $id = is_string($artifact['id'] ?? null) && $artifact['id'] !== ''
                ? $artifact['id']
                : 'artifact-' . $index;
            $requested = is_array($artifact['requested'] ?? null) ? $artifact['requested'] : [];
            $results = is_array($artifact['results'] ?? null) ? $artifact['results'] : [];
            $tier = is_string($requested['testset'] ?? null) ? $requested['testset'] : 'unknown';
            $patterns = is_array($requested['patterns'] ?? null) ? $requested['patterns'] : [];
            $repositoryHead = is_string($artifact['repository_head'] ?? null) ? $artifact['repository_head'] : '';
            $status = is_string($artifact['status'] ?? null) ? $artifact['status'] : 'unknown';
            $exit = array_key_exists('exit', $results) ? (int) $results['exit'] : null;
            $tests = array_key_exists('tests', $results) ? (int) $results['tests'] : 0;
            $errors = array_key_exists('errors', $results) ? (int) $results['errors'] : 0;

            foreach ($patterns as $pattern) {
                if (is_string($pattern) && str_ends_with($pattern, '.test')) {
                    $requestedScripts[$pattern] = true;
                }
            }

            $artifactBlockers = [];
            if ($repositoryHead !== $acceptedHead) {
                $artifactBlockers[] = 'artifact-head-mismatch';
            }
            if (!in_array($tier, ['all', 'release'], true)) {
                $artifactBlockers[] = 'not-release-or-all-tier';
            }
            if ($status !== 'passed' || $exit !== 0 || $errors !== 0 || $tests <= 0) {
                $artifactBlockers[] = 'artifact-not-zero-error';
            }

            $row = [
                'id' => $id,
                'tier' => $tier,
                'repository_head' => $repositoryHead,
                'status' => $artifactBlockers === [] ? 'countable' : 'blocked',
                'tests' => $tests,
                'errors' => $errors,
                'exit' => $exit,
                'patterns' => array_values(array_filter($patterns, 'is_string')),
                'blocker_ids' => $artifactBlockers,
            ];

            if ($artifactBlockers === []) {
                $countable[] = $row;
                $tierCounts[$tier] = ($tierCounts[$tier] ?? 0) + 1;
                $testTotal += $tests;
                $errorTotal += $errors;
            } else {
                $blocked[] = $row;
            }
        }

        ksort($tierCounts, SORT_STRING);
        $scriptList = array_keys($requestedScripts);
        sort($scriptList, SORT_STRING);

        $globalBlockers = [];
        if ($countable === []) {
            $globalBlockers[] = [
                'id' => 'no-countable-release-artifact',
                'evidence' => 'no accepted-HEAD zero-error release/all artifact was supplied for current-next60',
            ];
        }
        if (($active['status'] ?? null) !== 'clear') {
            $globalBlockers[] = [
                'id' => 'duplicate-broad-runner-active',
                'evidence' => (string) ($active['active_count'] ?? 0) . ' active broad runner process(es) detected',
            ];
        }
        if (($phpAdmission['status'] ?? null) !== 'admitted') {
            $globalBlockers[] = [
                'id' => 'focused-php-pass-admission-blocked',
                'evidence' => $phpAdmission['blocker'] ?? 'focused PHP output did not satisfy admission gates',
            ];
        }

        $status = $globalBlockers === [] && $blocked === []
            ? 'current-next60-release-gate-countable'
            : ($countable !== [] && ($phpAdmission['status'] ?? null) === 'admitted' ? 'current-next60-release-gate-partial' : 'blocked');

        return [
            'status' => $status,
            'accepted_head' => $acceptedHead,
            'artifact_count' => count($artifacts),
            'countable_artifact_count' => count($countable),
            'blocked_artifact_count' => count($blocked),
            'countable_test_total' => $testTotal,
            'countable_error_total' => $errorTotal,
            'tier_counts' => $tierCounts,
            'requested_script_count' => count($scriptList),
            'requested_scripts' => $scriptList,
            'countable_artifacts' => $countable,
            'blocked_artifacts' => $blocked,
            'active_runner_status' => $active['status'] ?? 'unknown',
            'active_runner_count' => (int) ($active['active_count'] ?? 0),
            'php_pass_admission' => $phpAdmission,
            'php_pass_delta' => $status === 'blocked' ? 0 : (int) ($phpAdmission['assertion_delta'] ?? 0),
            'next_php_pass' => $status === 'blocked' ? $currentPhpPass : (int) ($phpAdmission['next_php_pass'] ?? $currentPhpPass),
            'global_blocker_count' => count($globalBlockers),
            'global_blockers' => $globalBlockers,
            'counts_release_parity' => $status === 'current-next60-release-gate-countable',
            'counts_runner_blocker_removal' => $status !== 'blocked' && $countable !== [],
            'non_overlap_note' => trim($nonOverlapNote),
            'next_gate' => match ($status) {
                'current-next60-release-gate-countable' => 'publish the accepted-HEAD zero-error release/all artifact as current-next60 countable release evidence',
                'current-next60-release-gate-partial' => 'preserve the countable accepted-HEAD artifact but keep blocked/stale artifacts uncounted until repaired',
                default => 'do not count current-next60 release evidence until a zero-error accepted-HEAD artifact, clear active-runner gate, and focused PHP admission are all present',
            },
            'dependency_closure' => 'no new support component needed; current-next60 release gate composes accepted-head bounded runner artifact records, duplicate-runner gates, and focused PHP TestRunner admission only',
        ];
    }

    /**
     * @param array<string, list<string>> $groups
     * @return array<string, array<string, mixed>>
     */
    public function focusedSubsetMatrix(array $groups, int $jobs = 1, ?string $repoRoot = null): array
    {
        if ($jobs < 1) {
            throw new \InvalidArgumentException('Focused upstream subset jobs must be at least 1');
        }

        $matrix = [];
        foreach ($groups as $name => $scripts) {
            if (!is_string($name) || $name === '') {
                throw new \InvalidArgumentException('Focused upstream subset group names must be non-empty strings');
            }

            $matrix[$name] = $this->buildFocusedSubsetPlan($scripts, $jobs, $repoRoot);
        }

        return $matrix;
    }

    /**
     * @param list<string> $scripts
     * @return array<string, mixed>
     */
    public function focusedSubsetRunRecord(
        string $name,
        array $scripts,
        int $jobs = 1,
        ?string $repoRoot = null,
        ?string $result = null
    ): array {
        if ($name === '') {
            throw new \InvalidArgumentException('Focused upstream subset run name must be non-empty');
        }

        $plan = $this->buildFocusedSubsetPlan($scripts, $jobs, $repoRoot);
        $parsed = $this->parseVeryquickResult($result);
        $completed = $result !== null && $parsed['scripts'] > 0;

        return [
            'name' => $name,
            'status' => $completed ? ($parsed['errors'] === 0 ? 'passed' : 'failed') : ($plan['runnable'] ? 'ready' : 'skipped'),
            'command' => $plan['command'],
            'scripts' => $plan['scripts'],
            'script_count' => $plan['script_count'],
            'jobs' => $plan['jobs'],
            'runnable' => $plan['runnable'],
            'skip_reason' => $completed || $plan['runnable'] ? null : $plan['skip_reason'],
            'result' => $result,
            'result_scripts' => $parsed['scripts'],
            'result_tests' => $parsed['tests'],
            'result_errors' => $parsed['errors'],
        ];
    }

    /**
     * @param list<string> $scripts
     * @return array<string, mixed>
     */
    private function buildFocusedSubsetPlan(array $scripts, int $jobs, ?string $repoRoot): array
    {
        $denominator = $this->manifest['benchmarkDenominator'] ?? [];
        $runner = is_array($denominator) && is_array($denominator['runnerStatus'] ?? null)
            ? $denominator['runnerStatus']
            : [];
        $buildDirectory = is_string($runner['buildDirectory'] ?? null)
            ? $runner['buildDirectory']
            : '.upstream-cache/libsqlite-build-port-libsqlite';

        $root = $repoRoot ?? dirname(__DIR__, 3);
        $absoluteBuildDirectory = $root . '/' . $buildDirectory;
        $testfixture = $absoluteBuildDirectory . '/testfixture';
        $testrunner = $root . '/.upstream-cache/libsqlite/test/testrunner.tcl';
        $normalizedScripts = [];
        foreach ($scripts as $script) {
            if (
                !is_string($script)
                || str_starts_with($script, '/')
                || !preg_match('/^[A-Za-z0-9_.*?\/-]+\.test$/', $script)
            ) {
                throw new \InvalidArgumentException('Focused upstream subset scripts must be SQLite .test names');
            }
            $normalizedScripts[] = $script;
        }

        $command = 'cd ' . $buildDirectory
            . ' && ./testfixture ../libsqlite/test/testrunner.tcl --jobs ' . $jobs . ' --stop-on-error veryquick';
        if ($normalizedScripts !== []) {
            $command .= ' ' . implode(' ', $normalizedScripts);
        }

        $missing = $this->missingRunnerInputs($absoluteBuildDirectory, $testfixture, $testrunner, $buildDirectory);

        return [
            'command' => $command,
            'scripts' => $normalizedScripts,
            'script_count' => count($normalizedScripts),
            'jobs' => $jobs,
            'runnable' => $missing === [],
            'skip_reason' => $missing === [] ? null : 'upstream cache/testfixture not hydrated in this worktree: missing ' . implode(', ', $missing),
        ];
    }
}
